window.HB_TR["matthew"]["ks"]=["1. حضرت عیسیٰ مسیح سٕنزِ نسلہٕ سٕنز کتاب، یُس داؤد سُند نیچو، یُس ابراہیم سُند نیچو چُھ۔ \n2. ابراہیم زاے اسحاق تہٕ اسحاق زاے یعقوب۔ تہٕ یعقوب زاے یہوداہ تہٕ تٔمۍ سٕندِس بٲے ۔ \n3.\\tتہٕ یہوداہ زاے فارس تہٕ زارا ثمر۔ تہٕ فارس زٲوۍ ایسروم۔ تہٕ ایسرومس زاے عارم۔ \n4.\\tتہٕ اَمَن دَب زاے اَمینادب۔ تہٕ اَمیناداب زاے نَسَن؛ تہٕ نَسَن زاے سالمَن۔ \n5. تہٕ سالمن زاے رچبُک بُز۔ تہٕ بوز زاے روتھ سُند عبید۔ تہٕ عبید زاے یسی۔ \n6.\\tتہٕ یسیٰ دیت داؤد بادشاہ۔ تہٕ داؤد بادشاہن زاو سُلیمانس سٍتـ̡ یُس یوریاس سٕنزِ زنانہٕ ٲس۔ \n7. تہٕ سُلیمان زاے روبعام۔ تہٕ روبوعم زاے عبیا۔ تہٕ ابیاہن دیت عسا۔ \n8. تہٕ آسا زاو جوسفات۔ تہٕ جوسفات زاو جورام۔ تہٕ جورامن زاو اوزیاس۔ \n9. تہٕ اوزیاس زاے جوتھم زٲو۔ تہٕ جوتھم زاو اچاز تہٕ عچاز زاے حزقیاس۔ \n10. تہٕ حزقیاسن زٲو ماناسس۔ تہٕ ماناسیس زاے آمون۔ تہٕ آمون زاے جوسیاس۔ \n11.\\tتہٕ یوسیاس دیت یکونیا تہٕ تٔمۍ سٕندِس بٲے زٲوِتھ، ییمہِ وِزِ تِم بابل نِنہٕ آو: {جوسیاس...: کینہہ پٔرۍ، یوسیاس پیوو یعقوب تہٕ یعقوب زٲوِتھ یعقوبیاس}\n12.\\tتہٕ ییلہ تِم بابل اننہٕ آو، یکونیاسن زٲو سالتھییل۔ تہٕ سالتھیلن زٲو زوروبابیل۔ \n13.\\tتہٕ زوروبابیل زٲو ابیعید۔ تہٕ ابیعیدس زاو الیاقیم۔ تہٕ الیاقیم زٲو آزور۔ \n14. تہٕ آزورن دِژ سدوک۔ تہٕ سَدوقَن زاے اَخِم۔ تہٕ اَخِم زاے ایلیوڈ۔ \n15.\\tتہٕ الیعزارن پیدہ الیعزر۔ تہٕ الیعزارن پیدہ متھان۔ تہٕ متھنن زٲو یعقوب۔ \n16.\\tتہٕ یعقوب زاو یوسف مریم سُند خانٛدار، یٔمِس عیسیٰ اوس زامُت، یٔمِس مسیح ونان چھِ۔ \n17. یێلہِ چھِ ابراہیم سٍتـ̡ داؤدس تام ژۅداہ نسلہٕ۔ تہٕ داؤد سٍتـ̡ بابل تام ژۄداہ نسلہٕ۔ تہٕ بابل نِنہٕ پى۪ٹھٕ مسیحس تام ژۄداہ نسلہٕ۔ \n18.\\tوُن اوس عیسیٰ مسیح سُند زٮ۪نہٕ یِتھٕ پٲٹھۍ: یێلہِ تٔمۍ سٕنزِ موج مریم یوسف سٕندِس سٍتـ̡ یکوٹہ یِنہٕ برونہہ، سۅ آیہ روح القدس سٕندِس شُرِس سٍتـ̡ لبنہٕ۔ \n19.\\tپتہٕ اوس یوسف تٔمۍ سُند خانٛدار، یُس اکھ عادل {انسان} آسنہٕ کِنۍ، تہٕ أمِس عوٲمی مثالہٕ بناونس پیٹھ آمادہ اوس، تٔمۍ سُند خیال اوس نہٕ أمِس رازٕ پٲٹھۍ۔ \n20.\\tمگر یێلہِ أمِس یِمن چیزن پیٹھ غور گۆو، وُچھ خداوند سُند فرشتہ أمِس خوابس مَنٛز نمودار تہٕ وونُن، یوسف، اے داؤد سُند نیچو، ژے نِش گژھ نہٕ پنٕنۍ زنانہٕ نِنہٕ نِش خوفہٕ، تکیازِ یُس تس مَنٛز پٲدٕ سپدان چُھ، سُہ چُھ روح القدس سُند۔ {حاملہٕ: Gr. begotten}\n21.\\tتہٕ سُہ زاے اکھ نیٚچُو، تہٕ تٔمۍ سُند ناو یُس عیسیٰ سُند ناو دِیُن، تکیازِ سُہ کرِ پننین لوکن ہٕندِس گۅنہٕ نِش بچاو۔ {عیسیٰ: یعنی، نجات دِنہٕ وول}\n22. وۅنۍ سپُد یہ سورے پورٕ سپدُن، یُس رسولن رب سٕندِس بارس منز وننہ اوس آمُت، \n23.\\tوُچھو، اَکھ کُنِرِ بچہٕ آسہِ، تہٕ یێمہِ سُند ناو چُھہ عمانویل، یێمِچ ترجمہٕ کٔرِتھ چُھہ خدایہِ سٍتـ̡ اسہِ سٍتـ̡ وَننہٕ آمُت۔ {تِم...: یا، تٔمۍ سُند ناو یِیہِ وننہٕ}\n24.\\tپَتہٕ یوسف، یُس نِندٕ پٲٹھـ̡ ہُند حُکُم کٔرِتھ کٔرِتھ کٔرٕن خداوند سٕندِ فرشتہٕ سٕندِ حُکُم، تہٕ نِیُن أمِس نِش پنٕنۍ زنانہٕ۔ \n25.\\tتہٕ ٲس نہٕ أمِس توٚت تام زانان یوٚت تام نہٕ تٔمۍ پنُن گۄڈنیُک نیچو زٲوِتھ، تہٕ تٔمۍ ووٚن تٔمِس عیسیٰ سُند ناو۔","1. یێلہِ عیسیٰ مسیح ہیرودیس بادشاہ سٕندِس زمانس مَنٛز یہودیہ کِس بیت لحمس مَنٛز زامُت، وُچھ مشرقہٕ پیٹھٕ دٲنِتھ یروشلیم کُن دِنہٕ۔ \n2. ونُن، سُہ کتہِ چُھ یُس یہودین ہُند بادشاہ زامُت چُھ؟ تکیازِ أسـ̡ چُھ مشرقس مَنٛز تٔمۍ سُند تارٕ وُچھمُت، تہٕ أسـ̡ أمِس پوٗزا کرنہٕ خٲطرٕ آمُت۔ \n3.\\tییلہ ہیرودیس بادشاہن یہ کتھ بوز، سُہ گوٚو پریشان تہٕ سورُے یروشلم پانس سٍتـ̡ ۔ \n4. تہٕ ییلہ تٔمۍ لُکن ہٕندِس سارِنٕے سردار پادٕرۍ تہٕ کاتب جمع کٔرۍ، تٔمۍ کٔر تِمن نِش منگ زِ مسیح کتہِ گژھہِ زٮ۪نہٕ۔ \n5. تہٕ تِمو ووٚن أمِس بیت اللحمس مَنٛز، یِتھٕ پٲٹھـ̡ چُھ پیغمبرن لیوکھمُت، \n6. تہٕ توے بیت اللحم، یہوداہٕ کِس سرزمینس منز، یہوداہٕ کِس شہزادن مَنٛز چُھہ نہٕ کم از کم، تکیازِ ژے منزٕ گژھہِ اکھ گورنر یُس میانین لوکن ہٕندِس اسرائیلس پیٹھ حکومت کرِ۔ {حکمرٲنی : یا، کھیٚنہٕ}\n7.\\tامہ پتہ ہیرودس ییلہ تٔمۍ دانشمندن بُلٲومُت، تِمن پرژھ تِمن نِش زِ ستارہ کمہِ بجہِ آو ظٲہر۔ \n8. تہٕ تٔمۍ سوٗزۍ تِم بیت اللحم کُن، تہٕ وونُن، گژھ تہٕ لۄکٹِس شُرِس ژھانڈنہٕ خٲطرٕ۔ تہٕ ییلہ ژیہ یہ لٔبِتھ تہٕ بہٕ یِتھ تہِ أمِس پوٗزا کٔرِتھ۔ \n9.\\tییلہ تِمو بادشاہ بوز، تِمو درٛاو تِم درٛاو۔ تہٕ لو، سُہ تارک، یُس تِمو مشرقس منز وُچھمُت، گوٚو تِمن برونہہ کُن، یوٚت تام سُہ آو تہٕ کھڑا ییتہِ لۄکُٹ شُر اوس۔ \n10.\\tییلہ تِمو ستارہ وُچھ، تِمو گٔیہِ سٮ۪ٹھاہ خوشی سان خۅش۔ \n11. تہٕ ییلہ تِم گرس منز آیہ، تِمو وُچھ لۄکُٹ شُر مریم سٕنزِ ماجہ سٍتۍ، تہٕ پیوٚو پیوٚو تہٕ کٔرٕکھ أمِس پوجا کرنہٕ۔ سۄن، تہٕ لوبان تہٕ مر۔ {پیش کرنہٕ: یا پیش کرنہٕ}\n12. تہٕ أکِس خوابس مَنٛز خدایہِ سٕنز خبر دِنہٕ آمٕژ زِ تِم گژھِ نہٕ ہیرودیس نِش واپس یِن، تِم گٔیہِ بییہِ پٲٹھـ̡ پننِس ملکس کُن۔ \n13. تہٕ ییلہ تِم نیرِ، وُچھِو خداوند سُند فرشتہ یوسف سٕندِس خوابس منز ظٲہر سپدان تہٕ وُچھِتھ وُچھِو، وُچھِو تہٕ جوان شُر تہٕ تٔمۍ سٕنزِ موج نِتھ ژٔلِو مصرس مَنٛز، تہٕ توٚت تام روزُن توٚت تام روزُن یوٚت تام بہٕ ژےٚ خبر دِیہِ، تِکیازِ ہیرودیس کرِ لۄکٹِس شُرِس أمِس تباہ کرنہٕ خٲطرٕ۔ \n14.\\tییلہ سُہ ووٚتھ، تٔمۍ نِش رٲژ شُر تہٕ ماجہ نِش تہٕ دراو مصرس کُن۔ \n15.\\tتہٕ روٗد ہیرودس سٕندِس مرنس تام، یُس خداوند سٕندِس بارس مَنٛز وَننہٕ آمُت اوس، یُس پیغمبرن وونُن اوس زِ میہ چُھہ مصرہٕ منزٕ پنُن نیچو بُلاونہٕ آمُت۔ \n16. پَتہٕ سپُد سُہ پوٗرٕ یُس یرمیوسی پیغمبرن وَنُن اوس ، \n17.\\tرامس منز ٲس اکھ آواز بوزنہٕ آمٕژ، ماتم تہٕ روُن، تہٕ سٮ۪ٹھاہ ماتم کٔرِتھ، راحیل ٲس پننین شُرین ہٕندِ خٲطرٕ روُن، تہٕ تس ٲس نہٕ تسلی دِنہٕ آمٕژ، تکیازِ تِم چھِنہٕ نہٕ۔ \n18. مگر ییلہ ہیرودیس مٔرۍ، وُچھ خداوند سُند اکھ فرشتہ آو خوابس مَنٛز یوسفس نِش ظٲہر۔ \n19.\\tوَنُن زِ وُچھِو تہٕ جوان شُر تہٕ تٔمۍ سٕنزِ موج نِتھ گٔژھِو اسرٲیلِچ سرزمینس مَنٛز، تِکیازِ تِم چھِ موٗدمٕتـ̡ یِمو لۄکٹِس شُرِس سٕندِس زُو ژھارنہٕ آمٕژ چھِ۔ \n20. تہٕ سُہ ووٚتھ، تہٕ لۄکُٹ شُر تہٕ تٔمۍ سٕنٛز موج نِتھ آو اسرٲیلِس مَنٛز ۔ \n21.\\tمگر ییلہ تٔمۍ بوز زِ آرکیلاوس اوس یہودیاہس منز پننِس مٲلس ہیرودیس سٕندِس کمرس مَنٛز بادشاہی کٔرمٕژ، سُہ گوٚو تتہِ گژھنہٕ نِش کھوژان: باوجوٗد تہِ اوس خوابس مَنٛز خدایہِ سٕنز خبردار کرنہٕ آمٕژ، سُہ پھیُر گلیل کِس حصن مَنٛز: \n22.\\tتہٕ سُہ آو تہٕ روٗد ناصرت ناوٕ أکِس شہرس مَنٛز روزُن، یُس پیغمبرن ہٕنز کتھ ٲس کٔرمٕژ، سُہ گژھہِ ناصری وننہٕ۔","1. تِمن دۅہن آو یوحنا بپتسمہ دِنہٕ، یُس یہوداہ کِس بیابانس مَنٛز تبلیغ کران اوس، \n2. تہٕ ونُن، توبہ کرو تہٕ اسمانٕچ بادشٲہی چھے نزدیک۔ \n3. یێمہِ سٍتـ̡ چُھہ یێمِس مُتلق پیغمبر عیسیٰ سٕندِ کتھ کٔرِتھ وَننہٕ آمُت چُھ، بیابانن مَنٛز کٔرِو وَتھ تٔمِس سٍتـ̡ وَتھ سٍتـ̡ تٔمۍ سٕنزِ وَتہٕ سٍتـ̡ \n4.\\tتہٕ یۅہے یوحنا اوس اونٹِس مَس سٍتـ̡ پوشہٕ تہٕ لٔگِس لٔگِتھ لٔگِتھ لٔگِتھ۔ تہٕ تٔمۍ سُند ماز اوس ٹِڈی تہٕ جنگلی ماچھ۔ \n5. پَتہٕ گۆو أمِس نِش یروشلم، تہٕ سٲرۍسٕے یہودایہ، تہٕ اردن اندۍ پٔکھۍ سارِنٕے علاقن نِش۔ \n6. تہٕ آیٔے اردنس مَنٛز تٔمِس بپتسمہ دِنہٕ، تہٕ کٔرِکھ پننین گناہن ہُند اقرار کٔرِتھ۔ \n7.\\tمگر ییلہ تٔمۍ واریاہ فریسی تہٕ صدوقی تٔمۍ سٕندِس بپتسمہ دِنہٕ خٲطرٕ یِوان وُچھ، تٔمۍ ووٚن تِمَن زِ اے سانپَن ہٕنزِ نسل، کٔمۍ چُھہ ژٔلِتھ یِنہٕ وٲلِس قہر نِش ژلنہٕ خٲطرٕ خبردار کورمُت۔ \n8.\\tتوبہ خاطرہ پھل دِیُن: {ملاقات...: یا، زندگی ہنزِ اصلاح ہند جوابدہ}\n9.\\tتہٕ یہ ونُن زِ اسہِ چھہ ابراہیم پننِس مٲلس سٍتـ̡ ، کیازِ بہٕ چُھس ژے ونان زِ خدا چُھہ یِمو کنیو سٍتـ̡ ابراہیمس تام اولاد پٲدٕ کرنٕچ قٲبل۔ \n10. تہٕ وۅنۍ تہِ چُھ کُلٮ۪ن ہٕندِس موٗلس تام کُلہٕ تراونہٕ آمُت: تێمہِ مۅکھہ چُھ پریتھ کُل یُس نہٕ اصل پھل دِوان چُھ، سُہ چُھ ژٹنہٕ یوان تہٕ نارس مَنٛز تراونہٕ یِوان۔ \n11. بہٕ چُھس پٔزۍ پٲٹھـ̡ توبہٕ خٲطرٕ آبہٕ سٍتـ̡ بپتسمہ دِوان، مگر یُس میانہِ پَتہٕ یِوان چُھ، سُہ چُھہ میانہِ کھۅتہٕ زیادٕ طاقتور آسان، یٔمۍ سٕندِس بوٗٹ چُھس بہٕ تُلنس لایق چُھس: سُہ کرِ تۅہہِ روح القدس سٍتـ̡ بپتسمہ دِنہٕ، تہٕ نارٕ سٍتـ̡ بپتسمہ دِنہٕ: \n12.\\tیمۍ سُند پنکھ اتھس منز آسہِ، تہٕ سُہ کرِ پنُن فرش صاف کٔرِتھ پنُن کُنُک جمع کٔرِتھ۔ مگر سُہ دِیہِ نہ بٔرِتھ نارٕ سٍتۍ زٲلِتھ۔ \n13. پَتہٕ چُھ عیسیٰ علیہ السلام گلیل پیٹھٕ اردن تام یوحنا سُند بپتسمہ دِنہٕ خٲطرٕ یوان۔ \n14.\\tمگر یوحنا کٔر أمِس منع کٔرِتھ یہِ ؤنِتھ زِ بہٕ چُھس ژے بپتسمہ دِنہٕ یُن، تہٕ ژٕ چُھکھ میانہِ نِش یِوان؟ \n15. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تس جواب دِتھ زِ وُنہِ تہِ گژھہِ یِتھٕ پٲٹھۍ أسـ̡ سارِنٕے نیکی پورٕ کرٕنـ̡ ۔ تێلہِ دِژ أمِس سٍتـ̡ دِنہٕ۔ \n16. تہٕ عیسیٰ علیہ السلام ییلہ تس بپتسمہ دِنہٕ آو، ووت سیوٚد آبہٕ منزہ نیبر۔ تہٕ وُچھ تس خٲطرٕ آسمانہٕ کھولنہٕ، تہٕ تٔمۍ وُچھ خدایہ سُند روح کۅتر ہٕندۍ پٲٹھۍ، تہٕ تس پیٹھ گاش دِوان۔ \n17.\\tتہٕ آسمانہٕ پیٹھٕ اکھ آواز یُس ونان چھُ، یہِ چُھہ میون پیاری نیچو، یٔمِس سٍتـ̡ بہٕ خوش چُھس۔","1. پَتہٕ آو عیسیٰ مسیح روحہٕ سٍتـ̡ بیابانن مَنٛز نِنہٕ یُتھ شیطان سُند آزمائش کرنہٕ مۅکھہٕ۔ \n2. تہٕ ییلہ تٔمۍ ژتٲجی دۅہن تہٕ ژتٲجی رٲژ روزٕ تھوو، سُہ اوس امہ پتہٕ ہُند دُکھ دِنہٕ آمُت۔ \n3. تہٕ ییلہ فتنہ وول أمِس نِش آو، تٔمۍ ووٚن زِ اگر تہٕ خدا سُند فرزند چھُو، تیٚلہِ دِیُن حُکُم زِ یِم کٔنہِ یِن روٹی بناونہٕ۔ \n4. مگر تٔمۍ دیُت جواب تہٕ وونُن، یہ چُھ لیکھنہٕ آمُت، انسان روزِ نہٕ صرف روٹی سٍتـ̡ زندٕہ روزُن، بٔلکہِ خدایہِ سٕندِ زبانہِ منزٕ نیرنہٕ وٲلِس پریتھ لفظس سٍتـ̡ روزُن۔ \n5. پَتہٕ چُھ شیطان أمِس مُقدس شہرس مَنٛز نِوان، تہٕ بِہناوُن سُہ ہیکل کِس تینتٲلِس پیٹھ، \n6. تہٕ چُھ أمِس ونان زِ اگر تہٕ خدا سُند نیٚچُو چھُو، پَنُن پان ترٛاوُن، تِکیازِ یہِ چُھہ لیکھنہٕ آمُت زِ سُہ دِیہِ تُہٕندِس فرشتن تہٕ تِمن ہٕندِس اتھس مَنٛز تُلِتھ تُہٕندِس اَتھَس مَنٛز، یێلہِ تہٕ کُنہِ ساتہٕ کُنہِ تہِ وِزِ پَنُن کھۄر کُنہِ سٍتـ̡ ٹاس دِنہٕ۔ \n7. حضرت عیسیٰ علیہ السلام ووٚن أمِس دُبارٕ لیکھنہٕ آمُت، تہٕ ژے گژھ نہٕ خداوند پنُن خدایہ آزماونہٕ یُن۔ {آزمائش: یا، کوشش کرُن، یا آزمائش کرُن، یا، ثبوت}\n8. دُبارٕ چُھ شیطان أمِس أکِس تھدِس بالس پیٹھ نِوان، تہٕ دُنیاہٕچ سارِنٕے بادشٲہی تہٕ تِمن ہُند جلال ہاوان چھُ۔ \n9.\\tتہٕ چُھس وَنُن زِ یِم سٲری چیز بہٕ دِیہٕ ژے دِنہٕ، یێلہِ ژٕ پیٚیہِ تہٕ میانہِ پوٗزا کٔرِو۔ \n10. تێلہِ چُھ عیسیٰ علیہ السلام أمِس ونان زِ یێلہِ نیرُن شیطان، تێلہِ چُھہ لیکھنہٕ آمُت، تہٕ تێہہ کٔرِو خداوند پنُن خدا، تہٕ تٔمِس سٍتـ̡ کرٕنـ̡ عبادت کرٕنـ̡ ۔ \n11. پَتہٕ چُھ شیطان أمِس ترٲوِتھ، تہٕ وُچھِتھ آو فرشتہٕ تہٕ أمِس خدمت کٔرِتھ۔ \n12. وۅنۍ ییلہ حضرت عیسیٰ علیہ السلام بوٗز زِ یوحنا آو قٲد خانس مَنٛز تراونہٕ، سُہ دراو گلیل کُن۔ {کاسٹ ...: یا، دِنہٕ}\n13. تہٕ ناصرت ترٲوِتھ آو سُہ کفرناؤمس مَنٛز، یُس سمندرٕ بٔٹھِس پیٹھ چھُ، زابولون تہٕ نفتھالیم کِس سرحدس مَنٛز۔ \n14.\\tیُس یُس عیسیٰ پیغمبرن وونمُت اوس تہ یہ گژھہِ پورٕ سپدُن، \n15.\\tزبولون ہٕنز سرزمین، تہٕ نیفتھلیم سٕنز سرزمین، سمندرٕچ وتہٕ، اردن اپارِ، غیر قومن ہٕنز گلیل۔ \n16.\\tیِمو لُکھ یِم انہِ گٹہِ منز بِہِتھ ٲسۍ، تِمو وُچھ سٮ۪ٹھاہ گاش۔ تہٕ یِمن ہٕندِس علاقس مَنٛز بِہِتھ تہٕ موتُک سایہ چھُ گاش پٲدٕ سپدان۔ \n17. تَمہِ وقتہٕ پیٹھٕ کٔر حضرت عیسیٰ علیہ السلام تبلیغ کرُن، تہٕ وَنُن ہیوٚت، توبہ کرُن: تِکیازِ اسمانٕچ بادشٲہی چھے نزدیک۔ \n18.\\tتہٕ حضرت عیسیٰ علیہ السلام وُچھ زٕ بٲے، شمعون پطرس تہٕ اینڈریوس پنُن بٲے سمندرس مَنٛز جال تراوُن، تکیازِ تِم ٲسۍ گاڈٕ رٹان۔ \n19.\\tتہٕ سُہ چُھ تِمن ونان زِ میانہِ پٲٹھۍ، تہٕ بہٕ بناوٕ تۅہہ انسانن ہٕندِ گاڈٕ رٹان۔ \n20.\\tتہٕ تِمو ترٲوۍ سیدُے جال تہٕ أمِس پَتہٕ پَتہٕ۔ \n21.\\tتہٕ اَمہِ پَتہٕ پٔکِتھ وُچھ أمِس باقٕے زٕ بٲے یعقوبی سُند نیچو تہٕ یوحنا تٔمۍ سُند بوے زبدی سٕندِس مٲلِس سٍتـ̡ أکِس جہازس منز، تہٕ تِمن ہٕندِس جالس مرمت کٔرِتھ۔ تہٕ تٔمۍ بُلٲوِتھ تِمن بُلان۔ \n22. تہٕ تِمو دراو یکدم جہازٕ تہٕ پنُن مول تہٕ أمِس پتہٕ۔ \n23.\\tتہٕ عیسیٰ علیہ السلام گۆو سٲرۍسٕے گلیل سٍتـ̡ تہندِس عبادت خانن مَنٛز پرناوُن، تہٕ بادشاہتٕچ خوشخبری دِژٕن، تہٕ لُکن مَنٛز کٔرٕن پرٮ۪تھ قٕسمٕچ بیمارِ تہٕ پرٮ۪تھ قٕسمٕچ بیمارِ شفا دِنہٕ۔ \n24.\\tتہٕ تٔمۍ سٕنز شہرت گٔیہِ سٲرۍسٕے شامس منز، تہٕ تِمو أنۍ أمِس نِش سارِنٕے بیمار لُکھ یِم مختلف بیمارِ تہٕ عذابَن ہٕندِس سٍتـ̡ گٔیہِ، تہٕ یِم شیطان ٲسۍ، تہٕ یِم پاگل ٲسۍ، تہٕ یِمن فالج آسہِ۔ تہٕ تٔمۍ کٔر تِم شفا۔ \n25.\\tتہٕ تٔمِس پَتہٕ گٔیہِ گلیل پیٹھ، تہٕ {دکاپولس} تہٕ {یروشلم پیٹھ} تہٕ {پیٹھ} یہوداہ پیٹھ، تہٕ اردن اپارِ {پیٹھ} لُکھ لُکہٕ۔","1.\\tتہٕ ہجوم وُچھِتھ ووت سُہ أکِس پہاڑس کُن: تہٕ ییلہ سُہ سیٹ آو تٔمۍ سٕندِ شٲگِر أمِس نِش۔ \n2.\\tتہٕ تٔمۍ کٔر پَنُن بوش تہٕ تِمن ہیچھناوُن، \n3.\\tروحس منز غریبن ہٕندِس بابرکت سٍتـ̡ چُھہ تِمن ہٕندِس بادشاہتس سٍتـ̡ ۔ \n4. ماتم کرن وٲلس چھہِ بابرکت تہ تِمن تسلی دِنہٕ یِن۔ \n5. مُبرکت: تِکیازِ تِم گژھن زمینہِ ہُند وارث۔ \n6. یِم پاکیزگی ہٕندِس سٍتـ̡ فاقہٕ تہٕ پیاسہٕ کران چھِ، تِمن ہٕندِس سٍتـ̡ چُھہ مُبارک۔ \n7.\\tبابرکت چھہِ رحم کرُن: تکیازِ تِمن گژھہِ رحم میلان۔ \n8.\\tبابرکت چھہِ پاک دِل: تکیازِ تِم گژھن خدایہ وُچھن۔ \n9. امن قٲیم کرن وٲلِس چھِ بابرکت ، تِکیازِ یِم یِن خدایہِ سٕندِ اولاد وننہٕ یِن۔ \n10. یِم نیکی ہٕندِ خٲطرٕ ستاونہٕ آمٕتۍ چھِ، تِمن ہٕندِس سٍتـ̡ چُھہ آسمانٕچ بادشٲہی ۔ \n11.\\tبابرکت چھُو، ییلہ {انسان} تۅہہِ بد خواہ کرِ، تہٕ تۅہہِ سٍتـ̡ کرِ تہٕ میانہِ خاطرہ کرِ ژے خلاف پریتھ قسمہ کِس بُرِس سٍتـ̡ اپُز۔ {اپُز: Gr. Lieing}\n12. خۅش گژھُن، تہٕ سٮ۪ٹھاہ خۅش گژھُن: تۅہہِ سٍتـ̡ چُھہ تُہند اجر جنتس مَنٛز، تِکیازِ تِمو کٔر تۅہہِ برونہہ کُن پیغمبرن ستاونہٕ۔ \n13.\\tتُہۍ چھِو زمینہِ ہُند نوٗن: مگر اگر نوُن چُھہ مَزٕ راوُن، کَمہِ سٍتـ̡ ییہِ نوٗنہٕ دِنہٕ؟ اَمہ پتہٕ چُھہ یہِ کُنہِ چیزس خٲطرٕ اصل، مگر کٔڈِتھ کٔڈِتھ تہٕ انسانن ہٕندِس قدمن تل لَتہٕ یِنہٕ۔ \n14.\\tتُہۍ چھِو دُنیاہُک گاش۔ یُس شہر بالس پیٹھ قایم آسہِ سُہ ہیکہِ نہٕ ژوٗرِ تھٲوِتھ۔ \n15.\\tانسان چھہ شمعہ زالان تہ بشل تلہ کنہِ تھپھ کٔرِتھ بلکہ شمعہ دانس پیٹھ۔ تہ یہ چھہ گرس منز موجود سارنٕے لوکن گاش دوان۔ {اکھ بُشل: اصلی لفظس منز چھہ تتھ پیمانس پیٹھ اشارہ کران یُس اکھ پِنٹ کم آسہِ}\n16.\\tپَنُن گاش گژھہِ انسانن برونہہ کُن یُتھ تُہٕندِس نیکی کامہِ وُچھن، تہٕ تُہٕندِس مٲلِس ہٕنز حمد کٔرِن یُس جنتس مَنٛز چھُ۔ \n17.\\tیہ نہ سوچو زِ بہٕ چُھس شریعت یا پیغمبرن تباہ کرنہٕ خٲطرٕ آمُت آمُت، بہٕ چُھس نہٕ تباہ کرنہٕ خٲطرٕ آمُت بلکہ پورٕ کرنہٕ خٲطرٕ آمُت۔ \n18.\\tیێلہِ بہٕ چُھس ژے ونان زِ یوتام نہ اسمانس تہٕ زمینہِ نیرِ، یوتام نہٕ سارِوٕے سارِوٕے پوٗرٕ سپدِ۔ \n19. یُس یُس یِمو منزٕ اکھ کم حکمہٕ پھُٹراوِ، تہٕ انسانس یِہ ہیچھناوِ، سُہ ییہِ آسمانہٕ کِس بادشٲہی مَنٛز سارِوٕے کھۄتہٕ کم وننہٕ۔ \n20. تکیازِ بہٕ چُھس ژےٚ ونان زِ یوتام نہٕ تُہٕنز نیکی کاتبن تہٕ فریسیین ہٕنزِ نیکی کھوتہٕ زیادٕ آسہِ، تُہۍ ہیکو نہٕ کُنہِ تہِ صورتس منز آسمانہٕ کِس بادشٲہی مَنٛز دٲخل گٔژھِتھ۔ \n21.\\tژیہ بوزمُت زِ تِمو اوس پرانہِ زمانہٕ پیٹھٕ وَننہٕ آمُت زِ ژے گژھِ نہٕ مارُن۔ تہٕ یُس تہِ قتل کرِ، سُہ گژھہِ فیصلُک خطرہٕ: {by: or, to}\n22. مگر بہٕ چُھس ژے ونان زِ یُس تہٕ یُس پننِس بٲیس سٍتـ̡ کُنہِ وجہہ ورٲے ناراض آسہِ، سُہ گژھہِ فیصلہٕ کہِ خطرس منز، تہٕ یُس تہٕ یُس پننِس بٲیِس راکا سٍتـ̡ وَنُن آسہِ، سُہ گژھہِ مجلسُک خطرٕ، مگر یُس تہِ وَنُن چُھ، تہٕ یُس تہِ وَنُن چُھ، بیوقوف چُھ، سُہ گژھہِ جہنم کہِ نارُک خطرٕ۔ {راکا: یعنی، بیکار انسان}\n23.\\tتێلہِ یێلہِ ژے پنُن تحفہٕ قربان گاہس پیٹھ أنِو، تہٕ تتہِ گژھہِ یاد روزُن زِ تُہند بٲے چُھہ تۅہہِ خلاف کرُن۔ \n24. پنُن تحفہٕ ترٲوِو قربان گاہَس برونہہ کُن، تہٕ پَنٕنہِ وَتہِ گژھِ۔ گۅڈٕ گژھ پننِس بٲیِس سٍتـ̡ صلح کٔرِتھ، تہٕ پَتہٕ یِو پَنُن تحفہٕ۔ \n25.\\tپننِس مُخٲلِفس سٍتـ̡ کٔرِو جلدی رضامندی ، ییلہ تہٕ تُہۍ أمِس سٍتـ̡ وتہِ ٲسِو۔ یێلہِ کُنہِ تہِ وِزِ دُشمن دِیہِ تُہہِ قاضس نِش تہٕ قاضی دِیہِ ژےٚ افسرس نِش، تہٕ ژے یِیہِ قٲد خانس منز تراونہٕ۔ \n26.\\tبہٕ چُھس ژے ونان زِ تۅہہ گژھِ نہٕ تتہِ نیبر نیرُن، یوٚت تام نہٕ ژے پورٕ دِیہِ۔ \n27.\\tتۅہہ چُھہ بوزمُت زِ تِمو اوس پرانہِ زمانہٕ پیٹھٕ وَننہٕ آمُت، زنا کرُن نہٕ: \n28. مگر بہٕ چُھس ژےٚ ونان زِ یُس تہٕ یُس زنانہِ ہٕندِس ہوس خٲطرٕ وُچھان چُھ، سُہ چُھ أمِس دِلس مَنٛز زنا کٔرمُت۔ \n29.\\tتہٕ اگر تۅہہِ دٔچھنِس أچھ ژےٚ ناراض کرِ، تہٕ ژٔٹِتھ کٔرِو پانس نِش، تکیازِ تۅہہِ ہٕندِ خٲطرٕ چُھ فٲیدٕ مند زِ تُہند اکھ نفر گژھہِ ختم گژھُن، تہٕ تُہند سورُے جسم گژھہِ جہنمس مَنٛز تراونہٕ یُن۔ {بُزرگ...: یا کٔرِو تۅہہِ ناراض کرُن}\n30. تہٕ اگر تُہُند دٔچھُن اَتھٕ ژٔٹِتھ ژٔٹِھتھ ژٔٹِتھ دِنہٕ یُن۔ \n31.\\tیہ چھہ وننہ آمت زِ یُس تہِ پننہِ زنانہِ ہُند ذکر کرِ، سہ گژھہِ طلاق دِنُک خط دِن: \n32. مگر بہٕ چُھس ژےٚ ونان زِ یُس تہٕ یُس پننہِ زنانہِ زنا کِس وجہہ سٍتـ̡ تراوِ، سُہ چُھ زنا کرُن، تہٕ یُس تہٕ یُس طلاق دِنہٕ واجنہِ زنانہِ سٍتـ̡ خاندر کرِ، سُہ چُھ زنا کٔرِتھ۔ \n33. دُبارٕ چُھہ بوزمُت زِ تِمو چُھہ پرٲنِس زمانس منز وَننہٕ آمُت زِ ژے گژھ نہٕ پنُن پان تراوُن، بلکہ کرٕ خداوند سٕندِ خٲطرٕ پَنُن قسم۔ \n34. مگر بہٕ چُھس ژےٚ وَنُن، کُنہِ تہِ کُنہِ تہِ قَسم کٔرِتھ تہٕ نہ آسُن؛ تِکیازِ یہِ چُھ خدایہِ سُند تخت: \n35. تہٕ نہ چُھہ زمینہِ سٍتـ̡ تکیازِ یہِ چُھہ تٔمۍ سٕندِس قدمن ہُند پٲٹھۍ: نہٕ یروشلمس سٍتـ̡ تکیازِ یہِ چُھ عظیم بادشاہ سُند شہر۔ \n36.\\tتہٕ کَلہٕ سٍتـ̡ کَلہٕ سٍتـ̡ قَسم کٔرِتھ، تِکیازِ تُہہِ ہێکہِ نہٕ أکِس مَس سَفید تہٕ کرٛیٚہُن کٔرِتھ۔ \n37.\\tمگر چانۍ کتھ گژھہِ آسن، ہاں، ہاں۔ نہ، نہ، تکیازِ یُس تہِ یُس تہِ بدکار آسہِ۔ \n38.\\tژیہ بوزمُت زِ یہ چھہ وننہ آمت زِ اچھ بدلہٕ أچھ تہٕ دند بدلہٕ دند۔ \n39.\\tمگر بہٕ چُھس ژےٚ ونان زِ یُس تہٕ یُس تہٕ تُہٕندِس دٔچھنِس گِلِس پیٹھ لَگ دِیہِ، سُہ کٔرِو تٔمِس کُن تہِ۔ \n40.\\tتہٕ اگر کانہہ شخص تۅہہِ قانونس پیٹھ مقدمہ کرِ، تہٕ تُہند کوٹ نِتھ نِن، تٔمِس گژھہِ تُہند پوشہ تہِ۔ \n41. تہٕ یُس تہِ ژیہ اکھ میل پکنہٕ خٲطرٕ مجبور کرِ، سُہ گژھہِ أمِس سٍتـ̡ دۅشوے سٍتـ̡ ۔ \n42.\\tیُس تۅہہِ منگان چُھ، تہٕ یُس تۅہہِ نِش قرضہٕ نِنہٕ چُھ، تٔمِس دِیُن نہٕ پتھ کُن۔ \n43.\\tژے چُھہ بوزمُت زِ ژے کٔرِو پننِس ہمساین سٍتـ̡ محبت تہٕ دُشمن سٍتـ̡ نفرت۔ \n44. مگر بہٕ چُھس ژےٚ ونان، پننین دُشمنن سٍتـ̡ محبت کرُن، تِمن سٍتـ̡ کرو خیر یِم تۅہہِ سٍتـ̡ نفرت کران چھِ، تہٕ تِمن ہٕندِ خٲطرٕ کٔرِو دُعا یِم تۅہہِ سٍتـ̡ بد سٍتـ̡ استعمال کران چھِ، تہٕ تۅہہِ سٍتـ̡ دُعا کران چھِ۔ \n45. یُتھ تُہۍ پننِس مٲلہِ سٕندِ بُرِ بٔنِتھ یُس آسمانس مَنٛز چُھ، تکیازِ سُہ چُھ پَنُن آفتاب بدی تہٕ نیکی پیٹھ طلوع کران، تہٕ صالحن تہٕ ناانصافن پیٹھ چُھ روٗد تراوان۔ \n46. یێلہِ تہِ چُھہ تِمن سٍتـ̡ محبت کران یُس تۅہہِ محبت کران چُھ، تێلہِ کیا ثواب چُھہ؟ پبلِکن تہِ چُھہ نہٕ یِتھ؟ \n47. تہٕ اگر تم صرف پننین باین سلام کران چھو، تہٕ کیا چُھ تُہۍ باقین کھوتہٕ زیادٕ کران؟ کیا پبلکن تہٕ چُھ نہٕ یِتھ؟ \n48. تێمہِ کِنۍ گژھِو کامل یُس تُہند مول یُس آسمانس مَنٛز چُھ، تہٕ چُھہ کٲمل ۔","1. ہوشیار روزُن زِ تُہۍ کٔرِو نہٕ انسانس برونہہ کُن پنُن خیرات دِنہٕ، یُس تِمن ہُند ظٲہر سپدُن، نتہٕ چُھہ نہٕ تۅہہِ پننِس مٲلہِ سُند ثواب یُس جنتس مَنٛز چُھ۔ {خیرات: یا، نیکی} {تُہٕندِس سٍتـ̡ نتہٕ﴾\n2.\\tتێلہِ ییلہ تہِ ژیہ خیرات دِوان چھِ، یێلہِ منافق عبادت خانن تہٕ سڑکن مَنٛز کران چھِ، یُتھ زن تِمن انسانن ہٕنز عزت حٲصل سپدِ۔ یێلہِ بہٕ چُھس ژے ونان زِ تِمن ہُند ثواب میلہِ۔ {مہٕ کرو نہ...: یا کرو نہٕ بُرٕ وُن}\n3. مگر ییلہ تہۍ خیرات کرِ، تہٕ گژھہِ نہٕ پننہِ کھوورِ اتھس یہ زانُن زِ تُہند دٔچھُن اتھٕ کیا چُھ کران: \n4. یُتھ تُہُند مول یُس ژوٗرِ پٲٹھـ̡ وُچھان چُھ، سُہ دِیہِ تۅہہِ نَنہٕ پٲٹھـ̡ انعام۔ \n5.\\tتہٕ ییلہ تم دعا کران چھِو، تہٕ تم گژھن نہٕ منافقن ہٕندۍ پٲٹھۍ، تکیازِ تِم چھِ عبادت خانن تہٕ سڑکن ہٕندِس کونس مَنٛز کھڑا گژھِتھ عبادت کرُن پسند کران، یُتھ زن تِم انسانن ہٕندِ نظرِ تل گژھن۔ بہٕ چُھس ژے ونان زِ تِمن چُھ تِمن ہُند اجر میلان۔ \n6.\\tمگر ییلہ تہۍ دعا کران چھِو، پننِس المارِ منز اژُن، تہٕ ییلہ ژیہ پنُن دروازٕ بند کرِ، پننِس مٲلِس سٍتـ̡ کٔرِو دُعا یُس پوشیدٕ آسہِ۔ تہٕ تُہند مول یُس ژوٗرِ پٲٹھـ̡ وُچھان چُھ، سُہ دِیہِ تۅہہِ نَنہٕ پٲٹھـ̡ انعام۔ \n7.\\tمگر ییلہ تم دعا کران چھہِ، تکیازِ تم چھہِ سوچان زِ تم گژھن پننہِ کتھہِ پیٹھ بوزنہ۔ \n8.\\tتێلہِ گژھِو نہٕ تِمن ہٕندِس ہِش پٲٹھۍ، تێکیازِ تُہُند مول چُھہ زانان زِ تۅہہِ کمہِ چیزن ہٕنز ضرورت چُھ، تێلہِ چُھہ تس سٍتـ̡ پرژھنہٕ برونہہ۔ \n9. یێمہِ پٲٹھـ̡ کٔرِو یێلہِ دُعا کٔرِو: سٲنـ̡ باپ، یُس آسمانس مَنٛز چُھ، تُہند ناو گژھہِ پاک ۔ \n10. چانۍ بادشاہی ییہِ یِنہٕ۔ تُہٕنز مرضی گژھہِ زمینس مَنٛز کرنہٕ، یِتھ کٔنۍ زَن اسمانس مَنٛز چُھ۔ \n11. اسہِ دِیُن دۅہہٕ دِنہٕ آمُت۔ \n12. تہٕ اسہِ کٔرِو پنُن قرضہٕ معاف، یِتھ کٔنۍ أسۍ پننین قرضن معافی دِوان چھِ۔ \n13. تہٕ اسہِ نِش گژھ نہٕ آزمائشس مَنٛز بچاو، مگر بد نِش بچاوُن، تکیازِ تۅہہِ چُھہ بادشاہی، تہٕ طاقت تہٕ جلال ہمیشہٕ خٲطرٕ۔ آمین۔ \n14. یێلہِ تہٕ یێلہِ تُہۍ انسانن ہٕندِس گناہ معافی دِیِو، تێلہِ کرِ تُہند آسمانی باپ تہِ معاف: \n15. مگر یێلہِ نہٕ تُہۍ انسانن ہٕندِس گناہ معافی دِیِو، تێلہِ کرِ تُہند مول تہندِ قصور معاف۔ \n16.\\tامہِ علاوٕ ییلہ تم روزٕ تھاوان چھِو، منافقن ہٕندۍ پٲٹھۍ، غمگین شکلہِ ہُند نہ گژھُن، تکیازِ تِم چھِ پنٕنۍ بُتھ مسخ کران، یُتھ زن تِم انسانس روزٕ روزنہٕ خٲطرٕ ظٲہر سپدِ۔ بہٕ چُھس ژےٚ ونان زِ تِمن چُھ تِمن ہُند اجر میلان۔ \n17. مگر ییلہ تہۍ روزٕ روزان چھِو، پنُن کلہٕ مسح کٔرِتھ تہٕ بُتھ چھلناوُن۔ \n18.\\tیُس نہٕ تُہٕندِس مٲلِس سٍتـ̡ روزٕ روزُن ظٲہر سپدُن، بٔلکہِ پننِس مٲلِس سٍتـ̡ یُس رازٕ پٲٹھـ̡ چُھہ، تہٕ تُہُند مول یُس ژوٗرِ پٲٹھـ̡ وُچھان چُھ، سُہ دِیہِ تۅہہِ ظٲہِر کرنہٕ۔ \n19.\\tزمینس پیٹھ مہٕ تھاوُن پانس خٲطرٕ خزانہٕ، ییتہِ کیم تہٕ زنٛگ بدکار چھِ، تہٕ ییتہِ ژوٗر ژوٗرِ نِوان چھِ: \n20. مگر پانس خٲطرٕ تھٲوِو آسمانس مَنٛز خزانہٕ، ییتہِ نہ کیم تہٕ زنٛگ تہٕ یتہِ نہٕ ژوٗرِ تہٕ ژوٗرِ آسہِ۔ \n21. تتہِ آسہِ تُہند دِل تہِ۔ \n22. جسمُک گاش چُھ أچھ: اگر تۅہہِ اچھ کُنی آسہِ، تُہند سورُے جسم آسہِ گاشہٕ سٍتـ̡ بٔرِتھ۔ \n23.\\tمگر اگر چانۍ أچھ بد آسہِ، تیلہِ گژھہِ تُہند سورُے جسم انہِ گٹہِ سٍتـ̡ بٔرِتھ۔ تێلہِ یێلہِ تێلہِ یُس گاش چُھہ انہِ گوٚٹ آسہِ، تیلہِ کوتاہ بۆڈ چُھہ سُہ انہِ گوٚٹ! \n24. کانہہ تہِ انسان ہیکہِ نہ دۅن مالکن ہنز خدمت کٔرِتھ، تکیازِ یا تہ کرِ سُہ أکِس سٍتۍ نفرت، تہٕ بییِس سٍتۍ محبت کرِ۔ نتہٕ کرِ سُہ أکِس سٍتـ̡ رٔٹِتھ تہٕ بییِس سٍتـ̡ حقارت کٔرِتھ۔ تہٕ تُہۍ ہیکو نہٕ خدایہ سٕنز خدمت کٔرِتھ۔ \n25. تێمہِ کِنۍ چُھس بہٕ ژے ونان، پننہِ زُوُہِ مُتلق گژھہِ نہٕ سوچ، تہٕ کیا کھیٚیہِ تہٕ کیا چیٚو۔ تہٕ نہ توتہِ پنہٕ نِس جسمس خٲطرٕ، کیا چُھکھ لاگُن۔ کیا زندگی چھا ماز کھۅتہٕ زیادٕ، تہٕ جسم چُھہ پوشہٕ کھۅتہٕ زیادٕ؟ \n26.\\tہوہٕکۍ جاناوار وُچھِو، تِکیازِ تِم چھِنہٕ وۄپدان، نَہ چھِ لُٹان تہٕ نہ چھِ کوٹھن مَنٛز جمع گَژھان۔ توتہِ چُھہ تُہند آسمانی باپ تِمن کھٮ۪وان دِوان۔ کیا تُہۍ چھِو نہٕ تِمَن کھۅتہٕ زیادٕ بہتر؟ \n27.\\tتوہہِ منزٕ کُس ہیکہِ سونچِتھ تٔمۍ سٕندِس قدس منز اکھ کیوبِٹ ہُرراوِتھ؟ \n28.\\tتہِ کیازِ چھکھ پلو سونچان؟ کھیت چہ لِلہِ پیٹھ وچھو، تم کتھہ پاٹھۍ چھہِ کھسان۔ تم چھہِ نہ محنت کران تہ نہ چھہِ نژان۔ \n29. تہٕ توتہِ چُھس بہٕ ژےٚ ونان زِ سُلیمان تہِ اوس نہٕ یِمو منزٕ أکِس ہٕندۍ پٲٹھۍ۔ \n30. کیازِ، یێلہِ خدایہِ کھہُک گاسہٕ یُس از تہٕ پگہہ تندرس منز تراونہٕ ییہِ، تێلہِ کیا سُہ چُھہ نہٕ زیادٕ پلو دِن، اے کم ایمانہٕ؟ \n31.\\tلہذا گژھہِ نہ سوچُن، یہ ونُن زِ أسۍ کیا کھیون ؟ یا اسہِ کیا چیوٚن؟ یا اسہِ کتہِ گژھہِ پلو لاگُن؟ \n32. (یِمو سارِوٕے چیزو پَتہٕ چُھہ غیر قومن ہٕندِس باپ سٍتـ̡ یِمن سارِنٕے چیزن ہٕنز ضوروٗرَتھ:) تێلہِ چُھہ تُہٕندِس آسمانی مٲلِس زانان زِ تێہہِ چُھہ یِمن سارِنٕے چیزن ہٕنز ضٔروٗرت۔ \n33. مگر گۅڈٕ کٔرِو خدایہِ سٕنزِ بادشاہی تہٕ تٔمۍ سٕنزِ نیکی ہٕنز تلاش کٔرِو۔ تہٕ یِم سارِنٕے چیز یِن توے سٍتـ̡ شٲمل کرنہٕ۔ \n34.\\tتَمہِ کِنۍ گژھہِ نہٕ پگہہ کُن سوچُن: تکیازِ پگہہ گژھہِ پننہِ چیزن ہٕندِس خیالس منز۔ دۅہس تام چُھہ اَمہ سٍتـ̡ بُرٲے سٍتـ̡ کٲفی۔","1. فیصلہ کرو نہٕ زِ تُہند فیصلہ گژھہِ نہٕ کرنہٕ۔ \n2.\\tتہِ کُنہِ فیصلہٕ سٍتـ̡ ییہِ فیصلہ کرنہٕ، تہٕ کُنہِ پیمانہٕ سٍتـ̡ ییہِ تۅہہِ سٍتـ̡ دُبارٕ میننہٕ۔ \n3.\\tتہٕ ژے کیازِ چھکھ پننِس بٲے سٕنزِ اچھِ منز موجود موٹ وچھان، مگر تۅہہ چھُنہٕ پننِس أچھن منز موجود شعاعہٕ سٍتۍ غور کران۔ \n4.\\tیا ژیہ کِتھہ پاٹھۍ وَنُن پننِس بٲیس زِ میہ کٔڈِتھ ژیہ پننہِ اچھِ منزٕ کٔڈِتھ کٔڈِتھ تہٕ وُچھِو تۅہہِ اچھن منز اکھ بیم {چھُ}؟ \n5. اے منافق، گۅڈٕ کٔرِو پننہِ أچھِ منزٕ بیم کڈنہٕ۔ تہٕ پَتہٕ کٔرِو ژے صاف پٲٹھۍ وُچھِتھ زِ پنہٕ نِس بٲے سٕنزِ أچھِ منزٕ کٔڈِتھ کٔڈِتھ کٔرِتھ۔ \n6. ہونین یُس مقدس چُھ نہٕ دِیُو، تہٕ نہ تراوُن پنٕنۍ موتی سورن برونہہ کُن، نتہٕ تِم کرِ تِمن پننین قدمن تلہٕ لتہٕ تہٕ پھٔٹِتھ ژٔٹِتھ۔ \n7.\\tپرژھو، تہٕ یہ یِیہِ دِنہٕ؛ ژھانڈِو، تہٕ ژے لٔبِو؛ دستک دِیُو، تہٕ یہ گژھہِ ژےٚ خٲطرٕ کھولنہٕ: \n8.\\tیُس پریتھ کانہہ منگان چُھ، سُہ چُھ رٔٹان۔ تہٕ یُس ژھانڈان چُھ، سُہ چُھ لبنہٕ یِوان۔ تہٕ یُس ٹاس دِیہِ سُہ یلہٕ دِنہٕ۔ \n9.\\tیا کُس انسان چُھہ یُس یُس نیچو روٹی منگان چھُ، سُہ دِیہ تس کٔن؟ \n10.\\tیا اگر سُہ گاڈٕ پرژھہِ، کیا سُہ دِیہ تمِس ناگ؟ \n11.\\tتێلہِ یێلہِ تہٕ یێلہِ تُہۍ بد کار ٲسِو، پننین شُرین کِتھہ کٔنۍ چُھ اصل تحفہٕ دِنہٕ یِوان، تێلہِ کوتاہ کرِ تُہند مول یُس آسمانس مَنٛز چُھ، تِمن یُس أمِس منگناوان چُھ، کوتاہ دِیہِ تُہند مٲل یُس أمِس منگناوان چُھ؟ \n12. تێمہِ کِنۍ یێلہِ تہِ یێلہِ تہِ شریعت تہٕ پیغمبرن ہٕندِس سٍتـ̡ کرُن۔ \n13.\\tژاو آبنائے دروازس پیٹھ اژُن: تکیازِ وسیع {is} دروازہ، تہٕ وسیع {is} وتہِ، یُس تباہی کُن واتناوان چُھ، تہٕ واریاہ چھِ یِم اتھ منز گژھان چھِ: {strait: or, narrow}\n14.\\tکیازِ اَتھ وَتہِ چھُ دروازٕ، تہٕ تنگ چھُ سُہ وَتھ یُس زندگی کُن واتناوان چھُ، تہٕ واریاہ کم چھِ یِم یہِ لبان چھِ۔ {کیازِ: یا، کِتھہٕ پٲٹھۍ}\n15.\\tاپُز پیغمبرن نِش روزِو خبردار، یِم تۅہہِ نِش کۅکرِ ہٕندِس پوشس منز یوان چھِ، مگر باطنی طور چھِ تِم رامہٕ ہونہٕ وٲلۍ۔ \n16.\\tتُہۍ چھِو تِمن ہٕندِس پھلہٕ سٍتـ̡ زانان۔ کیا انسان چھِ کانٹَن ہٕندِ انگور سٍتـ̡ یا کُلہِ ہٕندِس انجیر سٍتـ̡ جمع کٔرِتھ؟ \n17. یِتھے پٲٹھۍ چُھ پرٮ۪تھ کُل اصل پھل دِوان۔ مگر بدکار کُل چُھ بد پھل دِوان۔ \n18.\\tاصل کُل ہیکہِ نہ بد پھل دِتھ، نہ ہیکہِ بدکار کُل اصل پھل دِتھ۔ \n19. پریتھ کُل یُس نہٕ اصل پھل دِوان چُھ، سُہ چُھ ژٹنہٕ یوان تہٕ نارس مَنٛز تراونہٕ یِوان۔ \n20. اَمہِ مۄکھٕ یِمن ہٕندِس پھلہٕ سٍتـ̡ زاننہٕ یِوان۔ \n21. پریتھ کانہہ یُس میہ ونان چُھ، خداوند، خداوند، گژھہِ نہٕ اسمانس کِس بادشٲہی مَنٛز اژُن۔ مگر یُس میانہِ مٲلہِ سٕنز مرضی کرِ، یُس آسمانس مَنٛز چُھ۔ \n22. واریاہ لوٗکھ چھِ اَمہِ دۅہہٕ مےٚ ونان، خداوند، خداوند، کیا أسۍ کٔر نہٕ تہندِ ناوٕ سٍتـ̡ پیشن گوئی؟ تہٕ تہٕ چُھہ تُہندِ ناوٕ سٍتـ̡ شیطان کٔرِتھ کٔرِمٕتۍ؟ تہٕ تُہندِ ناوٕ سٍتـ̡ کٔرِکھ واریاہ حیرت انگیز کٲم؟ \n23. تہٕ پتہٕ بہٕ تِمن سٍتـ̡ اقرار کٔرِتھ، بہٕ چُھس نہٕ زانہہ تہٕ زانہہ پتاہ چُھہ: میہ نِش گژھ یُس بدکاری کران چُھ۔ \n24. تێمہِ کِنۍ یُس تہِ میانہِ یِم کتھ بوزان تہٕ یِم کران چُھ، بہٕ کٔرٕ تس أکِس دانشمند شخصس سٍتـ̡ تشبیہ دِنہٕ، یٔمۍ پَنُن مکانہٕ أکِس کَنہِ پتھرس پیٹھ بنوومُت چُھ: \n25. تہٕ روٗد پیوٚو تہٕ سٔہلاب آو تہٕ واو ووٚتھ تہٕ لوٚگ تتھ گرس پیٹھ۔ تہٕ یہ پیوٚو نہٕ: تکیازِ یہ اوس أکِس کنہِ پتھرس پیٹھ قایم کرنہٕ آمُت۔ \n26.\\tتہٕ یُس میانہِ یِم کتھ بوزان آسہِ، تہٕ یِم نہٕ کرِ، سُہ گژھِ أکِس بیوقوف شخصس سٍتـ̡ تشبیہ دِنہٕ یُن، یٔمۍ پنُن مکانہٕ سیٚکہِ پیٹھ بنوومُت چُھ: \n27.\\tتہٕ روٗد پیوٚو تہٕ سٔہلاب آو تہٕ واو ووٚتھ تہٕ تتھ مکانس لٔگۍ۔ تہٕ سُہ پیوٚو پیوٚو: تہٕ اَمہ ہُند پیوٚو بٔڈ۔ \n28.\\tتہٕ سپُد یێلہِ عیسیٰ علیہ السلام یِم کلامَن ختم کٔرۍ، لُکھ گٔیہِ تٔمۍ سٕندِس نظریہٕ سٍتـ̡ حٲران: \n29.\\tتکیازِ تٔمۍ ہیچھناوۍ تِمن اِختِیار آسنہٕ کِنۍ، نہ کہ کاتب سٕندِس طورس پیٹھ۔","1.\\tییلہ سُہ بالہٕ پیٹھٕ بۄن آو تہٕ بٔڈۍ بٔڈۍ لٔگۍ أمِس پَتہٕ پَتہٕ۔ \n2. تہٕ وُچھِتھ آو اَکھ کوڑھ تہٕ أمِس پوٗزا کٔرِتھ وونُن، خداوند، اگر ژٕ چاہِ، تہٕ ژٕ ہیکو مے پاک کٔرِتھ۔ \n3.\\tتہٕ حضرت عیسیٰ علیہ السلام تروو پنُن اتھہٕ تہٕ کوٚرُن أمِس اتھہٕ تہٕ وونُن بہٕ کرُن؛ ژٕ گژھہِ پاک۔ تہٕ یکدم گۆو تٔمۍ سُند کوڑھ صاف کرنہٕ۔ \n4. تہٕ عیسیٰ مسیح چُھ أمِس ونان زِ وُچھکھ نہٕ کٲنسہ تہِ کٲنسہ۔ مگر پَنٕنہِ وتہِ گژھِ، پادٕرِس نِش ہٲوِو پنُن پان، تہٕ سُہ تحفہٕ پیش کرُن یُس موسىٰ سُند حُکُم دِیُتمُت چُھ، تِمن ہٕنز گوٲہی دِنہٕ خٲطرٕ۔ \n5.\\tییلہ عیسیٰ مسیح کفرناؤمس مَنٛز دٲخل سپُد، تس نِش آو اکھ صد دِنہٕ، تہٕ تٔمِس دِژ التجا کرنہٕ، \n6.\\tتہٕ وَنُن، خداوند، میون خادم چُھ گَرِ مَنٛز بٮ۪مار، سٮ۪ٹھاہ عذاب۔ \n7. تہٕ عیسیٰ مسیح چُھ أمِس ونان زِ بہٕ یِیہٕ تہٕ أمِس شفا دِنہٕ۔ \n8.\\tسینچورین دیُت جواب تہٕ وونُن، خداوند، بہٕ چُھس نہٕ اتھ لایق زِ ژٕ گژھہِ میانہِ چھتہِ تلہٕ یِن، مگر صرف کتھ کرٕن، تہٕ میون خادم گژھہِ شفا بخش۔ \n9. تکیازِ بہٕ چُھس اَکھ اِنتِظام اِنتِظام کَرُن، یێمہِ سٍتـ̡ سُہ چُھس سُہ چُھہ نیران۔ تہٕ بییِس نِش چُھہ یِوان، تہٕ سُہ چُھ یِوان۔ تہٕ میٲنِس خادمس کُن، یێلہِ کٔرِو تہٕ سُہ چُھ کران۔ \n10.\\tییلہ حضرت عیسیٰ علیہ السلام بوٗز، سُہ گوٚو حٲران تہٕ وونُن تِمن یُس پَتہٕ یِنہٕ وٲلِس سٍتـ̡ چُھہ یێلہِ بہٕ چُھس ژے ونان زِ بہٕ چُھس نہٕ یوتاہ زیادٕ ایمانہٕ لبنہٕ آمُت، نہٕ اسرٲیلِس مَنٛز۔ \n11. تہٕ بہٕ چُھس ژےٚ ونان زِ واریاہ یِن مشرق تہٕ مغرب پیٹھٕ یِن، تہٕ بِہنہٕ ابراہیم، اسحاق تہٕ یعقوبس سٍتـ̡ آسمانہٕ کِس بادشٲہی مَنٛز۔ \n12. مگر بادشٲہی ہٕندِ بچہٕ یِن نیبرِمِس اندِپِس مَنٛز کڈنہٕ یِن: اَتہِ گژھہِ روُن تہٕ دندٕ گٔژٕھن۔ \n13.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن سینچورِنس زِ پَنٕنـ̡ وَتہِ گژھِ۔ تہٕ یێتھے پٲٹھـ̡ ژے پۯاوُن چُھ، تِتھے پٲٹھـ̡ گژھہِ تۅہہِ سٍتـ̡ کرنہٕ۔ تہٕ تٔمۍ سُند خادم گۆو أتھۍ ساعتس مَنٛز شفا ۔ \n14. تہٕ ییلہ عیسیٰ پطرس سٕندِس گرس منز آو، تٔمۍ وُچھ پننہِ زنانہِ ہٕنز موج تہٕ تپھ بٮ۪مار۔ \n15.\\tتہٕ تٔمۍ کٔر تٔمۍ سٕندِس اتھس تھپھ، تہٕ تپھ دراو أمِس تہٕ سۅ ووٚتھ، تہٕ کٔرٕن تِمن ہٕنز خدمت۔ \n16.\\tییلہ یێلہِ ووت تِمو أمِس نِش واریاہ یِم شیطانن ہٕندِس سٍتـ̡ ٲسۍ، تہٕ تٔمۍ کٔرٕن روحن ہٕندِس کلامَس سٍتـ̡ ژٔٹِتھ تہٕ سارِنٕے بیمار کٔرِن شفا ۔ \n17.\\tیُس یُس عیسیٰ رسولن وونمت اوس زِ پانہٕ کٔر سانہِ بیمارِ ہٕنزِ بیمارِ ہٕندِس سٍتـ̡ پورٕ سپدُن۔ \n18.\\tییلہ حضرت عیسیٰ علیہ السلام پانس اندۍ پکھۍ واریاہ بٔڈ وُچھ، تمٔۍ دیُت دوٚیمہِ طرفہٕ نیرنُک حُکم۔ \n19.\\tتہٕ اَکھ کاتب آو تہٕ وونُن أمِس مالک، ییتہِ تہِ ژٕ گژھِ، بہٕ کَرٕ ژےٚ پتہٕ۔ \n20. تہٕ عیسیٰ مسیح چُھ أمِس ونان زِ پۄژھہٕ پٲٹھۍ، تہٕ ہوہٕکۍ جاناوارن چھِ گُرٕ آسان۔ مگر انسان سٕندِس نیٚچوِس چُھنہٕ کَتہِ کَلہٕ تراوُن۔ \n21.\\tتہٕ تٔمۍ سٕندِس بیٚیِس شٲگِرَن ووٚن أمِس زِ خداوند، بہٕ دِیُن گۅڈٕ پنُن مول دفن کرنہٕ۔ \n22.\\tمگر حضرت عیسیٰ علیہ السلام ووٚن أمِس زِ میانہِ پٲٹھۍ۔ تہٕ پَنٕنـ̡ \n23.\\tییلہ سُہ أکِس جہازس منز اژنہٕ آو تہٕ تٔمۍ سٕندِ شٲگِر گٔیہِ أمِس پَتہٕ۔ \n24.\\tتہٕ وُچھِتھ آو سمندرس منز اکھ زبردست واوُن، یوت تام جہازٕ لہرٕ سٍتۍ ؤلِتھ اوس، مگر سُہ اوس شوٚنگِتھ۔ \n25.\\tتہٕ تٔمۍ سٕندِ شٲگِر آیہِ أمِس نِش تہٕ ووٚنُن زِ خداوند، اسہِ بچاو، أسۍ چھِ فنا گٔژھان۔ \n26.\\tتہٕ سُہ چُھ تِمن ونان زِ اے کم ایمانٕکۍ کیازِ چھِو کھوژان؟ پَتہٕ ووٚتھ ووٚتھ، تہٕ واو تہٕ سمندرس ملامت کٔرِتھ۔ تہٕ اَتہِ گۆو سٮ۪ٹھاہ سکون۔ \n27.\\tمگر مرد گٔیہِ حٲران زِ یہِ کُس انسان چُھ، یُس واو تہٕ سمندرٕ تہِ چھُ أمِس اطاعت کران! \n28.\\tتہٕ ییلہ سُہ دوٚیمہِ طرفہٕ گرجیسینس ہٕندِس ملکس منز آو، تتہِ سمکھیوو أمِس زٕ شیطان سٍتۍ، قبرو منزٕ نیبر نیران، یُس نہٕ کانہہ تہِ انسان اَتھ وتہِ نیرِ۔ \n29.\\tتہٕ وُچھِتھ دِژ تِمو کرٛٮ۪کھ دِتھ زِ اسہِ کیا چُھہ ژے عیسیٰ سٕندِس سٍتـ̡ \n30.\\tتہٕ تِمن نِش اوس واریہن سورن ہُند کھیٚنہٕ دِنہٕ خٲطرٕ اکھ رژھ وتھ۔ \n31.\\tیێلہِ دِژ شیطانو أمِس گُزٲرِتھ زِ یێلہِ ژے اسہِ کٔڈِتھ کٔرِو اسہِ سورن ہٕندِس کھورِس مَنٛز نیرُن۔ \n32.\\tتہٕ تٔمۍ ووٚن تِمن گژھِ۔ تہٕ ییلہ تِم نٮ۪بر دِنہٕ آیہ، تِم گٔیہِ سورن ہٕندِس کھیٚلس منز، تہٕ وُچھِتھ گٔیہِ سورن ہُند سورُے کھیٚلہٕ سمندرس مَنٛز، تہٕ گٔیہِ آبس مَنٛز ختم۔ \n33.\\tتہٕ یِمو تِم رٔٹِتھ ژٔلِتھ گٔیہِ شہرس مَنٛز، تہٕ وَنُن پرٮ۪تھ کُنہِ چیز، تہٕ یُس شیطانن ہٕندِس قبضس سٍتـ̡ سپدیومُت اوس۔ \n34.\\tتہٕ وُچھ سورُے شہر عیسیٰ مسیحس سمکھنہٕ خٲطرٕ درٛاوُن، تہٕ ییلہ تمو أمس وُچھ، تِمو کٔر أمِس التجا زِ سُہ گژھہِ تِہندِ ساحلہٕ نِش نیرُن۔","1.\\tتہٕ سُہ ژاو أکِس جہازس منز، تہٕ ووت پننِس شہرس منز۔ \n2.\\tتہٕ وُچھِتھ اوٚن تِمو أمِس نِش اَکھ شخٕص یُس فالج ہٕندِس بٮ۪مارس پیٹھ لٔگِتھ اوس، تہٕ حضرت عیسیٰ علیہ السلام وُچھِتھ یُس تِہُند ایمان وُچھِتھ فالج ہٕندِس بیمارس وونُن۔ پَنٕنـ̡ پٲٹھـ̡ گۅناہ گژھہِ معاف۔ \n3.\\tتہِ وچھو کینژو کاتبو پانس اندر ونان، یہِ {انسان} چھہ کفر کران۔ \n4.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن تِہٕندِس خیالس منز کیازِ چُھہ بُرٕ سوزان؟ \n5.\\tتکیازِ یہ ونُن چھا سہل زِ {چانہِ} گۅناہ گژھہِ معاف۔ یا یہ ونُن زِ وۅتھُن تہٕ پکُن؟ \n6. مگر یێلہِ تۅہہِ زانہِ زِ انسان سُند فرزند چُھ زمینس پیٹھ گۅنہہ معافی دِنُک اِقت تھاوان، (تیلہِ چُھ سُہ فالج وٲلِس بیمارس ونان ،) وۅتھٕ وُتھ، پنُن بسترٕ رٔٹِو، تہٕ گژھ پنہٕ نِس گرس منز۔ \n7. تہٕ سُہ ووٚتھ، تہٕ دراو پننِس گرس کُن۔ \n8.\\tمگر ییلہ لُکن وُچھ، تِمو گٔے حٲران تہٕ خدایہ سٕنز حمد کٔرٕن، یٔمۍ انسانس یژھ طاقت دِژمٕژ ٲس۔ \n9. تہٕ یێلہِ عیسیٰ مسیح تتہِ پۯاو، تٔمِس وُچھ میتھیو ناوُک اکھ شخٕص یُس رسمہٕ کِس رسیدس پیٹھ بِہِتھ اوس، تہٕ سُہ چُھ أمِس وَنُن، میانہِ پٲٹھۍ۔ تہٕ سُہ ووٚتھ تہٕ أمِس پَتہٕ پَتہٕ۔ \n10. تہٕ سپُد عیسیٰ مسیح گرس منز مازس پیٹھ بِہتھ، وُچھ واریاہ پبلکن تہٕ گۅنہگار آیہِ أمِس تہٕ تٔمۍ سٕندٮ۪ن شاگردن سٍتـ̡ بِہتھ۔ \n11.\\tتہٕ ییلہ فریسیو وُچھ، تِمو ووٚن تٔمۍ سٕندٮ۪ن شاگردن زِ کیازِ چُھہ پنُن آقا پبلکن تہٕ گۅنہگارن سٍتـ̡ کھٮ۪وان؟ \n12.\\tمگر یێلہِ حضرت عیسیٰ علیہ السلام بوٗز، تِمن وۆنُن یێلہِ \n13. مگر گژھ تہٕ ہیچھِو تہٕ یێمہِ سُند مطلب کیا چُھ، بہٕ کرٕ رحم تہٕ قربانی نہٕ: کیازِ بہٕ چُھس نہٕ نیکوکارن بلاونہٕ خٲطرٕ آمُت بلکہ گۅنہگارن توبہ کرنہٕ خٲطرٕ۔ \n14. اَمہِ پتہٕ آو یوحنا سٕندِ شٲگِر أمِس نِش وَنُن، أسۍ تہٕ فریسی کیازِ چھِ روزٕ تھاوان، مگر تُہند شٲگِر چھِ نہٕ روزٕ تھاوان؟ \n15. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمن زِ مہرازٕ یِمن سٍتـ̡ یێلہِ مہرازٕ تِمن سٍتـ̡ آسہِ، کیا مہرازٕکۍ شُرۍ ہیکن ماتم کٔرِتھ؟ مگر سُہ دۅہ یِن یێلہِ مہرازٕ یِن تِمن نِش نِنہٕ، تہٕ پَتہٕ روزٕ تھاوُن۔ \n16.\\tکانہہ تہِ انسان چھہ نہ نوِ پلو پرانہِ پلوس منز تراوان، تکیازِ یُس اتھ برنہ خاطرہ تراونہ یوان چھہ سہ چھہ پلو منزہ نیران، تہ کرایہ چھہ بدتر گژھان۔ {نٔوۍ: یا، خام یا، بے ساختہ}\n17.\\tنتہ چھہ انسان پرانین بوتلن منز نوو شراب تراوان: نتہ چھہ بوتلہِ پھٹان تہ شراب ختم گژھان تہ بوتلہِ چھیہ ختم گژھان: مگر یم چھہِ نوِ نوِ شراب نوین بوتلن منز تراوان، تہ دۅشوے چھہِ محفوظ۔ {بوتلہٕ: یا، ژمہِ ہٕنزِ بورۍ، یا چمٕر}\n18.\\tیێلہِ تٔمۍ یِمن سٍتـ̡ یِم کتھ کٔرِتھ، وُچھِتھ آو اَکھ حُکُمران تہٕ تٔمِس پوٗزا کٔرِتھ وَنُن زِ میٲنۍ کوٗر چھے وُنہِ تہِ موٗدمٕژ، مگر یِمو پَنُن اَتھٕ تٔمِس پٲٹھۍ، تہٕ سُہ روزِ زندٕ۔ \n19.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚتھ تہٕ أمِس پتہٕ تہٕ تٔمۍ سٕندِس شٲگِرِس تہٕ تٔمۍ سٕندِس شٲگِرِس تہِ گٔیہِ۔ \n20.\\tتہ وچھ اکھ زنانہ، یۅسہ باہ ؤری خونس منز مبتلا ٲس، آیہِ تس پتھ کُن تہ لوٚگ تمۍ سندِس پلوس پیٹھ اتھہ: \n21.\\tتکیازِ تٔمۍ ووٚن پانس اندر، اگر بہٕ تٔمۍ سٕندِس پلوس اَتھٕ لاگہٕ کٔرِتھ، بہٕ روزٕ پورٕ۔ \n22.\\tمگر عیسیٰ مسیحن پھیُر سُہ تہٕ ییلہ أمِس وُچھ، تٔمۍ ووٚن، کورِ، رژھ۔ چانہِ ایمانن کٔر ژے پورٕ۔ تہٕ زنانہِ گٔیہِ تمہِ ساعتہ پورٕ۔ \n23.\\tتہٕ یێلہِ عیسیٰ علیہ السلام حکمران سٕندِس گرس مَنٛز آو تہٕ وُچھن مُلکن تہٕ لُکھ شور کٔرِتھ، \n24.\\tتٔمۍ ووٚن تِمن جاے دِیُن، تکیازِ دٲر چھے نہٕ مٔرِتھ بلکہ شوٚنگِتھ ۔ تہٕ تِمو کٔر أمِس طنز کرنہٕ خٲطرٕ اسُن۔ \n25.\\tمگر ییلہ لُکھ نیبر کڈنہٕ آو، سُہ ژاو اندر تہٕ رٔٹِن أمِس اتھہٕ تھپھ تہٕ دٲر ووٚتھ۔ \n26. تہٕ اَمہ شہرت گٔیہِ اَتھ سارِنٕے سرزمینس منز۔ {شہرت...: یا، یہ شہرت}\n27. تہٕ یێلہِ عیسیٰ مسیح تتہِ نیرِ، زٕ انہِ نفر گٔیہِ أمِس پَتہٕ پَتہٕ، کٔرِتھ وَنُن تہٕ وَنُن، {تُہ} داؤد سُند نیٚچُو، اسہِ پیٹھ رحم کرُن۔ \n28.\\tییلہ سُہ گرس منز آو، انہِ مرد آو أمِس نِش۔ تہٕ عیسیٰ علیہ السلام چُھ تِمن ونان زِ کیا تۅہہ چھُس یقین کران زِ بہٕ چُھس یہ کرِتھ ہیکان؟ تِمو ووٚن أمِس آ، اے خداوند۔ \n29.\\tاَمہِ پتہٕ دِژ تِمن ہٕنزِ أچھن تھپھ کٔرِتھ وونُن، تُہٕندِس عقیدس مُطٲبق گژھہِ تۅہہِ سٍتـ̡ ۔ \n30.\\tتہٕ تِہٕنزِ أچھ گٔیہِ یلہٕ۔ تہٕ حضرت عیسیٰ علیہ السلام دِژ تِمن ہُند دُبارٕ دِتھ وُچھِتھ زِ وُچھِو نہٕ کٲنسہ تہِ انسانس پتاہ۔ \n31.\\tمگر تِمو ییلہ تِم نیرِ، تِمو پھٲلٲو تٔمۍ سٕنز شہرت سٲرۍسٕے ملکس منز۔ \n32.\\tییلہ تِم نیبر درایہ، وُچھ تِمو أمِس نِش اَکھ کوٚنگُر شخٕص یُس شیطان اوس۔ \n33.\\tتہٕ ییلہ شیطان کٔڈِتھ کٔرِتھ وُچھُن زِ یہِ اوس نہٕ اسرٲیلِس مَنٛز زانہہ تہِ وُچھنہٕ آمُت۔ \n34.\\tمگر فریسیو ووٚن زِ سُہ چُھ شیطانن ہٕندِس شہزادس سٍتـ̡ شیطان کڈان۔ \n35. تہٕ عیسیٰ علیہ السلام اوس سارنٕے شہرن تہٕ گامن مَنٛز پٔکِتھ تہٕ تِمن ہٕندِس عبادت خانن مَنٛز پرناوان تہٕ بادشٲہی ہٕنز خوشخبری دِژٕن، تہٕ لُکن مَنٛز کٔرٕن پرٮ۪تھ کُنہِ بیمارِ تہٕ پرٮ۪تھ بیمارِ شفا دِوان۔ \n36.\\tمگر ییلہ تٔمۍ یہ ہجوم وُچھ، سُہ گوٚو تِمن پیٹھ رحم کٔرِتھ، تِکیازِ تِم گٔیہِ بے ہوش، تہٕ گٔیہٕ نٮ۪بر کُن پھٔلِتھ، یِمن ہٕندِ پٲٹھۍ، یِمن نہٕ کُنہِ کٔرِتھ گٔیہِ۔ {بیہوش...: یا، تھوٚکِتھ لٔگِتھ}\n37.\\tتێلہِ چُھ سُہ پننین شاگردن ونان زِ فصلہٕ چُھ پٔزۍ پٲٹھـ̡ سٮ۪ٹھاہ زیادٕ، مگر مزدور چِھہ کم۔ \n38. تَمہِ مۄکھٕ کٔرِو فصلُک مٲلک، یُس سُہ سوزِ پننِس فصلس مَنٛز مزور۔","1.\\tتہٕ ییلہ تٔمۍ پننین بہن شاگردن بُلوو، تمٔۍ دِژ تِمن ناپاک روحن خٕلاف، تِمن کٔڑِتھ تہٕ پرٮ۪تھ قٕسمٕچ بیمارِ تہٕ پرٮ۪تھ قٕسمٕچ بیمارِ شفا دِنٕچ طاقت۔ {خلاف: یا، زیادٕ}\n2. وۅنۍ چُھ بہن رسولن ہٕندِ ناو یِم؛ گۄڈنیُک، شمع، یُس پطرس ونان چُھ، تہٕ اندریوس سُند بوے چُھ؛ یعقوب سُند نیچو، تہٕ یوحنا سُند بوے چُھ؛ \n3. فلپ، تہٕ بارتھولومیو؛ تھامس، تہٕ میتھیو دی پبلکن؛ جیمز {نیچو} الفائیس، تہٕ لیبیئس، ییٚمۍ سٕنٛز کنیت تھیڈیئس ٲس۔ \n4. شمعون کنعانی، تہٕ یہوداہ اسکریوتی، ییٚمۍ أمس تہٕ دھوکہ دِژ۔ \n5.\\tیِمو باہ عیسیٰ علیہ السلام سوٗزۍ تہٕ دِتُکھ حُکُم زِ غیر قومن ہٕنزِ وتہِ مَنٛز گژھ نہٕ تہٕ سامری ہٕندِس شہرس مَنٛز اژُن نہٕ۔ \n6.\\tمگر گژھ اسرٲیلِہ کِس گرِ کِس رٲوِمٕتِس کۅکرس کُن۔ \n7. تہٕ یێلہِ چُھہ تبلیغ کٔرِتھ ونان زِ اسمانٕچ بادشٲہی چھے اتھس منز۔ \n8. بیمارن ٹھیک کرُن، کوڑھ پاک کرُن، مُردٕ زندٕ کرُن، شیطان کٔرِو دِن: آزادانہٕ سٍتـ̡ دِیُو۔ \n9. پننِس پرسس منز کٔرِو نہ سۄن، نہ رۄپھ، تہٕ نہ پیتل، {فراہم: یا، حٲصِل}\n10.\\tنہ چھہ نہ دۅشوے کوٹ، نہ کھورِ تہ نہ کھورِ تہ نہ چھہ وُنہِ تہِ لۅتہِ: تکیازِ مزدور چھہ پننہِ مازس لایق۔ {لاٹھۍ:Gr. اکھ عصا}\n11. تہٕ یُس تہِ شہرس یا قصبس مَنٛز اژِو، پرژھو زِ اتھ منز کُس چُھ لایق۔ تہٕ تتہِ روزِو توٚت تام روزُن۔ \n12. تہٕ ییلہ تہٕ کُنہِ گرس منز اژِو، تٔمِس کٔرِو سلام۔ \n13. تہٕ اگر گرٕ لایق آسہِ، تیلہِ گژھہِ پنُن امن اتھ پیٹھ واپس، مگر اگر یہ لایق آسہِ نہ، تیلہِ گژھہِ پنُن امن پانس نِش واپس۔ \n14.\\tیُس نہٕ تۅہہِ رٔٹِتھ تہٕ تُہٕندِس کلامَس بوزِ، یێلہِ تہٕ تُہٕندِس گَرٕ یا شہرٕ منزٕ نیرِو، تُہٕندِس کھورِ ہٕنزِ گرد ژٔٹِو۔ \n15. بہٕ چُھس ژے ونان زِ قیامتس مَنٛز گژھہِ سدوم تہٕ گومورہ ہٕندِ سرزمینہٕ خٲطرٕ تمہِ شہرٕ کھوتہٕ زیادٕ برداش۔ \n16.\\tوُچھ، بہٕ چھُس ژے رامہٕ ہٕندِس درمِس منز کۅکرِ ہٕندِس پٲٹھـ̡ سوزان: تێمہِ کِنۍ گژھِو ناپَن ہٕندۍ پٲٹھۍ، تہٕ کۅترن ہٕندۍ پٲٹھـ̡ بے ضرر۔ {بے ضرر: یا، سادٕ}\n17.\\tمگر انسانس نِش گژھہِ ہوشیار روزُن، تکیازِ تِم کرِ تۅہہِ مجلسن تام واتناوُن، تہٕ تِم کرِ تۅہہِ پننین عبادت خانن مَنٛز کوٹھہٕ دِنہٕ۔ \n18.\\tتہٕ یِن تِمن تہٕ غیر قومن خلاف گوٲہی دِنہٕ خٲطرٕ گورنرن تہٕ بادشاہن برونہہ کُن اننہٕ۔ \n19. مگر ییلہ تم توہہِ حوالہٕ دِن، تہٕ یہ سوچو نہٕ زِ تہٕ کیا کتھ کرِو، تکیازِ تۅہہِ یُس تہِ کتھ کرِ، سُہ ییہ تتھۍ ساعتس منز دِنہٕ۔ \n20. تِکیازِ تُہۍ چھِنہٕ کتھ کران بلکہ چُھہ پننِس مٲلہِ سُند روح یُس تۅہہِ مَنٛز کتھ کران چُھ۔ \n21.\\tتہٕ بٲے دِیہِ بٲے مارنہٕ خٲطرٕ، تہٕ بچہٕ گژھن مٲلِس ماجہ سٍتـ̡ کھڑا تہٕ تِمن مارنہٕ یِن۔ \n22. تہٕ میانہِ ناوٕ خٲطرٕ گژھہِ سارِنٕے انسانس سٍتـ̡ نفرت، مگر یُس ٲخرس تام برداشت کرِ، سُہ گژھہِ نجات دِنہٕ۔ \n23. مگر ییلہ تم اتھ شہرس منز تۅہہِ ستاونہٕ یِن، تہٕ ژٔلِو بییِس شہرس مَنٛز، تکیازِ بہٕ چُھس ژیہ ونان زِ تۅہہ گژھِو نہٕ اسرٲیلِک شہرن پیٹھ، یوتام نہٕ انسان سُند فرزند یِنہٕ۔ {ہاو...: یا، ختم، یا ختم کرُن}\n24.\\tشٲگِر چُھنہٕ پننِس آقا سٕندِس آقا سٍتـ̡ تہٕ نہ چُھہ خادم پننِس مالہٕ سٍتـ̡ پیٹھ۔ \n25.\\tشٲگِرِس سٕندِ خٲطرٕ چُھ یہِ کٲفی زِ سُہ آسہِ پَنُن مٲلک، تہٕ خادمَس پَنُن مٲلک۔ یێلہِ تِمو گرُک مٲلِک بِلزیبُب بُلوومُت چُھ، تِم کوتاہ بییہ تہِ وَنُن تِمن ہٕندِس گرس مَنٛز؟ {بیلزیبُب: Gr. Beelzebul}\n26.\\tتِمن ہُند خوف گژھِ نہٕ: تِکیازِ یُس نہٕ ظٲہر سپدِ، یُس نہٕ ظٲہِر سپدِ۔ تہٕ یُس نہٕ پتاہ گژھِ۔ \n27.\\tیُس بہٕ ژے اوندپِس منز ونان چھُس، {یہ} گاشس منز کتھ کرُن: تہٕ یُس تہٕ یُس تہٕ یُس تہٕ کُنہِ \n28.\\tتہٕ تِمن سٍتـ̡ گژھہِ نہٕ تِمن سٍتـ̡ کھوژُن یُس جسمس ماران چُھ، مگر روح مارنس لایق چُھہ نہٕ، بلکہ گژھہِ تٔمِس سٍتـ̡ کھوژُن یُس جہنمَس مَنٛز روح تہٕ جسم دۅشوے تباہ کٔرِتھ آسہِ۔ \n29.\\tکیا زٕ چُرِ چھِنہٕ أکِس پھورس منز کٕننہٕ یِوان؟ تہٕ یِمو منزٕ اکھ گژھِ نہٕ تُہندِ مٲلہِ سٕندِ بغٲر زمینس پیٹھ پیوٚو۔ {فارتھنگ: یہِ چُھ اصلس مَنٛز نصف پونسہٕ فارتھنگ، یُس رومی پونسہٕ ہُند دٔہِم حصہٕ چُھ}\n30.\\tمگر تُہٕندِس کَلہٕ سٍتۍ چھِ سارِنٕے مَس گنزراونہٕ آمٕتۍ۔ \n31.\\tتَمہِ کِنۍ چھُنہٕ ژےٚ کھوژُن، تۅہہِ چھِو واریہن گورِیو کھۅتہٕ زیادٕ قٲمِل ۔ \n32. یُس تہِ یُس میہ انسانن برونہہ کنہِ اقرار کرِ، سُہ تہِ کرٕ پننِس مٲلس برونہہ کُن یُس جنتس منز چُھ۔ \n33. مگر یُس تہِ انسانس برونہہ کنہِ میہ انکار کرِ، بہٕ تہِ کرٕ پننِس مٲلس برونہہ کُن یُس آسمانس منز چُھ۔ \n34.\\tیہ نہ سوچو زِ بہٕ چھُس زمینس پیٹھ امن سوزنہِ آمُت: بہٕ چھُس نہ امن سوزنہِ آمُت بلکہ تلوار سوزنہِ آمُت۔ \n35. تکیازِ بہٕ چُھس أکِس مردس پننِس مٲلس سٍتـ̡ تہٕ کورِ ماجہ سٍتـ̡ تہٕ کورِ ماجہ سٍتـ̡ اختلاف کرُن۔ \n36.\\tتہٕ انسان سٕندِ دُشمن آسہِ تٔمۍ سٕندِس گرس سٍتـ̡ دُشمن ہٕندِس دُشمن سٍتـ̡ ۔ \n37.\\tیُس مٲلِس یا ماجہِ میانہِ کھوتہٕ زیادٕ محبت کران چُھ، سُہ چُھنہٕ میانہِ لایق تہٕ یُس میانہِ کھوتہٕ زیادٕ نیچوِس یا کورِ سٍتـ̡ محبت کران چُھ، سُہ چُھنہٕ میانہِ خٲطرٕ لایق۔ \n38.\\tیُس نہٕ پَنُن صلیب رٔٹِتھ تہٕ میانہِ پَتہٕ پَتہٕ پَکُن روزِ، سُہ چُھنہٕ میانہِ لایق۔ \n39.\\tیُس پَنُن زُو میلہِ سُہ سُہ راوُن، تہٕ یُس میانہِ خٲطرٕ پنُن زُو راوان آسہِ، سُہ میلہِ سُہ میلہِ۔ \n40. یُس تہٕ یُس تہٕ یُس میہ رٔٹان چُھ، سُہ چُھ سُہ میلان یُس مے سوزان چُھ۔ \n41. یُس نبی سٕندِ ناوٕ سٍتـ̡ پیغمبر رٔٹِتھ چُھہ سُہ پیغمبر سُند اجر میلہِ۔ یُس نیک انسان سٕندِس ناوس پیٹھ نیک انسان رٔٹِتھ آسہِ، تس میلہِ نیک سُند اَجر۔ \n42. تہٕ یُس یِمو منزٕ أکِس شُرۍ سٕندِس ناوس پیٹھ سرد پیالہ چیٚنہٕ دِیہِ، بہٕ چُھس ژےٚ ونان زِ سُہ گژھِ نہٕ کُنہِ تہِ پَنُن انعام۔","1. تہٕ سپُد یێلہِ حضرت عیسیٰ علیہ السلام پننین بہن شاگردن ہُند حُکُم ختم کٔرِتھ، سُہ دراو تتہِ تِہندین شہرن مَنٛز پرناونہٕ تہٕ تبلیغ کرنہٕ خٲطرٕ۔ \n2. وۅنۍ ییلہ یوحنا جیلس مَنٛز مسیح سٕنز کٲم بوز، تٔمۍ سوٗزۍ پَنٕنۍ زٕ شٲگِر، \n3.\\tتہٕ وونُن تٔمِس سُہ یُس یِوان چھُ، کِنہ أسۍ چھِو بییِس س� \n4.\\tحضرت عیسیٰ علیہ السلام دِیُت جواب تہٕ وونُن تِمن گژھِو تہٕ یوحنا ہٲوِو تِم چیز یِم تُہۍ بوزان تہٕ وُچھان چھِو: \n5.\\tانہِ گاش چُھہ رٔٹِتھ تہٕ لوٚنگہِ پکان چُھ، کوڑھ چھِ پاک سپدان، تہٕ بہرِ بوزان چُھ، مُردٕ چِھ زندٕ سپدان تہٕ غریبن چُھ تِمن انجیل ہٕنز تبلیغ کران۔ \n6. تہٕ بابرکت چُھہ {سُہ}، یُس نہٕ میانہِ مَنٛز ناراض گژھہِ۔ \n7. تہٕ یێلہِ تِم درٛاو، حضرت عیسیٰ علیہ السلام ہیوٚت یوحنا سٕندِس بارس مُتعلِق بٔڈِس لٔگِس وَنُن، تہٕ ژیہ کیا گۆو بیابانن مَنٛز وُچھنہٕ خٲطرٕ؟ واو سٍتـ̡ ہُند نِلہٕ ہُراونہٕ آمُت؟ \n8.\\tمگر ژیہ کیا وُچھِتھ نیبر نیرِو؟ نرم پوشاک لٲگِتھ انسان چھُ؟ وُچھِو یِم نرم پوشاک لاگان چھِ، تِم چھِ بادشاہن ہٕندِس گَرَس مَنٛز۔ \n9.\\tمگر ژیہ کیا گۆو وچھنہٕ خٲطرٕ؟ اکھ پیغمبر؟ آ، بہٕ چُھس ژے ونان، تہٕ پیغمبر کھۅتہٕ زیادٕ۔ \n10.\\tیێمہِ سٍتـ̡ چُھہ یێمہِ سٍتـ̡ لیکھنہٕ آمُت چُھ، یێمہِ سٍتـ̡ چُھہ تُہٕندِس بُتھِس برونہہ کُن پَنُن قاصد سوزان، یُس تۅہہِ برونہہ کُن وَتھ تیار کرِ۔ \n11. بہٕ چُھس ژےٚ وَنُن زِ یُس زنانہٕ سٍتـ̡ پٲدٕ سپدان چُھہ، تِمن مَنٛز چُھنہٕ یوحنا بپتسمہ دِنہٕ وٲلِس سٍتـ̡ بٔڈ تہٕ بٔڈ سُہ چُھہ یێمہِ سٍتـ̡ بپتسمہ دِنہٕ آمُت۔ \n12. تہٕ یوحنا بپتسمہ دِنہٕ وٲلِس زمانہٕ پیٹھٕ وُنیُک تام چُھ آسمانٕچ بادشٲہی تشددُک شکار سپدان، تہٕ تشدد کرن وٲلۍ چھِ اتھ زبردستی نِوان۔ {مصیبت...: یا، چُھ زبردستی حٲصل کرنہٕ آمُت، تہٕ یِم انسانس زور دِوان چِھ}\n13.\\tسارِنٕے پیغمبرن تہٕ شریعتٕچ پیشن گویی کٔر یوحنا ہس تام۔ \n14.\\tتہِ اگر ژیہ میلہِ، یہ چھہ الیاس، یُس یُس یِنہٕ وول اوس۔ \n15.\\tیُس بوزُن آسہِ، سہ بوزُن۔ \n16.\\tمگر بہٕ کَتہِ کَرٕ یَتھ نسلس ہُند تشبیہ؟ یہِ چُھ یِتھٕ پٲٹھۍ بازرَن مَنٛز بِہِتھ شُرین ہٕندِس پٲٹھۍ، تہٕ پننین سٲتھین بلاوان چھِ، \n17. تہٕ ونُن، أسۍ چُھہ ژےٚ نژان، تہٕ ژے چُھکھ نہٕ نژان۔ أسۍ چھِ ژےٚ خٲطرٕ ماتم کٔرمٕژ، تہٕ ژے چُھکھ نہٕ ماتم کٔرمٕژ۔ \n18.\\tیوحنا آو نہ کھٮ۪وان تہٕ نہ چیوان تہٕ تِم چھہِ ونان زِ تس چُھ شیطان۔ \n19.\\tانسان سُند نیچو آو کھٮ۪وان چیوان تہٕ تِم چھِ ونان زِ وُچھِو اَکھ شُمار تہٕ شرابُک یُس پبلکن تہٕ گۅنہگارن ہُند دوس چھُ۔ مگر حکمت چھے تٔمۍ سٕندِس شُرٮ۪ن ہٕندِس دٲیرٕ سٍتـ̡ دِنہٕ آمٕژ۔ \n20.\\tتمہِ پتہ ہیوٚتُن تِمن شہرن ہٕنز بدتمیزی کرٕنۍ، تکیازِ تِمو کٔر نہٕ توبہ کرنہٕ۔ \n21.\\tہا ہا خوراسین! ہا ہا تۅہہِ ہٕندِس کامہِ سٍتـ̡ یێلہِ سٍتـ̡ یێلہِ یِم بٔرِتھ تہٕ سٍتـ̡ سٍتـ̡ پى۪ٹھـ̡ پٲٹھـ̡ توبہ کٔرِتھ۔ \n22. مگر بہٕ چُھس ژے ونان زِ قیامتُک دۅہہٕ آسہِ صور تہٕ صیدون سٕندِ خٲطرٕ ژےٚ کھوتہٕ زیادٕ برداش۔ \n23. تہٕ توہ، کفرناؤم، یُس جنتس مَنٛز تھزراونہٕ آمُت چُھ، یُس جہنمَس مَنٛز واتناونہٕ یِن، یێلہِ یێلہِ سَدومَس مَنٛز یِم عظیم کٲم کرنہٕ آمٕژ آسہِ، سُہ آسِہا از تام روزُن۔ \n24. مگر بہٕ چُھس ژے ونان زِ قیامت کہ دۅہہٕ گژھہِ سدوم کِس سرزمینس خٲطرٕ ژےٚ کھوتہٕ زیادٕ برداش۔ \n25. اَمہِ وِزِ دِیُت عیسیٰ مسیحن جواب تہٕ وونُن، اے باپ، آسمانُک تہٕ زمینُک رب، بہٕ چُھس تُہند شُکر ادا کران تکیازِ ژے چُھکھ یِم چیز دانشمندن تہٕ دانشمندن نِش ژوٗرِ تھوومُت، تہٕ یِم چھِ بچن ہٕندِ خٲطرٕ ظٲہر کٔرۍمٕتۍ۔ \n26.\\tتوتہِ چھہ بابا: تکیازِ یہ اوس تۅہہِ نظرِ منز اصل باسان۔ \n27. سٲری چیز چُھہ میٲنس مٲلس سٍتـ̡ دِنہٕ آمُت: تہٕ کانہہ تہِ انسان چُھہ نہٕ نیچوس سٍتـ̡ زانان، مگر مٲلِس سٍتـ̡ چُھہ زانان۔ نۂ تہٕ چُھہ کُنہِ تہِ شخصس مٲلِس سٍتـ̡ زانان، سوائے نیچو، تہٕ یێمِس سٍتـ̡ نیچو ظٲہر کرِ۔ \n28.\\tیِمو سارِوٕے محنتہٕ تہٕ بٔرِتھ چھِو، تہٕ بہٕ دِیہ ژے آرام دِنہٕ۔ \n29.\\tمیون جولہٕ رٔٹِو پانس پیٹھ، تہٕ میانہِ نِش ہیچھِو۔ تِکیازِ بہٕ چُھس دِلَس مَنٛز نرم تہٕ کمتر تہٕ ژے میلہٕ پنٕنٮ۪ن روحن آرام دِنہٕ۔ \n30.\\tمیانہِ خٲطرٕ چُھ آسان تہٕ میون بوجھ چُھ ہلکہٕ۔","1. تمہِ وِزِ گۆو عیسیٰ علیہ السلام سبت دۅہہٕ مکایہِ مٔنزۍ مٔنزۍ ۔ تہٕ تٔمۍ سٕندِ شٲگِرِ گٔیہِ ہُرۍ، تہٕ ہیوٚتُکھ مکایہِ ہٕندِ کُن تُلنہٕ تہٕ کھٮ۪نہٕ خٲطرٕ۔ \n2. مگر ییلہ فریسیو وُچھ، تِمو ووٚن أمِس زِ وُچھِو تُہند شٲگِر سُہ کٔرِتھ یُس سبت دۅہہٕ کرُن چُھہ نہٕ جٲیز۔ \n3. مگر تٔمۍ ووٚن تِمن زِ کیا چُھہ نہٕ پٔرِمُت زِ داؤد کیا کوٚر ، ییلہ سُہ ہُند ہُرٕ اوس، تہٕ تِم یِم أمِس سٍتـ̡ ٲسۍ۔ \n4. سُہ کِتھہ پٲٹھـ̡ ژاو خدایہ سٕندِس گرس مَنٛز، تہٕ کھیوٚن سُہ روٹی یُس نہٕ أمِس سٍتـ̡ کھٮ۪نہٕ خٲطرٕ حلال اوس، تہٕ نہ تِمن ہٕندِ خٲطرٕ یُس أمِس سٍتـ̡ اوس، بلکہ صرف پادٕرین ہٕندِ خٲطرٕ۔ \n5. یا چُھہ نہٕ شریعت مَنٛز پٔرِمُت زِ سبت دۅہہٕ چِھہ پادٕرۍ سبت دۅہہٕ ناپاک کران، تہٕ بے عیب چھِ۔ \n6. مگر بہٕ چُھس ژےٚ ونان زِ اتھ جایہِ چُھ مندرٕ کھوتہٕ بوڈ ۔ \n7.\\tمگر اگر ژیہ پتاہ آسہِ ہے {یہِ} مطلب کیا چُھ، میہ کرِ رحم تہٕ قربانی نہٕ، ژے ہا نہٕ بے گناہ لوکن ہنز مذمت۔ \n8. تکیازِ انسان سُند فرزند چُھ سبت کہ دۅہہٕ تہِ خداوند آسان۔ \n9.\\tتہٕ ییلہ سُہ تتہِ نیرِ، سُہ گۆو تِہٕندِس عبادت خانس مَنٛز: \n10.\\tتہٕ وُچھِتھ اوس اَکھ شخٕص یُس اَتھٕ مروٚزمُت اوس۔ تہٕ تِمو پرژھ أمِس زِ کیا سبت دۅہہٕ چُھہ شفا دِنہٕ یُن جٲیز؟ یُتھ زن تِم أمِس پیٹھ الزام لگٲوِتھ۔ \n11.\\tتہٕ تٔمۍ ووٚن تِمن منز، یُس کُس انسان آسہِ، یُس اکھ دانٛد آسہِ، تہٕ اگر سبت کہ دۅہہ کُنہِ کھۅڈس منز پییہِ، کیا سُہ رٔٹِتھ تھپھ کٔرِتھ تُلِتھ تُلِتھ؟ \n12. تیلہِ کوتاہ چُھ انسان دانٛدٕ کھۅتہٕ بہتر؟ اَمہِ مۄکھٕ چُھ سبت دۅہہٕ رژھرٕ۔ \n13.\\tاَمہِ پَتہٕ چُھ أمِس مردس وَنُن پَنُن اَتھٕ پھٔہلٲوِو۔ تہٕ تٔمۍ کٔر پَنُن اَتھٕ پٲٹھۍ۔ تہٕ سُہ آو پوٗرٕ پٲٹھۍ، یِتھٕ پٲٹھۍ۔ \n14. پَتہٕ گٔیہِ فریسی نیٚبر، تہٕ کٔرٕکھ أمِس خٕلاف مجلس، یِتھ کٔنۍ ہیکَن تِم أمِس تباہ کٔرِتھ۔ {رٔٹِو...: یا، مشورٕ کٔرِتھ}\n15.\\tمگر ییلہ حضرت عیسیٰ علیہ السلام پتاہ لٔگِتھ تہٕ تٔمۍ کٔر تِمن سارِنٕے شفا دِنہٕ۔ \n16.\\tتہٕ تِمن حکم زِ تِم گژھن نہٕ أمِس زاننہٕ یِن: \n17.\\tیُس یُس عیسیٰ پیغمبرن وونمت اوس تہ یہ گژھہِ پورٕ سپدُن، \n18.\\tوُچھِو میون خادم، یُس میہ چُھس ژٲرمُت چُھ؛ میانہِ محبوب، یٔمِس سٍتـ̡ میون روح خوش چُھہ: بہٕ کرٕ پنُن روح أمِس پیٹھ، تہٕ سُہ کرِ غیر قومن ہُند فیصلہٕ۔ \n19. سُہ گژھِ نہٕ کوٗشِش کَرُن، تہٕ نہ کَرُن روُن۔ تہٕ نہٕ کُنہِ تہِ نفر سٕنز آواز سڑکہِ مَنٛز بوزنہٕ۔ \n20. سُہ پھُٹُن نہٕ سُہ پھُٹُن، تہٕ سُہ پھُٹِتھ تہٕ سُہ چُھس نہٕ بٔرِتھ، یوٚت تام نہٕ سُہ فتح کُن فٲصلہٕ دِیہِ۔ \n21. تہٕ غیر قومن ہٕندِس ناوس پیٹھ بھروسہ کرُن۔ \n22.\\tاَمہ پتہٕ آو أمِس نِش یُس شیطان اوس، انہِ تہٕ کوٚنگ، تہٕ تٔمۍ کٔر أمِس شفا دِنہٕ، تیوٗت زِ انہِ تہٕ گونگے دۅشوے کٔر کتھ تہٕ وُچھن۔ \n23.\\tتہٕ سارِوٕے لُکھ گٔیہِ حٲران تہٕ وونُن، کیا یہِ چھُنہٕ داؤد سُند نیٚچُو؟ \n24.\\tمگر ییلہ فریسیو بوٗز، تمو ووٚن زِ یہِ {نفر} چُھ نہٕ شیطان کٔڑِتھ بلکہِ شیطانن ہٕندِس شہزادس بیلزیبوب سٕندِ دٔسۍ کڈنہٕ آمُت۔ {Beelzebub: Gr. Beelzebul}\n25.\\tتہٕ حضرت عیسیٰ علیہ السلام تِمن ہٕندِس خیالس زانان تہٕ تِمن وونُن زِ پرٮ۪تھ کُنہِ بادشٲہی یُس پانس خلاف تقسیم کرنہٕ آمُت چُھ، سُہ چُھ ویران کرنہٕ آمُت۔ تہٕ پرٮ۪تھ کانہہ شہر یا گرٕ یُس پانس خلاف تقسیم کرنہٕ آمُت چُھ، سُہ گژھِ نہٕ کھڑا روزُن: \n26. تہٕ اگر شیطان شیطان کٔڑِتھ کٔرِ، سُہ چُھ پانس خلاف تقسیم سپدان۔ تیلہِ کِتھہ پٲٹھـ̡ تٔمۍ سٕنز بادشاہت کِتھہ پٲٹھۍ؟ \n27. تہٕ اگر بہٕ بیلزبوب سٍتـ̡ شیطان کٔڑِتھ کٔرِتھ، تێلہِ کٔرِو تُہٕندِس شُرِ کٔڈِتھ؟ تێمہِ کِنۍ گژھن تُہند قاضی۔ \n28. مگر اگر بہٕ خدایہ سٕندِ روحہٕ سٍتـ̡ شیطان کٔڈِتھ کٔرِتھ، تیلہِ چُھہ خدایہِ سٕنز بادشٲہی تہٕ تۅہہِ نِش آمٕژ۔ \n29.\\tنتہٕ کِتھہ کٔنۍ ہیکہِ أکِس مضبوٗط شخصہٕ سٕندِس گرس منز اژِتھ، تہٕ تٔمۍ سُند مال خراب کٔرِتھ، یوٚت تام سُہ گۅڈٕ طاقتور شخصس پابند کرِ۔ تہٕ پتہٕ کرِ سُہ پنُن گرٕ بِگاڑ۔ \n30. یُس نہٕ میہ سٍتـ̡ چُھہ سُہ چُھہ میانہِ خلاف۔ تہٕ یُس نہٕ میہ سٍتـ̡ جمع چُھہ سُہ چُھہ بێبرِس پٲٹھـ̡ منتشر سپدان۔ \n31. اَمہِ مۄکھٕ چُھس بہٕ ژےٚ وَنُن زِ سارِنٕے قٕسمٕک گۅناہ تہٕ کفر یِیہِ انسانن خٲطرٕ معاف، مگر {پاک} بھوتَس خلاف گژھِ نہٕ کفر کرنہٕ یِنہٕ انسانن خٲطرٕ معاف۔ \n32. تہٕ یُس تہِ انسان سٕندِس فرزندس خلاف کتھ کرِ، سُہ گژھہِ معاف، مگر یُس تہِ روح القدس خلاف کتھ کرِ، سُہ گژھہِ نہٕ تس معافی دِنہٕ، نہ یتھ دنیاہس مَنٛز تہٕ نہ ینہٕ وٲلِس دنیاہس مَنٛز۔ \n33.\\tیا کُلِس بناوُن اصل تہٕ تٔمۍ سُند پھل بناوُن اصل۔ نتہٕ کُلِس کرُن خراب تہٕ تٔمۍ سُند پھل بناوُن، تکیازِ کُلِس چُھ تٔمۍ سٕندِس پھلہٕ سٍتـ̡ زاننہٕ یِوان۔ \n34.\\tاے سانپَن ہٕنزِ نسلہٕ، ژٕ کِتھ کٔنۍ ہیکِو بد کار آسنہٕ سٍتـ̡ اصل کتھ کٔرِتھ؟ تِکیازِ دِلٕچ کثرت سٍتـ̡ چُھ ٲسٕچ کتھ کران۔ \n35. نیک انسان چُھ دِل کِس نیکی خزانہٕ منزٕ نیران تہٕ بد انسان چُھ بد خزانہٕ منزٕ بد چیز پٲدٕ کران۔ \n36. مگر بہٕ چُھس ژےٚ ونان زِ پرٮ۪تھ کُنہِ بیکار کتھ یُس انسان بولہِ، سُہ کرِ قیامتٕکہِ دۅہہٕ اَمیُک حساب۔ \n37.\\tتکیازِ پننہِ کلامَو سٍتـ̡ گژھہِ تۅہہِ عادل تہٕ پننہِ کلامٕ سٍتـ̡ گژھہِ تۅہہِ مذمت کرنہٕ۔ \n38.\\tپتہٕ دِژ کینہہ کاتب تہٕ فریسیو جواب دِتھ وونُن، مالک، أسۍ وُچھکھ ژے نِش اکھ نشانہٕ۔ \n39.\\tمگر تٔمۍ دِژ جواب تہٕ وونُن تِمن زِ اکھ بد کار تہٕ زنا دار نسل چھے کُنہِ نشانہٕ پتہٕ ژھاران۔ تہٕ اتھ گژھہِ نہٕ کانہہ نشانی دِنہٕ، مگر پیغمبر یونس سٕنزِ نشانہٕ سٍتـ̡ دِنہٕ: \n40. یِتھٕ پٲٹھۍ اوس یونس تریہ دۅہ تہٕ تریہ رٲژ وہیل سٕندِس یٔڈ مَنٛز۔ یِتھے پٲٹھۍ روزِ انسان سُند فرزند تریہ دۅہ تہٕ تریہ رٲژ زمینہِ ہٕندِس دلس منز۔ \n41.\\tنینوا ہٕندِس انسانس گژھن یَتھ نسلس سٍتـ̡ فیصلہٕ کٔرِتھ تہٕ أمِچ مذمت کرٕن: کیازِ تِمو کٔر یونس سٕنزِ تبلیغس پیٹھ توبہٕ۔ تہٕ وُچھِو، یَتہِ چُھہ یونس سٕندِ کھۅتہٕ بوڈ ۔ \n42.\\tجنوبٕچ ملکہ گژھہِ یَتھ نسلس سٍتـ̡ فیصلس مَنٛز وۅتھنہٕ، تہٕ کرِ أمِچ مذمت: تکیازِ سُہ ٲس سُلیمان سٕنز حکمت بوزنہٕ خٲطرٕ زمینہٕ کِس اندۍ پکھۍ پیٹھٕ آمٕژ۔ تہٕ وُچھِو، یێتہِ چُھ سُلیمانس سٍتـ̡ بٔڈ {چُھ}۔ \n43.\\tییلہ ناپاک روح انسان نِش نیران چُھ، سُہ چُھ خشک جاین مٔنزۍ پکان تہٕ آرام ژھاران تہٕ کانہہ تہِ میلان چُھ۔ \n44. اَمہِ پتہٕ چُھس سُہ وَنُن زِ بہٕ واپَس پَنُن گَرٕ یَتہِ پٮ۪ٹھٕ بہٕ نیرِمُت چھُس۔ تہٕ یێلہِ سُہ یِوان چُھ، سُہ چُھس خٲلی، صاف کٔرِتھ تہٕ سجاونہٕ آمُت وُچھان۔ \n45. پَتہٕ چُھ سُہ نیران، تہٕ پانس سٍتـ̡ پانس سٍتـ̡ زیادٕ بدکار سَتھ روحہٕ نِتھ تہٕ تِم اژان تہٕ اَتہِ روزان چُھ: تہٕ أمِس انسان سٕنز ٲخری حالت چُھ گۄڈنِکہِ کھوتہٕ بدتر آسان۔ یێتھے پٲٹھـ̡ آسہِ یێمہِ بدکار نسلہٕ سٍتـ̡ تہِ۔ \n46.\\tییلہ سُہ وُنہِ تہِ لُکن سٍتـ̡ کتھ کران اوس، وُچھِتھ ٲس موج تہٕ تٔمۍ سٕندِ بٲے أمِس سٍتـ̡ کتھ کرنٕچ خواہش۔ \n47. اَمہ پتہٕ ووٚن أمِس زِ وُچھِو، تُہٕنزِ موج تہٕ تُہٕندِ بٲے چھِس نیبر کُن کھڑا تہٕ تۅہہِ سٍتـ̡ کتھ کرٕنـ̡ یژھان۔ \n48.\\tمگر تٔمۍ دِژ جواب تہٕ وونُن أمِس زِ میون موج کُس چُھ؟ تہٕ میٲنۍ بٲے کُس چھِ؟ \n49.\\tتہٕ تٔمۍ پَنُن اَتھٕ پَنٕنِس شٲگِرَن کُن تہٕ وونُن، وُچھِو میانہِ موج تہٕ میانہِ بٲے ! \n50. یُس تہِ میانہِ مٲلہِ سٕنز مرضی کرِ، یُس اسمانس مَنٛز چُھ، سُہ چُھ میون بوے تہٕ بینہِ تہٕ موج۔","1. امی دۅہہ دراو عیسیٰ مسیح گرٕ منزہ نیبر تہٕ بیوٹھ سمندرس بٹھس پیٹھ۔ \n2.\\tتہٕ بٔڈۍ بٔڈۍ لٔگۍ أمِس نِش جمع تہ سُہ گوٚو أکِس جہازس منز تہٕ بیوٹھ۔ تہٕ سورُے ہجوم کھڑا بٹھِس پیٹھ۔ \n3.\\tتہٕ تٔمۍ ووٚن تِمن سٍتـ̡ تمثیلن مَنٛز واریاہ کتھٕ وَنُن، وُچھِو اَکھ کُنہِ سٍتـ̡ وونہٕ آمُت۔ \n4.\\tتہٕ ییلہ تٔمۍ ووت وتہِ نِش کینہہ {بیٲل} پیوٚو تہٕ جاناوار آیہِ تہٕ کھیوٚن تِم کھٮ۪نہٕ۔ \n5.\\tکینہہ پیوٚو کنین جاین پیٹھ، ییتہِ نہٕ تمن زیادہ زمین ٲس، تہٕ یِمن سٍتۍ گٔیہ تِم پھٔٹۍ، تکیازِ تِمن ٲس نہٕ زمینہِ ہُند کانہہ سرٛوٚن: \n6.\\tتہٕ ییلہ آفتاب کھسنہٕ آو، تِم گٔیہِ دزِ۔ تہٕ کیازِ تِمن اوس نہٕ کانہہ موٗل ، تِم گٔیہِ مرز۔ \n7.\\tتہٕ کینہہ گٔیہِ کانٹَن منز۔ تہٕ کُنہِ \n8.\\tمگر باقٕے گٔیہِ اصل زمینہِ منز، تہٕ دِتُکھ میوٕ، کینہہ ہتھ گنہٕ، کینہہ شیٹھ گنہٕ، کینہہ ترہ گنہٕ۔ \n9.\\tیُس بوزُن آسہِ، سُہ بوزُن۔ \n10.\\tتہٕ شٲگِر آیہِ تہٕ وونُن تِمن سٍتـ̡ کیازِ چُھکھ تِمن سٍتـ̡ تمثیلن سٍتـ̡ کتھ کران؟ \n11.\\tتٔمۍ دِژ جواب تہٕ وونُن تِمن کیازِ یہ چُھہ اسمانٕچ بادشٲہی ہٕندِ اسرار زاننہٕ خٲطرٕ دِنہٕ آمُت، مگر تِمن چُھنہٕ یہِ دِنہٕ آمُت۔ \n12. یُس تہِ آسہِ، سُہ ییہِ أمِس دِنہٕ، تہٕ أمِس آسہِ زیادٕ کثرت حٲصِل، مگر یُس نہٕ آسہِ، سُہ ییہِ أمِس نِش نِنہٕ۔ \n13. تێمہِ کِنۍ چُھس بہٕ تِمن سٍتـ̡ تمثیلن سٍتـ̡ کتھ کٔرِتھ: کیازِ تِم چِھہ نہٕ وُچھان۔ تہٕ بوزان چِھہ نہٕ تِم بوزان تہٕ نہ چِھ تِم سمجھان۔ \n14. تہٕ یِمن مَنٛز چھے یسیاس سٕنز پیشن گویی پورٕ سپٕدمٕژ، یُس ونان چُھ، بوزنہٕ سٍتـ̡ تہٕ بوزِو نہٕ سمجُن۔ تہٕ وُچھِتھ تہٕ وُچھِو نہٕ وُچھِو: \n15.\\tتکیازِ یِمن ہُند دِل چُھہ گٔژھمُت، تہٕ تِہٕندِس کَن چُھہ بوزنہٕ سٍتـ̡ سٍتـ̡ تہٕ تِمن ہٕنزِ أچھ چھے بند گٔمٕژ۔ یێلہِ کُنہِ تہِ وِزِ گژھن تِمن اچھو سٍتـ̡ وُچھن، تہٕ بوزنہٕ یِن تہٕ یِمن ہٕندِس دِلہٕ سٍتـ̡ سمجُن، تہٕ یِمن ہٕندِس دِلس سٍتـ̡ گژھن سمجُن، تہٕ بہٕ گژھہِ تِمن شفا دِنہٕ۔ \n16.\\tمگر چانۍ اچھ چھیہ بابرکت تکیازِ تم چھہِ وچھان: تہ تہند کن، تکیازِ تم بوزان چھہِ۔ \n17. یێلہِ بہٕ چُھس تۅہہِ ونان زِ واریاہ پیغمبرن تہٕ نیک انسانو چُھ تِم چیز وُچھنٕچ خواہش کٔرمٕژ یِم تۅہہ وُچھان چھِ، تہٕ تِم چِھ نہٕ وُچھمٕتۍ۔ تہٕ تِم بوزٕنـ̡ یِم تۅہہ بوزان چِھہ، تہٕ بوزمٕژ چِھہ نہٕ۔ \n18.\\tلہذا بوزو کۅکرِ سُند تمثیل۔ \n19. یێلہِ کانہہ شخص بادشٲہی ہُند کلام بوزان چُھ، تہٕ سُہ چُھ نہٕ سمجھان، تیلہِ چُھ بدکار یِوان، تہٕ سُہ چُھ رٔٹِتھ یُس تٔمِس دِلس مَنٛز ووومُت اوس۔ یێمہِ سُہ چُھہ وتہِ سٍتـ̡ بیول میلہِ۔ \n20.\\tمگر یُس بیول کنین منز روٚٹ، سُہ چُھ سُہ یُس کلام بوزان چُھ، تہٕ خوشی سان چُھ یہ وصول کران۔ \n21.\\tتوتہِ چُھہ نہٕ تس پانس مَنٛز جڑ پیوان، بلکہ چُھ کینژَس کالس روزان: کیازِ ییلہ لفظ سٍتـ̡ مصیبت یا فتنہ پٲدٕ سپدِ، سُہ چُھ ناراض سپدان۔ {ناراض: سُہ چُھ دُبارٕ گۅنہٕ گۅنہٕ سٍتـ̡ گُناہ گَژھان}\n22.\\tیُس سُہ تہِ یُس کانٹَن مَنٛز بیول میلان چُھ، سُہ چُھ سُہ یُس کلام بوزان چُھ۔ تہٕ یێمہِ دُنیاہُک خیال تہٕ دولتُک دھوکہٕ دِنہٕ سٍتـ̡ چُھہ کلامُک دم دِنہٕ سٍتـ̡ تہٕ سُہ چُھ بے ثمر سپدان۔ \n23. مگر یُس اصل زمینہِ مَنٛز بیول دِوان چُھ، سُہ چُھ سُہ یُس کلام بوزان چُھ، تہٕ سُہ چُھ سمجھان۔ یُس پھل تہِ دِوان چُھ، تہٕ کُنہِ ہتھ گنہٕ، کینہہ شیٹھ، کُنہِ ترہ تہٕ کُنہِ ترٕہ دِوان چُھ۔ \n24.\\tبیاکھ تمثیل یُس تِمن برونہہ کُن پیش کٔرِتھ وونُن، اسمانٕچ بادشٲہی چھے تِتھِس شخصس سٍتۍ تشبیہ دِنہٕ آمٕژ یٔمۍ پننِس کھہس مَنٛز اصل بیول ووومُت: \n25.\\tمگر ییلہ انسان شوٚنگتھ اوس، تٔمۍ سُند دُشمن آو تہٕ ووت کٕنکس منز تار تہٕ ووت پننہِ وتہِ۔ \n26.\\tمگر ییلہ تلوار وُپھ دِتھ پھل دِنہٕ آو، تیلہِ گٔیہِ تار تہِ نمودار۔ \n27.\\tتہٕ گرٕ دار سٕندِ نوکر آیہِ أمِس وونُن، جناب، ژے اوسُکھ نہٕ پننِس کھہَس مَنٛز اصل بیٲلۍ ووومُت؟ تیلہِ کتہِ چھُ یہِ دِنہٕ آمُت؟ \n28.\\tتٔمۍ ووٚن تِمَن دُشمن یہِ کٔرِتھ۔ نوکرَو ووٚن أمِس زِ کیا أسۍ گژھِو تِم جمع کٔرِتھ؟ \n29.\\tمگر تٔمۍ ووٚن، نہ۔ یێلہِ تہٕ یێلہِ تہٕ تُہۍ کٔرِو تِمن سٍتـ̡ کٕنُک موٗل تہِ۔ \n30.\\tفصلس تام گژھن دۅشوے اکوٹہ وۅپدُن، تہٕ فصلہٕ وِزِ بہٕ وَنُن زِ گۅڈٕ کٔرِو گٔنڈِتھ تہٕ گٔنڈِتھ زالنہٕ خٲطرٕ، مگر کٕنُک جمع کٔرِو میٲنِس کوٹھس منز۔ \n31.\\tبیاکھ تمثیل دِژ تِمن برونہہ کُن ونُن، اسمانٕچ بادشٲہی چھے سرسٕہ کِس دانہٕ ہٕندۍ پٲٹھۍ، یُس انسان نِش نِتھ پننِس کھہس مَنٛز ووومُت چھُ: \n32.\\tیُس پٔزۍ پٲٹھۍ سارِوٕے بیٲلۍ منزٕ سارِوٕے کھۄتہٕ کم چُھ، مگر ییلہ یہِ وۄپداونہٕ یِوان چھُ، سُہ چُھ جڑی بوٹین مَنٛز سارِوٕے کھۄتہٕ بوٚڈ آسان، تہٕ کُل بنان چھُ، یُتھ ہوہٕکۍ جاناوار یِوان تہٕ اَمہ کِس لنجہِ منز روزان چھِ۔ \n33.\\tبیاکھ تمثیل وۆن تِمن سٍتـ̡ ۔ اسمانٕچ بادشٲہی چھے خمیرٕکۍ پٲٹھۍ، یُس زنانہٕ نِتھ ترٚین پیمانن مَنٛز ژوٗرِ تھووُن، یوٚت تام سورُے خمیر گٔیہِ۔ {پیمائش: یونانۍ زبانہِ منز چُھ لفظ اکھ پیمانہٕ یتھ منز تقریباً ڈۅڈ چُھس آسان، یُس اکھ پِنٹ کھۅتہٕ زیادٕ چُھہ یژھان}\n34.\\tیِمو سارِوٕے کتھٕ کٔر عیسیٰ علیہ السلام تمثیلن مَنٛز وَننہٕ۔ تہٕ تمثیلہٕ ورٲے اوس نہٕ تِمن سٍتـ̡ کتھ کٔرمٕژ: \n35.\\tیُس رسول اللہ صلی اللہ علیہ وآلہ وسلم سُند وننہ آمُت اوس، بہٕ کٔرٕ تمثیلن منز پنُن بوش کھولنہٕ۔ بہٕ کٔرٕ تِم چیز یِم دنیاہٕچ بنیادٕ نِش پوشیدٕ تھاونہٕ آمٕتۍ چھِ۔ \n36.\\tتێلہِ سوٗزۍ عیسیٰ علیہ السلام ہُند ہجوم، تہٕ ژاو گرس منز، تہٕ تٔمۍ سٕندِ شٲگِرِ آیہِ أمِس نِش تہٕ وونُن زِ اسہِ کٔرِو میدانٕچ تمثیل بیان کرنہٕ۔ \n37.\\tتٔمۍ دیُت جواب تہٕ تِمن وونُن یُس اصل بیول ووپناوان چُھ، سُہ چُھ انسان سُند نیٚچُو۔ \n38. کھیت چُھ دنیا؛ اصل بیٛول چِھ بادشٲہی ہٕندِ شُرۍ۔ مگر تارس چِھ بدکار سٕندِ شُرۍ۔ \n39. یُس دُشمن یُس تِمن ووومُت چُھ، سُہ چُھ شیطان۔ فصلہٕ چُھ دنیاہُک خاتمہٕ۔ تہٕ فصلہٕ کَرن وٲلہِ چھِ فرشتہٕ۔ \n40. یِتھٕ کٔنۍ چھِ تارٕ جمع کرنہٕ یِوان تہٕ نارس مَنٛز زالنہٕ یِوان۔ یِتھے پٲٹھۍ گژھہِ یِتھ دُنیا کِس ٲخرس پیٹھ۔ \n41.\\tانسان سُند فرزند سوزِ پَنٕنـ̡ فرشتہٕ، تہٕ تِم کرِ تٔمۍ سٕنزِ بادشٲہی منزٕ سارِنٕے چیٖز جمع یِم بد کار کران چھِ۔ {چیز...: یا، سکینڈل}\n42.\\tتہٕ تراوُن نارٕ کِس بھٹس مَنٛز۔ \n43. تیلہِ گژھہِ نیکوکار پننِس مٲلہِ سٕنزِ بادشٲہی منز آفتابٕکۍ پٲٹھۍ۔ یُس بوزنہٕ خٲطرٕ کُن آسہِ، سُہ بوزُن۔ \n44.\\tبییہِ چُھہ آسمانٕچ بادشٲہی ہِش یُس کھہَس مَنٛز ژوٗرِ روزِتھ چھُ۔ یُس انسان لبان چُھ، سُہ چُھ ژوٗرِ روزان، تہٕ اَمہ سٍتـ̡ چُھ سُہ کھیت مٔلِتھ تہٕ کٕنُن تہٕ سُہ کھیت ہیوٚن۔ \n45.\\tبییہِ چُھہ اسمانٕچ بادشٲہی أکِس سوداگر سٕندِس پٲٹھۍ، یُس اصل موتی ژھاران چُھ: \n46.\\tییمہِ سٍتـ̡ ییلہ أمِس اکھ سٮ۪ٹھاہ موتی لوٚب، سُہ گۆو تہٕ کُنُن سُہ سورُے یُس أمِس نِش اوس، تہٕ ہیوٚتُن سُہ ۔ \n47. بییہِ چُھہ آسمانٕچ بادشٲہی أکِس جالس ہیوٗ یُس سمندرس مَنٛز تراونہٕ آمُت اوس، تہٕ پرٮ۪تھ قٕسمُک جمع کرنہٕ آمُت چھُ: \n48.\\tیُس بٔرِتھ بٔرِتھ بٔٹھِس کُن لٔگِتھ بِہتھ تہٕ رٔٹِتھ گٔیہِ۔ \n49.\\tیِتھے پٲٹھـ̡ گژھہِ دنیاہٕ کِس اندس پیٹھ: فرشتہٕ یِن نیرِتھ تہٕ بدکارن نِش ژٹِتھ ژٔٹِتھ \n50.\\tتہٕ تراوُن نارٕ کِس بھٹس مَنٛز: اَتہِ گژھہِ وُپھ تہٕ دندٕ گٔژِھتھ دِنہٕ۔ \n51.\\tعیسیٰ مسیح چُھ تِمن ونان زِ کیا تۅہہ چُھہ یِم سارِنٕے کتھٕ سمجِمٕتۍ؟ تِم چھِ أمِس ونان آ، خداوند۔ \n52.\\tتێلہِ ووٚن تِمن تێلہِ چُھہ پرٮ۪تھ کانہہ کاتب یُس اسمانٕچ بادشٲہی ہُند حکم دِنہٕ آمُت چُھ، سُہ چُھ أکِس اِنسان سٕندِس پٲٹھۍ، یُس پنہٕ نِس خزانہٕ منزٕ نوو تہٕ پرانہِ چیز نیران چُھ۔ \n53.\\tتہٕ سپُد سپُد، {یہ} ییلہ حضرت عیسیٰ علیہ السلام یِم تمثیلہٕ مُکمل کٔرۍ، سُہ گۆو تتہِ نِش روانہٕ۔ \n54.\\tتہٕ ییلہ سُہ پننِس ملکس مَنٛز آو، تٔمۍ ہیچھناوُن تِمن ہٕنزِ عبادت خانس مَنٛز، یوت تام تِم حٲران گٔیہِ، تہٕ وونُن، یہِ {انسان} کتہِ چُھہ یہِ حکمت، تہٕ {یِم} زبردست کامہِ؟ \n55. کیا یہِ چھان سُند نیچو چُھنہٕ؟ کیا تٔمۍ سٕنزِ موج چھے نہٕ مریم ونان ؟ تہٕ تٔمۍ سٕندِ بٲے یعقوب تہٕ یوسس تہٕ شمعون تہٕ یہوداہ؟ \n56.\\tتہٕ تٔمۍ سٕنزِ بینہِ، کیا تِم چھَنہٕ سٲری اسہِ سٍتۍ؟ تیلہِ کتہِ چھِ یہِ {انسان} یِم سارِنٕے چیٖز؟ \n57.\\tتہٕ تِم گٔیہِ أمِس مَنٛز ناراض۔ مگر حضرت عیسیٰ علیہ السلام ووٚن تِمن زِ رسول چُھہ نہٕ بے عزت، مگر پننِس ملکس مَنٛز تہٕ پننِس گرس مَنٛز۔ \n58.\\tتہٕ تِمو کٔر نہٕ تِمن ہٕندِ کُفر کِنۍ اَتہِ واریاہ طاقتور کٲم۔","1.\\tتمہِ وِزِ بوز ہیرودیس عیسیٰ سٕنزِ شہرت، {ٹیٹرارک: یا، ژورن صوبن پیٹھ گورنر}\n2.\\tتہٕ وونُن پننین خدمتگارن زِ یہِ چُھ یوحنا بپتسمہ دِنہٕ آمُت۔ سُہ چُھ مُردٕ منزٕ زندٕ سپدان۔ تہٕ امہِ مۅکھٕ چُھہ عظیم اعمال أمِس مَنٛز ظٲہر سپدان۔ {کرُن...: یا، چُھ أمِس سٍتـ̡ انجام دِنہٕ آمُت}\n3. تکیازِ ہیرودیس اوس یوحنا ہس تھپھ کٔرِتھ، تہٕ بٔنِتھ تھووُن ہیرودیاس سٕندِ خٲطرٕ قٲد خانس منز، یُس تٔمۍ سٕندِس بٲے فلپس سٕنزِ زنانہِ ٲس۔ \n4.\\tتکیازِ یوحنا ووٚن أمِس زِ یہِ تھاوُن چُھہ نہٕ تۅہہِ خٲطرٕ جٲیز۔ \n5.\\tتہٕ ییلہ سُہ أمِس مارُن آسہِ، سُہ اوس ہجومَس کھوژان، تِکیازِ تِم ٲسۍ أمِس پیغمبر مانان۔ \n6.\\tمگر ییلہ ہیرودیس زاہ دوہ مناونہٕ آو، ہیرودیاس سٕنز کورِ کٔر تِمن برونہہ کنہِ نژان، تہٕ ہیرودیس کٔرٕن خۄش۔ {امہ برونہہ...: Gr. منز}\n7. تمہ پتہ کوٚر تٔمۍ وعدٕ زِ سُہ یُس تہِ منگہِ دِیہ۔ \n8.\\tتہٕ سۅ ووٚن پننہِ ماجہ ہٕندِس ہدایتس برونہہ کُن زِ مے دِیُن جان بپتسمہ دِنہٕ وول کلہٕ۔ \n9.\\tتہٕ بادشاہس اوس افسوس تہٕ بہر حال قسمہٕ خٲطرٕ، تہٕ یِم أمِس سٍتۍ مازس پیٹھ بِہتھ ٲسۍ، تٔمۍ دِیُت حُکُم۔ \n10. تہٕ تٔمۍ سوٗز، تہٕ کوٚرُن جیلس منٛز یوحنا سُنٛد کلہٕ ژٹنہٕ۔ \n11.\\tتہٕ تٔمۍ سُند کلہٕ آو أکِس چارجَرس منز اننہٕ، تہٕ کورِ دِنہٕ آمُت، تہٕ سۅ أنِتھ ماجہ نِش۔ \n12.\\tتہٕ تٔمۍ سٕندِ شٲگِرِ آیہ، تہٕ تُل لاش تُلِتھ تہٕ دفن کٔرِتھ گٔیہِ عیسیٰ ہس وَنُن۔ \n13.\\tیێلہِ حضرت عیسیٰ علیہ السلام یہِ بوز، سُہ دراو جہازٕ سٍتـ̡ أکِس صحرائی مقامس کُن، تہٕ ییلہ لوکو بوز، تِمو دراو شہرو منزٕ پیدل أمِس پٲٹھۍ۔ \n14.\\tتہٕ حضرت عیسیٰ درٛاو تہٕ وُچھُن واریاہ بٔڈِس لُکھ تہٕ تِمن سٍتـ̡ رحم کٔرِتھ تہٕ تِمن ہٕندِس بیمارس شفا دِنہٕ۔ \n15.\\tتہٕ ییلہ شامس آو تٔمۍ سٕندِ شٲگِر أمِس نِش وَنُن، یہِ چھُ ریگستانٕچ جاے تہٕ وُنۍ گۆو وُنُن۔ بٔڈِس سٍتـ̡ ژٔلِتھ یُتھ تِم گامن مَنٛز گٔژِھتھ تہٕ پانَس مٔلِتھ مٔلِتھ۔ \n16. مگر حضرت عیسیٰ علیہ السلام ووٚن تِمن زِ تِمن گژھہِ نہٕ نیرُن۔ تِمن دِیُن کھٮ۪نہٕ خٲطرٕ۔ \n17.\\tتہٕ تِم چھِ أمِس ونان زِ اسہِ چھِ یَتہِ صرف پانژھ روٹی تہٕ زٕ گاڈ۔ \n18.\\tتٔمۍ ووٚن، تِم أنِو میہ نِش۔ \n19. تہٕ تٔمۍ دِیُت بٔڈِس گاسہِ پیٹھ بِہنُک حُکُم، تہٕ پانژھ روٹۍ تہٕ زٕ گاڈٕ رٔٹِتھ تہٕ آسمانس کُن نظر دِتھ دِژُن دُعا تہٕ دِژُن پنہٕ نِس مریدن تہٕ شٲگِرِن ہٕندِس شٲگِرِس دِژٕنۍ۔ \n20.\\tتہٕ تِمو کٔر سارِوٕے کھٮ۪نہٕ تہٕ بٔرِتھ تہٕ تِمو تُل تِم ٹُکرٕ یِم باہ ٹوٗکرِ بٔرِتھ ٲسۍ۔ \n21.\\tتہٕ یِم کھٮ۪وان ٲسۍ، زنانہٕ تہٕ شُرِ علاوٕ ٲسۍ تقریباً پانژھ ساس مرد۔ \n22. تہٕ یێلہِ دِژ عیسیٰ علیہ السلام پننین شاگردن أکِس جہازس منز کھسنہٕ خٲطرٕ، تہٕ أمِس برونہہ کُن دوٚیمہِ طرفہٕ گژھنٕچ مجبور، ییلہ زن تٔمۍ ہجوم سوٗزِ۔ \n23. تہٕ ییلہ تٔمۍ ہجوم ژوٗر کٔرۍ، سُہ ووت أکِس پہاڑس پیٹھ عبادت کرنہٕ خٲطرٕ، تہٕ ییلہ شام آو سُہ اوس تتہِ کُنی۔ \n24.\\tمگر جہازٕ اوس وۅنۍ سمندرس منز، لہرن سٍتـ̡ لٔگِتھ لٔگِتھ: تکیازِ واو اوس برعکس۔ \n25.\\tتہٕ ژوٗرمہِ رٲژ منز گۆو عیسیٰ مسیح سمندرس پیٹھ پکان تمن نِش۔ \n26.\\tتہٕ ییلہ شٲگِرو أمِس سمندرس پیٹھ پکان وُچھ، تِمو گٔیہِ پریشان تہٕ وونُن زِ یہِ چُھ اکھ روح۔ تہٕ تِمو کٔر خوفہٕ سٍتـ̡ کرٛٮ۪کھ۔ \n27. مگر سیدِ سیود حضرت عیسیٰ علیہ السلام تِمن سٍتـ̡ کتھ کٔرِتھ وونُن، رژھ۔ یہ چُھس بہٕ چُھس؛ خوفہٕ گژھ نہٕ۔ \n28. تہٕ پطرس دیُت أمِس جواب تہٕ وونُن، خداوند، اگر ژے آسہٕ تیلہِ کٔرِو مے آبس پیٹھ یِنُک حُکم۔ \n29. تہٕ تٔمۍ ووٚن، یِہ آو۔ تہٕ ییلہ پطرس جہازٕ منزٕ بۄن آو تہٕ سُہ پوٚک آبس پیٹھ، عیسیٰ ہس نِش گژھنہٕ خٲطرٕ۔ \n30.\\tمگر ییلہ تس واو وُچھ، سہ گوٚو کھوژُن۔ تہٕ ڈوبُن ہیوٚت، تٔمۍ ووٚن وۆن، خداوند، مے بچاو۔ {زوردار: یا، زور}\n31.\\tتہٕ یکدم کٔر حضرت عیسیٰ علیہ السلام پَنُن اَتھٕ تہٕ رٔٹِتھ رٔٹِتھ وونُن، اے کم ایمانہٕ، ژے کیازِ گوو شک کٔرِتھ؟ \n32.\\tتہٕ ییلہ تِم جہازس منز آیہ، واو گٔیہِ بند۔ \n33.\\tیِم جہازس منز ٲسۍ، تِمو آیہِ أمِس پوٗزا کٔرِتھ یہِ ونان زِ پٔزۍ پٲٹھـ̡ چُھہ تُہۍ خدا سُند نیٚچُو۔ \n34.\\tتہٕ ییلہ تِم گٔیہِ، تِم آیہ جینیسارٹ کِس سرزمینس منز۔ \n35.\\tتہٕ یێلہِ تَمہِ جایہِ ہٕندِس نفرن أمِس مُتعلِق پتاہ لٔگِتھ، تِمو سوٗزۍ أندۍ پٔکھۍ سارِنٕے مُلکس مَنٛز، تہٕ أنِکھ سارِنٕے بیمار أمِس نِش۔ \n36.\\tتہٕ کٔرٕن أمِس التجا زِ تِم گژھن صرف تٔمۍ سٕندِس پلوَس ہٕندِس دامن اَتھٕ لاگُن، تہٕ یِمن ہُند اَتھٕ لوٚگُن تِم گٔیہِ پوٗرٕ پٲٹھۍ۔","1. پَتہٕ آو عیسیٰ مسیح کاتب تہٕ فریسی، یِم یروشلمٕکۍ ٲسۍ، وونُن، \n2.\\tتہندِ شٲگِر کیازِ چھِ بزرگن ہٕندِس روایتس خلاف ورزی کران؟ تِکیازِ تِم چھِنہٕ روٹی کھٮ۪نہٕ وِزِ اتھہٕ چھلان۔ \n3.\\tمگر تٔمۍ دیُت جواب تہٕ تِمن وونُن، تہٕ کیازِ چھِو تہِ پننہِ روایت سٍتـ̡ خدایہ سٕندِس حکمس خلاف ورزی کران؟ \n4. کیازِ خداین دیت حکم زِ پننس مٲلس تہٕ ماجہ ہُند احترام کرُن: تہٕ یُس مٲلس یا ماجہ بد دعا کرِ، سُہ گژھہِ مرُن۔ \n5.\\tمگر تُہۍ چھِو ونان، یُس تہِ پننِس مٲلِس یا ماجہِ ہُند وَنُن چُھ، سُہ چُھ اکھ تحفہٕ، یُس تہٕ ژے میانہِ نِش فٲیدٕ حٲصل کرِ۔ \n6. تہٕ پننِس مٲلِس تہٕ ماجہِ ہٕنز عزت کرٕن، {سُہ گژھہِ آزاد}۔ یِتھٕ پٲٹھۍ چُھہ تۅہہ خدایہ سُند حکم پننہِ روایتہٕ سٍتـ̡ کانہہ اثر پیوان۔ \n7.\\tاے منافقو، اَسعیاہن کٔر تۅہہِ ہٕنز پیشن گویی کٔرِتھ وَنُن، \n8.\\tیِم لُکھ چھُ میہ نِش پنہٕ نِس ٲسِس سٍتـ̡ نزدیک، تہٕ چُھس چپنہٕ سٍتـ̡ عزت دِوان۔ مگر تِہُند دِل چُھہ میہ نِش دور۔ \n9. مگر بیکار چِھ تِم میانہِ عبادت کران، تہٕ انسانن ہٕندِس حکمس سٍتـ̡ ہیچھناوان چِھ۔ \n10. تہٕ تٔمۍ بُلوو ہجوم، تہٕ وونُن تِمَن، بوٗزِو تہٕ سمجُن: \n11.\\tیُس ٲسِس مَنٛز نیران چُھ، سُہ چُھ انسان ناپاک کران۔ یُس ٲسِس منزٕ نیران چُھ، سُہ چُھ انسانس ناپاک کران۔ \n12.\\tاَمہِ پتہٕ آو تٔمۍ سٕندِ شٲگِرِد تہٕ ووٚنُن تٔمِس زِ یہِ کتھ بوزنہٕ پتہٕ گٔیہِ فریسی ناراض؟ \n13. مگر تٔمۍ دیُت جواب تہٕ وونُن، پرٮ۪تھ کُل یُس میانہِ آسمانی مٲلہِ نہٕ ووتمُت چُھ، یُس نہٕ میانہِ آسمانی مٲلہِ ووتمُت چُھ، یُس یِن موٗل کڈنہٕ یُن۔ \n14.\\tتِم تراوُن یِم اَنٮ۪ن ہٕندِس رہنُما۔ تہٕ اگر انہِ گٔیہِ انہِ ہٕندِس رہنُمٲیی کٔرِتھ، دۅشوے گژھن کھۄلہِ مَنٛز۔ \n15.\\tپطرس دیُت جواب تہٕ وونُن أمِس زِ اسہِ کٔرِو یہِ تمثیلُک اعلان ۔ \n16.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن، کیا تُہۍ تہِ چھوا وُنہِ تہِ سمجھ نہٕ؟ \n17.\\tکیا تۅہہ چُھہ نہٕ وُنہِ تہِ سمجھان زِ یُس تہِ ٲسس منز اژان چُھہ سُہ چُھ یٔڈ مَنٛز گژان تہٕ یُس تہٕ چُھہ یٔڈِس مَنٛز دِنہٕ یِوان۔ \n18.\\tمگر یِم چیز ٲسِس منزٕ نیران چھِ تِم چھِ دِلہٕ منزٕ نیران۔ تہٕ تِم چھِ انسانس ناپاک کران۔ \n19. تکیازِ دِلہٕ منزٕ چھِ بد خیالات، قتل، زنا، زناکاری، ژوٗرِ، اپُز گواہ، توہین مذہب نیران۔ \n20.\\tیِم چیز چھِ انسان نِش ناپاک کران مگر چھلنہٕ آمٕتۍ اتھو سٍتۍ کھٮ۪نہٕ سٍتۍ چھُنہٕ انسان ناپاک سپدان۔ \n21. پَتہٕ گۆو عیسیٰ اَتہِ پٲٹھۍ، تہٕ دراو صور تہٕ صیدون کِس ساحلس کُن۔ \n22.\\tتہٕ وُچھ کنعانٕچ اَکھ زنانہٕ یِمو بٔٹھہِ پیٹھٕ دراو تہٕ وَنُن أمِس کُن وَنُن زِ اے خدایہ، داؤد سُند نیچو، میہ پیٹھ رحم کر۔ میانہِ کورِ چھے شیطانس سٍتـ̡ سٮ۪ٹھاہ پریشان۔ \n23.\\tمگر تٔمۍ دِژ نہٕ أمِس کُنہِ تہِ لفظُک جواب۔ تہٕ تٔمۍ سٕندِ شٲگِرِ آیہِ أمِس تہٕ وَنُن أمِس کُنہِ تہِ کُنہِ لفظس سٍتـ̡ دِنہٕ۔ تِکیازِ سُہ چُھ اسہِ پَتہٕ وَنان۔ \n24.\\tمگر تٔمۍ دیُت جواب تہٕ وونُن، بہٕ چُھس نہٕ سوزنہٕ آمُت بلکہ چُھس اسرٲیلِس گرٕ کِس رٲوِمٕتِس کُن سوزنہٕ آمُت۔ \n25.\\tپتہٕ آیہِ سُہ تہٕ کٔرٕن أمِس پوٗزا کٔرِتھ وونُن، خداوند، میانہِ مدد۔ \n26.\\tمگر تٔمۍ دیُت جواب تہٕ وونُن، شُرین ہُند روٹی نِنۍ تہٕ ہونین پیٹھ تراوُن چُھہ نہٕ مُقابلہٕ۔ \n27. تہٕ تٔمۍ ووٚن، پزر اے خدا، توتہِ چھِ ہونۍ تِمن ٹُکرٕ کھیوان یُس پننِس مٲلکَن ہٕندِس دسترٕ پیٹھٕ وسان۔ \n28.\\tاَمہِ پَتہٕ دِژ عیسیٰ مسیحن جواب تہٕ وونُن أمِس زِ اے زنانہٕ، تُہند ایمان چُھہ بٔڈ تہٕ یێلہِ تہٕ ژے یژھہٕ یژھہٕ تہِ آسُن۔ تہٕ تٔمۍ سٕنزِ کورِ گٔیہِ تمہِ ساعتہ سٍتـ̡ پوٗرٕ کرنہٕ۔ \n29. تہٕ عیسیٰ ووت تتہِ پیٹھہ نیرِتھ گلیل کِس سمندرس نزدیک۔ تہٕ ووت أکِس پہاڑس پیٹھ، تہٕ بیوٹھ تتہِ۔ \n30. تہٕ بٔڈۍ لٔگۍ أمِس نِش، یِمن سٍتـ̡ یِم لٔنگۍ، انہِ، گونگ، معذوٗر تہٕ باقٕے واریاہ ٲسۍ، تہٕ یِم دِژٕکھ عیسیٰ سٕندِس قدمن پیٹھ۔ تہٕ تٔمۍ دِژ تِم شفا: \n31.\\tیوت تام زِ یێلہِ تِمو کُنہِ تہٕ انہِ وُچھِتھ گٔیہِ حٲران تہٕ تِمو کٔر اسرٲیلِکِس خدایہِ سٕندِس حمد سٍتـ̡ ۔ \n32.\\tاَمہِ پَتہٕ بُلوو عیسیٰ علیہ السلام پَنٕنـ̡ پَنٕنـ̡ شٲگِرِـ̡ تہٕ وونُن، بہٕ چُھس نہٕ تِمن ہٕندِس بٔرِس سٍتـ̡ رحمت، تِکیازِ تِم چِھہ وُنہِ تریہ دۅہہٕ میہ سٍتـ̡ روزان تہٕ چُھس نہٕ تِمن ہٕندِس وتہِ منز بیہوش گژھن۔ \n33.\\tتہٕ تٔمۍ سٕندِ شٲگِر چھِ أمِس ونان زِ بیابانن مَنٛز کتہِ گژھہِ اسہِ یوتاہ روٹی یُتھ بٔڈِس بٔرِتھ بٔرِتھ؟ \n34.\\tتہٕ عیسیٰ علیہ السلام چُھ تِمن وَنُن زِ ژےٚ کٲژاہ روٹی چھِ؟ تہٕ تِمو ووٚن، ستھ تہٕ کینہہ لۄکٕٹۍ گاڈ۔ \n35. تہٕ تٔمۍ دِیُت ہجومس زمینس پیٹھ بِہنُک حُکُم۔ \n36.\\tتہٕ تٔمۍ رٔٹِتھ سَتھ روٹی تہٕ گاڈٕ رٔٹِتھ شُکریہ ادا کٔرِتھ تہٕ دِتُن پننین شاگردن تہٕ شاگردن ہٕندِس بٔڈس دِنہٕ۔ \n37.\\tتہٕ تِمو کٔر سارِوٕے کھٮ۪وان تہٕ بٔرِتھ گٔیہِ، تہٕ تِمو تُل پھُٹمُت {ماز} یُس سَتھ ٹوٗکرِ بٔرِتھ اوس۔ \n38.\\tتہٕ یِم کھٮ۪وان ٲسۍ، تِم ٲسۍ ژور ساس مرد، زنانہٕ تہٕ شُرۍ۔ \n39.\\tتہٕ تٔمۍ سوٗزۍ ہجوم تہٕ جہازٕ رٔٹِتھ آو مگدلہ کِس ساحلس پیٹھ۔","1. فریسی تہِ آیہ صدوقین سٍتۍ، تہٕ لالچ دِژ أمِس یژھ زِ سُہ ہاوِ تِمن آسمانہٕ پیٹھٕ اکھ نشانہٕ۔ \n2.\\tتٔمۍ دِژ جواب تہٕ وونُن تِمن ییلہ شام آسہِ، تۅہہ چھِو ونان زِ یہ آسہِ خوبصورت موسم، تکیازِ آسمان چھہ وۄزل۔ \n3.\\tتہِ صبحس آسہِ از کل بدحال موسم آسُن، تکیازِ آسمان چھہ وۄزل تہ پوٚت آسان۔ اے منافقو، تم ہیکو آسمانک بُتھ وچھتھ ہیکو۔ مگر کیا تۅہہ ہیکو نہٕ زمانٕچ نشانی وچھتھ؟ \n4.\\tبدکار تہٕ بدکار نسل چھہ کُنہِ نشانہٕ ژھاران۔ تہٕ اتھ گژھہِ نہ کانہہ نشانی دِنہٕ، مگر پیغمبر یونس سُند نشانہٕ۔ تہٕ سُہ تروو تِم تہٕ درٛاو۔ \n5.\\tتہٕ ییلہ تٔمۍ سٕندِ شٲگِر دوٚیمہِ طرفہٕ آیہ، تِمو ٲس روٹی کھیوٚن مٔشِد گٔمٕژ۔ \n6. اَمہِ پَتہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمَن زِ فریسیَن تہٕ صدوقین ہٕندِس خمیرس نِش گژھِو ہوشیار تہٕ ہوشیار روزُن۔ \n7.\\tتہٕ تِمو کٔر پانہٕ أکِس سٍتـ̡ استدلال کٔرِتھ، {یہِ} کیازِ أسـ̡ چُھہ نہٕ کانہہ روٹی ہیوٚتمُت۔ \n8.\\tیێلہِ عیسیٰ علیہ السلام وُچھ تِمن وۆنُن، اے کم ایمانہٕ، کیازِ چُھہ پانس پانس سٍتـ̡ دلیل دِوان، کیازِ چُھہ نہٕ کانہہ روٹی أنِمٕژ۔ \n9.\\tژیہ چھُنہٕ وُنہِ تہِ سمجُن، پانژن ساسن ہٕندِ پانژھ روٹۍ تہٕ کٲژاہ ٹوٗکرِ تُلِتھ تُلِتھ؟ \n10.\\tژۅن ساسن منز ستھ روٹۍ، تہٕ ژیہ کٲژاہ ٹوٗکرِ تُلۍ؟ \n11.\\tژیہ کِتھہ پاٹھۍ چُھہ نہٕ یہ سمجھان زِ میہ چُھہ نہٕ ژے سٍتـ̡ روٹی مُتلق کتھ کٔرمٕژ، یُتھ تہٕ فریسین تہٕ صدوقین ہٕندِس خمیرس نِش ہوشیار روزُن؟ \n12.\\tتێلہِ گٔیہِ تِمن سمجُن زِ تٔمِس دِژ نہٕ روٹی ہٕندِس خمیرس نِش بلکہ فریسین تہٕ صدوقین ہٕندِس نظریہٕ نِش ہوشیار روزنُک حُکم۔ \n13.\\tیێلہِ عیسیٰ مسیح قیصریہ فِلپی کِس بٔٹھِس مَنٛز ووت، تٔمۍ پرژھ پننین شاگردن زِ انسان کُس چُھہ ونان زِ بہٕ چُھس انسان سُند نیٚچُو؟ \n14. تہٕ تِمو ووٚن، کینہہ {ونان زِ تہٕ چُھہ} یوحنا بپتسمہ دِنہٕ آمُت: کینہہ الیاس۔ تہٕ باقٕے چھِ یرمیا یا پیغمبرن مَنٛز اکھ۔ \n15.\\tسُہ چُھہ تِمن ونان مگر تُہۍ کُس چُھس ونان زِ بہٕ چُھس؟ \n16. تہٕ شمعون پطرس دیُت جواب تہٕ وونُن، تہٕ چُھہ مسیح یُس زندٕ خدا سُند نیٚچُو۔ \n17.\\tتہٕ حضرت عیسیٰ علیہ السلامن دیُت جواب تہٕ وونُن تٔمِس مُبارکت، شمعون برجونا، تکیازِ ماز تہٕ خونن چُھ نہٕ ژے سٍتـ̡ ظٲہر کورمُت، بلکہ چُھہ میون باپ یُس آسمانس مَنٛز چُھ۔ \n18. تہٕ بہٕ چُھس ژے یہ تہِ ونان زِ ژٕ چُھہ پطرس تہٕ اتھ پتھرس پیٹھ بناوٕ بہٕ پنُن کلیسا۔ تہٕ جہنمٕکۍ دروازٕ گژھن نہٕ اتھ خلاف غٲلب۔ {پطرس: یہِ ناو چُھ أکِس کٔنہِ کٔنہِ ہُند اشارٕ}\n19. تہٕ بہٕ دِیہ ژے آسمانٕچ بادشٲہی ہٕنز کُنز، تہٕ یُس تہٕ ژے زمینس پیٹھ یُس تہٕ یُس تہٕ ژے زمینس پیٹھ تراوُن سُہ گژھہِ آسمانس مَنٛز یلہٕ تراونہٕ۔ \n20. تمہِ پتہ دِژ تٔمۍ پننین شاگردن حکم زِ تِم گژھن کٲنسہ تہِ شخصس ونُن زِ سُہ چُھ عیسیٰ مسیح۔ \n21. اَمہِ وقتہٕ پیٹھٕ دِژ حضرت عیسیٰ علیہ السلام پننین شاگردن ہاونہٕ زِ سُہ گژھہِ یروشلمس مَنٛز گژھُن، تہٕ بزرگن تہٕ بٔڈۍ پادٕرین تہٕ کاتبن ہٕنزِ واریاہ چیزن ہُند مصیبت گژھُن، تہٕ مارنہٕ یُن، تہٕ تریمہِ دۅہہ گژھہِ دُبارٕ زندٕ کرنہٕ۔ \n22.\\tپطرس نِش رٔٹِتھ ہیوٚتُن أمِس ملامت کرُن، خداوند، یہِ گژھہِ نہٕ ژے سٍتـ̡ دوٗر آسُن۔ {بٔنِو...: Gr. پانس پیٹھ رحم کرُن}\n23.\\tمگر سُہ پھیُر تہٕ پطرس ووٚنُن، شیطان، تہٕ ژٕ چُھکھ میانہِ خٲطرٕ جرم ، تکیازِ ژے چُھہ نہٕ خدایہِ سٕندِ چیزن ہُند مزٕ تھاوان بلکہ چُھہ تِمن چیزن ہُند مزٕ یِوان دِنہٕ۔ \n24. تێمہِ وۆن حضرت عیسیٰ علیہ السلام پننین شاگردن سٍتـ̡ یێلہِ کانہہ {انسان} میانہِ پتہٕ یِیہ، سُہ گژھہِ پانس نِش انکار کرُن، تہٕ تُلِن پنُن صلیب تہٕ میانہِ پتہٕ۔ \n25.\\tیُس تہِ پَنُن زُو بچاوِ، سُہ گژھہِ سُہ راوُن، تہٕ یُس میانہِ خٲطرٕ پنُن زُو راوِ، سُہ میلہِ سُہ تہِ۔ \n26.\\tانسانس کیا چُھ فٲیدٕ حٲصل سپدِ، اگر سُہ پورٕ دنیا حٲصل کرِ، تہٕ پنُن روح راوُن؟ یا انسان کیا دِیہِ پننہِ روحہٕ بدلہٕ؟ \n27. تکیازِ انسان سُند فرزند گژھہِ پننِس مٲلہِ سٕندِس جلال سٍتـ̡ پننین فرشتن سٍتـ̡ یِنہٕ۔ تہٕ پَتہٕ دِیہِ سُہ پرٮ۪تھ أکِس انسانس پننہِ کامہِ مُطٲبق انعام۔ \n28.\\tبہٕ چُھس ژے ونان زِ یێتہِ آسہِ کینہہ کھڑا یُس نہٕ موتُک مزہ چکھہِ، یوتام نہٕ تِم انسان سُند نیچو پننِس بادشاہتس منز یِوان وُچھن۔","1. تہٕ شیٚیہِ دۅہہٕ پَتہٕ چُھ عیسیٰ پطرس، یعقوب تہٕ یوحنا پنُن بوے نِتھ أکِس تھدِس بالس مَنٛز انان۔ \n2.\\tتہٕ آو تِمن برونہہ کُن تبدیٖل کرنہٕ: تہٕ تٔمۍ سُند بُتھ اوس آفتابٕکۍ پٲٹھۍ چمکُن، تہٕ تٔمۍ سُند پوشاک اوس گاشہٕ ہیوٗ سفید۔ \n3. تہٕ وُچھ تِمن نِش موسیٰ تہٕ الیاس أمِس سٍتـ̡ کتھ کران ظٲہر۔ \n4.\\tپطرس دیُت جواب تہٕ وونُن عیسیٰ مسیحس خدا، یێلہِ تہِ روزُن چُھہ اسہِ خٲطرٕ اصل۔ اکھ تہٕ اکھ موسیٰ سٕندِ خٲطرٕ، تہٕ اکھ الیاس سٕندِ خٲطرٕ۔ \n5.\\tییلہ سہ وُنہِ تہِ کتھ کران اوس، وُچھ اَکھ چمکدار اوٚبرُن یِمن پیٹھ ژھایہِ، تہٕ وُچھِو اوٚبرٕ منزٕ اکھ آواز، یُس وَننہٕ آمُت چھُ، یہِ چُھہ میون پیاری نیچو، یٔمِس سٍتـ̡ بہٕ خوش چُھس۔ تٔمِس بوزو۔ \n6.\\tتہٕ ییلہ شاگردن بوٗز، تِم پیوٚو بُتھِس پٲٹھۍ، تہٕ گٔیہِ کھوژان۔ \n7. تہٕ حضرت عیسیٰ علیہ السلام آو تہٕ تِمن اتھہٕ لاگُن تہٕ ووٚنُن، وُچھِو تہٕ گژھ نہٕ کھوژُن۔ \n8. تہٕ ییلہ تِمو أچھ تُل، تِمو وُچھ نہٕ کانہہ تہِ انسان، صرف عیسیٰ سٕندِ علاوٕ۔ \n9.\\tتہٕ یێلہِ تِم بالہٕ پیٹھٕ بۄن وٲتِتھ، حضرت عیسیٰ علیہ السلامن دِژ تِمن ہُند حکم دِتھ زِ یێلہِ نہٕ کٲنسہ تہِ انسانس وژن، یوتام نہٕ انسان سُند نیچو مُردٕ منزٕ زندٕ سپدِ۔ \n10.\\tتہٕ تٔمۍ سٕندٮ۪و شاگردو پرژھ أمِس زِ تیلہِ کیازِ چھُ کاتب ونان زِ الیاس گژھہِ گۅڈٕ یُن۔ \n11. تہٕ حضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن تِمن زِ الیاس گژھہِ پٔزۍ پٲٹھۍ گۅڈٕ یِنہٕ تہٕ سارِنٕے چیزن ہُند بحال سپدُن۔ \n12. مگر بہٕ چُھس ژےٚ ونان زِ الیاس چُھ گوڈٕے آمُت، تہٕ تِمو ٲس نہٕ أمِس زانان، مگر یِمو کٔرِکھ أمِس سٍتـ̡ یُس تِمو دِژمُت چُھ۔ یِتھے پٲٹھـ̡ گژھہِ یِمن سٍتـ̡ انسانہٕ سُند فرزند تہِ دِنہٕ۔ \n13.\\tتێلہِ گۆو شاگردن سمجھ زِ تٔمۍ اوس تمن سٍتـ̡ یوحنا بپتسمہ دِنہٕ وٲلِس سٍتـ̡ کتھ کٔرمٕژ۔ \n14.\\tتہٕ ییلہ تِم ہجومس نِش وٲتۍ، أمِس نِش آو اَکھ {یقین} شخص، یُس أمِس نِش کۄٹھہٕ بٔنِتھ وونُن، \n15.\\tخداوند، میانِس نیچوِس سٍتـ̡ رحم کرُن، تکیازِ سُہ چُھ پاگل تہٕ پریشان گومُت، تکیازِ اکثر چُھ سُہ نارس مَنٛز پیوان تہٕ اکثر آبس مَنٛز۔ \n16.\\tتہٕ بہٕ اوٚن سُہ چُھس پننین شاگردن نِش، تہٕ تِمو ہیوٚک نہٕ أمِس شفا دِتھ۔ \n17. یێلہِ دِژ عیسیٰ علیہ السلام جواب تہٕ وونُن، اے کافر تہٕ بدکار نسل، بہٕ کٲتِس کالس روزٕ ژے سٍتـ̡؟ بہٕ کُس کالس روزٕ ژے سٍتـ̡ دِنہٕ؟ سُہ أنِو میہ نِش۔ \n18.\\tتہٕ حضرت عیسیٰ علیہ السلامن دِژ شیطانس ملامت ۔ تہٕ سُہ دراو أمِس نِش تہٕ شُر گۆو تمہِ ساعتہ شفا ۔ \n19.\\tتێلہِ آو حضرت عیسیٰ ہس نِش الگ تہٕ وونُن، أسۍ کیازِ ہیوٚک نہٕ سُہ کٔڑِتھ کٔرِتھ؟ \n20. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمن کُفرٕ کِنۍ، یێلہِ تہٕ یێلہِ کُنہِ تہِ ناممکن آسہِ۔ \n21. یێلہِ تہِ چھُ نہٕ یِتھٕ نِش نیران بلکہِ دُعا تہٕ روزٕ سٍتـ̡ نیران۔ \n22. تہٕ یێلہِ تِم گلیلِس مَنٛز روزان ٲسۍ، حضرت عیسیٰ علیہ السلامن ووٚن تِمن زِ انسان سُند فرزند گژھہِ انسانن ہٕندِس اتھس مَنٛز دھوکہٕ دِنہٕ: \n23.\\tتہٕ تِم مارن أمِس تہٕ تریمہِ دۅہہ یِیہِ سُہ دُبارٕ زندٕ کرنہٕ۔ تہٕ تِم ٲسۍ سٮ۪ٹھاہ معذرت۔ \n24.\\tتہٕ ییلہ تِم کفرناؤم آیہ، یِمو خراج رٔٹِتھ آیہ پطرس نِش، تہٕ وونُن، کیا چُھہ تُہند آقا چُھنہٕ خراج دِوان؟ {خراج دِنہٕ: اصلی چُھہ دِدرخما، قٕمتھ پنٛدہ پینس سٹرلنگ؛ تقریباً ستترہ سینٹ}\n25.\\tسُہ چُھ ونان آ۔ تہٕ ییلہ سُہ گرس منز آو، حضرت عیسیٰ علیہ السلام رُکٲوِتھ رُکٲوِتھ وونُن، ژیہ کیا چُھہ سُہ شمع؟ زمینہِ ہٕندِس بادشاہس کٔمِس سٍتـ̡ چُھہ رسم یا خراج رٹان؟ پننین شُرین سٍتـ̡ یا اَپرن ہٕندِس سٍتـ̡ چُھہ؟ \n26.\\tپطرس چُھ أمِس وَنُن وَنان۔ عیسیٰ مسیح چُھ أمِس ونان زِ تَمہِ پَتہٕ چھِ شُرِ آزاد۔ \n27.\\tامہ باوجود زِ اسہِ گژھ تمن ناراض کرنہٕ، ژیہ گژھ سمندرس کُن، تہٕ اکھ ہُک تراوُن، تہٕ تُلِو گاڈ یُس گۅڈنچہ لٹہِ یِوان آسہِ۔ تہٕ ییلہ ژے تٔمۍ سُند بوش کھولِو، تۅہہ میلہِ پونسہٕ ہُند اکھ ٹُکر: یُس رٔٹِتھ تہٕ تِمن دِیُن میانہِ تہٕ ژے خٲطرٕ۔ {اکھ ٹُکر...: یا، اکھ سٹیٹر: یہ چُھ نصف اونس رۄپہٕ، قٲمتھ زٕ شلنگ تہٕ شےٚ پینس، سٹرلنگ۔ تقریباً پنژاہ سینٹ}","1. اَمی وِزِ آو عیسیٰ مسیحس نِش شٲگِر، وَنُن زِ اسمانٕچ بادشٲہی مَنٛز کُس چُھ سارِوٕے کھۄتہٕ بوڈ ؟ \n2. تہٕ حضرت عیسیٰ علیہ السلام بُلوو أکِس لۄکٹِس شُرس پانس نِش تہٕ تھووُن تِمن مَنٛز \n3. تہٕ ووٚنُن، یێلہِ بہٕ چُھس ژےٚ وَنُن، یوتام نہٕ تۅہہ بدلاونہٕ یِو، تہٕ لۄکٹٮ۪ن شُرین ہٕندۍ پٲٹھۍ، تُہۍ ہیکو نہٕ اسمانٕچ بادشٲہی مَنٛز اژِتھ۔ \n4. یُس تہِ یُس أمِس لۄکٹِس شُرِس سٍتـ̡ عاجز کرِ، سُہ چُھ آسمانہٕ کِس بادشاہتس مَنٛز سارِوٕے کھۄتہٕ بٔڈ آسان۔ \n5.\\tتہٕ یُس میانہِ ناوٕ سٍتـ̡ یُتھ اکھ لۄکُٹ شُر میلہِ سُہ چُھہ میہ وصول کٔرِتھ۔ \n6.\\tمگر یُس یِمو لۅکٹِس مَنٛز أکِس مَنٛز ناراض کرِ، یُس میہ پیٹھ پژھ تھاوان چُھ، تٔمِس خٲطرٕ بہتر اوس زِ تٔمِس گردنہٕ سٍتـ̡ گٔژھ کٔرِتھ تہٕ سُہ آو سمندرٕ کِس سرٛنِس مَنٛز ڈُباونہٕ۔ \n7.\\tدُنیاہس ہٕندِس جُرمَس سٍتـ̡ افسوس! تکیازِ یہ گژھہِ آسن زِ جرم گژھہِ آسن۔ مگر تٔمِس شخصس ہُند افسوس یٔمۍ سُند جرم سپدِ! \n8. لہٰذا اگر تُہند اَتھٕ یا کھۄر ژٔٹِتھ دِنہٕ یِنہٕ بجایہ زٕ اَتھٕ یا زٕ کھۅر دِنہٕ بجایہ چھُ تۅہہِ ہٕندِ خٲطرٕ بہتر زِ زٕ اَتھٕ یا زٕ کھۅر دِنہٕ بجایہ زٕ اَتھٕ یا زٕ کھۅر دِنہٕ یِنہٕ بجایہ۔ \n9.\\tتہٕ اگر تۅہہِ أچھ ژٔٹِتھ کٔرِو پانس نِش۔ \n10. ہوشیار روزُن زِ یِمو منزٕ کُنہِ تہِ کُنہِ تہِ نفرت۔ تکیازِ بہٕ چُھس ژے ونان زِ جنتس مَنٛز چھِ تِہٕندِس فرشتہٕ ہمیشہٕ میٲنِس مٲلہِ سُند بُتھ وُچھان یُس جنتس مَنٛز چُھ۔ \n11. تکیازِ انسان سُند فرزند چُھ یُس رٲومُت اوس سُہ بچاونہٕ خٲطرٕ آمُت۔ \n12.\\tتۅہہ کتھہ پاٹھۍ چھہ سوچان؟ اگر کٲنسہِ انسانس ہتھ کۅکر آسہِ، تہ یمو منزہ اکھ گمراہ آسہِ، سہ چھہ نہ نتھ تہ نو ترٲوتھ پہاڑن منز گژھتھ تہ گمراہ گژھن وٲلس ژھانڈان۔ \n13. تہٕ اگر تس یہ لبان آسہِ، بہٕ چُھس ژے ونان زِ سُہ چُھ نَمتھ تہٕ نَوٕ کھۅتہٕ زیادٕ خۅش سپدان۔ \n14. توتہِ چُھہ نہٕ تُہٕندِس مٲلہِ سٕنز مرضی یُس آسمانس مَنٛز چُھ، یُس یِمو منزٕ اکھ لۅکٹـ̡ مرُن چُھ۔ \n15.\\tتێلہِ اگر تُہند بٲے تۅہہِ خلاف زیادتی کرِ، گژھ تہٕ تس ؤنِو تٔمِس تہٕ تٔمِس درمِیان پنُن غلطی۔ \n16.\\tمگر اگر سُہ نہٕ بوزِ، تیلہِ نِیُن پانس سٍتـ̡ بییہ اکھ یا زٕ ، یُتھ زٕ دۄن یا ترٮ۪ن گواہَن ہٕندِس ٲسِس مَنٛز گژھہِ پرٮ۪تھ کانہہ لفظ قایم سپدِ۔ \n17. تہٕ یێلہِ سُہ یِم بوزنس منز غفلت کرِ، تیلہِ گژھہِ کلیساہٕ سٍتـ̡ وَنُن: مگر یێلہِ سُہ کلیسا بوزنس منز غفلت کرِ، تێلہِ گژھہِ سُہ تہٕ کُنہِ کافر تہٕ پبلکن ہٕندِ پٲٹھۍ۔ \n18. بہٕ چُھس ژےٚ ونان زِ یُس تہٕ ژے زمینس پیٹھ پابند کرِو سُہ گژھہِ آسمانس مَنٛز بند۔ \n19. بییہِ چُھس بہٕ ژے ونان زِ اگر تم منزٕ دۅنوے زمینس پیٹھ متفق گژھن یُس تِم پرژھن تہٕ یُس تِمن ہٕندِ خٲطرٕ یُس اسمانس مَنٛز چُھ۔ \n20. یێتہِ زٕ تریہ میانہِ ناوٕ سٍتـ̡ جمع کرنہٕ آمٕتۍ، تتہِ چُھس بہٕ تِمن مَنٛز آسان۔ \n21.\\tپَتہٕ آو پطرس أمِس نِش، تہٕ وونُن، خداوند، میانہِ بٲے کٲژاہ لٹہِ کرِ میانہِ خلاف گۅناہ تہٕ بہٕ کٔرٕ تس معاف۔ سَتھ لٹہِ تام؟ \n22.\\tعیسیٰ مسیح چُھس ونان زِ بہٕ چُھس نہٕ ژے سَتھ لٹہِ وَنان۔ \n23. تێمہِ کِنۍ چُھ آسمانٕچ بادشٲہی أکِس خاص بادشاہس سٍتـ̡ تشبیہ دِنہٕ آمٕژ، یُس تٔمۍ سٕندِس خادمَن ہُند حساب تھاوِ۔ \n24.\\tتہٕ ییلہ تٔمِس گنزرُن ہیوٚت، اَکھ آو أمِس نِش اننہٕ، یُس أمِس دَہ ساس ٹیلنٹ دِنہٕ آو۔ {ٹیلنٹ: اکھ ٹیلنٹ چُھ ستھ ہتھ پنژاہ اونس رۄپہٕ، یُس پانژھ شِلنگ پتہٕ اونس پاؤنڈ شلنگ چُھ}\n25.\\tمگر یوتاہ أمِس دِیُن نہٕ، تٔمۍ سٕندِس مٲلکَن دِیُت أمِس کٕنُنُک حُکُم، تہٕ أمۍ سٕنزِ خانٛدارِنہِ تہٕ شُرۍ، تہٕ یُس أمِس نِش اوس، تہٕ معاوضہٕ دِیُن دِنہٕ۔ \n26. اَمہِ مۄکھٕ پیوٚو خادم پیوٚو تہٕ کٔرٕن أمِس پوٗزا کٔرِتھ وَنُن، خداوند، میانہِ سٍتـ̡ صبر کرُن، تہٕ بہٕ کٔرٕ ژے سارِنٕے دِنہٕ۔ {أمِس پوٗزا کٔرِتھ: یا کٔرٕن أمِس التجا کٔرِتھ}\n27.\\tتمہ پتہ گۆو تمہِ خادم سُند مالک، رحم کٔرِتھ تہٕ کوٚرُن أمِس قرضہٕ معاف۔ \n28.\\tمگر یۅہے نوکر دراو نیبر، تہ لوٚب تٔمۍ سُند اکھ سٲتھی نوکر، یُس أمس ہتھ پینس واجب اوس، تہٕ تٔمۍ تھووُن أمِس پیٹھ اتھہٕ، تہٕ رٔٹِن نِش تھپھ کٔرِتھ وونُن، مے دِیُن یُس ژے دِیُن۔ {پینس: رومی پونسہٕ چُھ أکِس اونسُک ٲٹھم حصہٕ، یُس پانژو شِلنگ پتہٕ ستھ پینس نصف پونسہٕ آسان چھُ۔ تقریباً ژۄداہ سینٹ}\n29.\\tتہٕ تٔمۍ سُند سٲتھی نوکر پیوٚو أمِس قدمن پیٹھ، تہٕ کوٚرُن أمِس التجا کٔرِتھ زِ میانہِ سٍتـ̡ صبر کرُن، تہٕ بہٕ دِیہٕ ژے سارِنٕے دٲیرٕ۔ \n30.\\tتہٕ سُہ اوس نہٕ سُہ قٲد خانس منز تراوُن، یوٚت تام سُہ قرضہٕ ادا کرُن۔ \n31.\\tتێلہِ ییلہ تٔمۍ سٕندِس سٲتھیو وُچھ یہِ سپدُن، تِمو گٔیہِ سٮ۪ٹھاہ افسوس، تہٕ یِمو وونُکھ پننِس مٲلکَس سُہ سورُے یُس سپدُن۔ \n32.\\tتێلہِ وۆن تٔمۍ سٕندِس مٲلکَن أمِس بُلاونہٕ پتہٕ، اے بدکار خادم، مے کٔر ژے سُہ سورُے قرضہٕ معاف، کیازِ ژے ٲس میہ یژھان۔ \n33.\\tکیا ژیہ ہا نہٕ پننِس سٲتھی خادمس پیٹھ رحم کٔرتھ، یتھہ پاٹھۍ میہ ژے پیٹھ رحم اوس۔ \n34.\\tتہٕ تٔمۍ سُند مٲلک گوٚو شرارت، تہٕ دِتُن سُہ ستٲمِس نِش حوصلہٕ، یوٚت تام سُہ واجب الادا ادا کرُن۔ \n35. یێتھے پٲٹھـ̡ کٔرِو میون آسمانی باپ تہِ تۅہہِ سٍتـ̡ یێلہِ دِلہٕ سٍتـ̡ تٔمۍ سٕندِس بٲیس سٍتـ̡ تٔمۍ سٕندِس گۅناہ معافی دِیہِ۔","1. تہٕ سپُد یہِ سپدُن، {یہِ} یێلہِ عیسیٰ علیہ السلام یِم کتھ مُکمل کٔرِتھ، سُہ دراو گلیل پى۪ٹھہٕ تہٕ آو اردن اپارِ یہودیہ کِس ساحلس مَنٛز۔ \n2.\\tتہٕ بٔڈۍ بٔڈۍ لٔگۍ أمِس پَتہٕ۔ تہٕ تٔمۍ کٔر تِم تتہِ شفا۔ \n3.\\tفریسی تہِ آیہ أمِس نِش، أمِس آزماونہٕ تہٕ وونُن، کیا أکِس مردس خٲطرٕ چھا یہ حلال زِ سُہ کرِ پرٮ۪تھ کامہِ خٲطرٕ پنٕنۍ زنانہٕ تراوُن؟ \n4.\\tتہٕ تٔمۍ دِژ جواب تہٕ وونُن تِمَن، کیا تٔمۍ پٔرِو نہٕ یہِ زِ یٔمۍ یِم گۅڈٕ گۅڈٕ بنوو، سُہ بنوو تِم مرد تہٕ زنانہٕ، \n5. تہٕ ووٚنُن، اَمہ مۅکھہٕ گژھہِ مرد مول تہٕ ماجہ ترٲوِتھ پننہِ زنانہِ سٍتـ̡ ژٔٹِتھ تہٕ یِم دۅشوے اکھ ماز آسن؟ \n6. اَمہِ مۄکھٕ چُھ نہٕ تِم دۅشوے بلکہ اَکھ ماز۔ تێمہِ کِنۍ یُس خدایہ رٔلِتھ چُھ، یێلہِ گژھہِ نہٕ انسان الگ الگ کٔرِتھ۔ \n7.\\tتِم چھِ أمِس ونان زِ موسىٰ کیازِ دیت طلاق دِنُک حُکُم۔ \n8.\\tسُہ چُھ تِمن ونان زِ موسیٰ چُھہ تہندِس دِلٕچ سختی کِنۍ تہٕ تۅہہِ پَنٕنۍ زنانہٕ دِنہٕ خٲطرٕ دِژمُت، مگر گۅڈٕ پیٹھے اوس نہٕ یہِ تِژھ آسان۔ \n9. تہٕ بہٕ چُھس ژےٚ ونان زِ یُس تہٕ یُس پننہِ زنانہِ سٍتـ̡ زنا کٔرِتھ تہٕ بییِس سٍتـ̡ خاندر کرِ، سُہ چُھ زنا کَران۔ \n10.\\tتٔمۍ سٕندِس مرید چھِ أمِس ونان زِ اگر مرد سُند معاملہ یُتھ آسہِ، تیلہِ چُھنہٕ خاندر کرُن صحیح۔ \n11.\\tمگر تٔمۍ ووٚن تِمن زِ سارِنٕے انسانس ہیکہِ نہٕ یہِ کلام حٲصل کٔرِتھ، سوائے تِمن یِمن یہِ دِنہٕ آمُت چھُ۔ \n12.\\tکینہہ کُنہِ \n13.\\tاَمہ پتہٕ آیہ أمِس نِش لۄکٹۍ شُرۍ اننہٕ، یُتھ سُہ تِمن پیٹھ اتھہٕ تھٲوِتھ دُعا کٔرِتھ، تہٕ شٲگِرَو کٔر تِمن ملامت کرنہٕ۔ \n14.\\tمگر عیسیٰ علیہ السلام ووٚن، لۅکٹٮ۪ن شُرین دِیُن تہٕ تِمن کٔرِو نہٕ میانہِ نِش یِنہٕ نِش منع کرنہٕ، تکیازِ یِمن ہٕندِس سٍتـ̡ چُھہ جنتٕچ بادشٲہی ۔ \n15.\\tتہٕ تٔمۍ تھوو تمن پیٹھ اتھہٕ تہٕ درٛاو تتہِ۔ \n16. تہٕ وُچھِتھ آو أکِس تہٕ وونُن أمِس زِ اَکھ رُک، بہٕ کُس اصل کَرُن، یُتھ بہٕ ہێکہٕ ابدی زندگی حٲصِل کٔرِتھ؟ \n17. تہٕ تٔمۍ ووٚن أمِس زِ ژٕ کیازِ چُھکھ مےٚ نیک وَنان۔ {یێلہِ} چُھہ نہٕ أکِس سٍتـ̡ نیکی سٍتـ̡ خدایہ، مگر یێلہِ ژے زندگی مَنٛز دٲخل گژھِو، تێلہِ تھاوُن حُکمن ہٕندِس حُکمس مُطٲبِق۔ \n18.\\tسُہ چُھ أمِس وَنُن، کُس چُھ؟ عیسیٰ مسیح چُھہ وَنُن، ژٕ گژھِ نہٕ قتل، زنا کٔرِتھ نہٕ ژوٗرِ کٔرٕن، تہٕ ژٕ گژھ نہٕ اپُز گوٲہی دِنہٕ، \n19.\\tپننِس مٲلِس تہٕ ماجہِ ہٕنز عزت کٔرِو: تہٕ پَنٕنِس ہمساین کٔرِو پانس پٲٹھۍ۔ \n20.\\tنوجوان چھہ تس ونان زِ یم سٲری چیز چھہِ میہ پننہِ جوانی پیٹھے تھپھ کٔرۍمٕتۍ: میہ کیا کمی چھیہ وُنی؟ \n21.\\tحضرت عیسیٰ علیہ السلام ووٚن أمِس زِ یێلہِ تہٕ یێلہِ پٲٹھـ̡ میانہِ پٲٹھۍ۔ \n22.\\tمگر ییلہ نوجوانن یہ قول بوٗز، سُہ دراو غمگسار گژھِتھ، تکیازِ تس اوس واریاہ مال۔ \n23.\\tتێلہِ وۆن عیسیٰ علیہ السلام پننین شاگردن وۆن، یێلہِ بہٕ چُھس ژیہ ونان زِ اکھ امیر انسان گژھہِ مشکل سان جنتٕچ بادشٲہی مَنٛز اژُن۔ \n24.\\tتہٕ بییہِ چُھس بہٕ ژےٚ ونان زِ اونٹِس خٲطرٕ چُھ سٕژنہِ ہٕندِ أچھ منزٕ نیرُن آسان یُس أکِس امیر سٕندِ خٲطرٕ خدایہ سٕندِس بادشاہتس مَنٛز اژُن۔ \n25.\\tییلہ تٔمۍ سٕندٮ۪و شٲگِرو بوٗز، تِم گٔیہِ سٮ۪ٹھاہ حٲران تہٕ وونُن، تیلہِ کُس ہیکہِ نجات دِتھ۔ \n26.\\tمگر حضرت عیسیٰ علیہ السلام وُچھ تِمن تہٕ وونُن تِمن سٍتـ̡ چُھہ یہِ ناممکن۔ مگر خدایہ سٍتـ̡ چُھ سارِنٕے چیٖز ممکن۔ \n27.\\tپطرس دیُت جواب تہٕ وونُن أمِس زِ وُچھ، أسۍ چھِ سارِنٕے ترٲوِتھ تہٕ تۅہہِ پتہٕ پٲٹھۍ۔ تیلہِ کیا گژھہِ اسہِ؟ \n28. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمن زِ یێلہِ بہٕ چُھس تہٕ یێمہِ سٍتـ̡ یێلہِ یێلہِ اِنسانن ہٕندِس سٍتـ̡ پى۪ٹھہٕ پى۪ٹھہٕ پى۪ٹھ، تێلہِ تہِ بِہِتھ بہن تختن پى۪ٹھ، اسرٲیلـ̡ کِس بہن قبیلن ہُند فیصلہ کٔرِتھ۔ \n29. تہٕ یُس پریتھ شخص میانہِ ناوٕ خٲطرٕ گرٕ، یا بٲے، یا بینہِ، یا مول، یا ماجہ، یا خانٛدارِنہِ، یا شُرۍ، یا زمینہٕ تراوِ، سُہ میلہِ ہتھ گنہٕ تہٕ ابدی زندگی ہُند وارث۔ \n30.\\tمگر واریاہ {یُس} گۅڈنچہ لٹہِ آسن ٲخری آسن۔ تہٕ ٲخری {گژھہِ} گۅڈنچہ لٹہِ۔","1.\\tاسمانٕچ بادشٲہی چھے أکِس انسانس ہٕندِس پٲٹھۍ، یُس صُبحس سُلہِ پننِس انگورس مَنٛز مزدور رٔٹِتھ دِنہٕ خٲطرٕ نیران چھُ۔ \n2.\\tییلہ تٔمۍ مزورن سٍتۍ اکھ پونسہ دۅہس پیٹھ اتفاق کور، تٔمۍ سوٗزۍ تم پننِس انگورس منز۔ {پینی: رومن پونسہ چھہ اکہ اونسُک ٲٹھم حصہ، یُس پانژھ شلنگ پتہٕ ستھ پینس نصف پونسہ آسان چھُ، تقریباً ژۅداہ سینٹ}\n3.\\tتہٕ سُہ دراو تریمہِ بجہ نیبر، تہٕ وُچھن باقٕے بازرَس مَنٛز بیکار کھڑا \n4.\\tتہٕ ووٚنُن تِمَن؛ تہٕ یُس تہِ صحیح چُھ، بہٕ دِیہٕ ژےٚ دِنہٕ۔ تہٕ تِم گٔیہِ پننہِ وتہِ۔ \n5.\\tبییہِ دراو سُہ شیٚیمہِ تہٕ نٔوِمِس گھنٹس لگ بھگ نیبر، تہٕ کوٚرُن یۅہے کٔرِتھ۔ \n6.\\tتہٕ کاہمہِ گھنٹہِ پتہ دراو سُہ نیبر، تہٕ وُچھ باقٕے بیکار کھڑا تہٕ تِمن وونُن زِ تم کیازِ چھِو سارِوٕے دۅہس یتہِ بیکار کھڑا روزان؟ \n7. تِم چھِ أمِس ونان زِ کٲنسہ تہِ چُھہ اسہِ رٔٹِتھ رٔٹمُت۔ سُہ چُھ تِمن ونان زِ تُہۍ تہِ گژھِو انگورس مَنٛز۔ تہٕ یُس تہِ صحیح، سُہ میلہِ۔ \n8.\\tتێلہِ ییلہ تہِ آو ، انگورُک مالک چُھ پننِس مٲلکَس ونان زِ مزورن بُلٲوِو تہٕ تِمن دِیُن ٲخری پیٹھٕ گۅڈنِکِس تام۔ \n9.\\tتہٕ ییلہ تِم وٲتِتھ {آیہ کرایہِ} دِنہٕ، تِمن میلہِ پرٮ۪تھ أکِس نفرس اکھ پونسہٕ۔ \n10.\\tمگر ییلہ گۅڈنچہ لٹہِ آو، تمو باسیوو زِ تمن گژھہِ زیادٕ مِلُن۔ تہٕ یِتھے پٲٹھۍ میلہِ پریتھ انسانس اکھ پونسہٕ۔ \n11.\\tتہٕ ییلہ تِمو میلہِ، تِمو کٔر گرٕ کِس نیک انسانس سٍتـ̡ بڑبڑاوُن، \n12.\\tیہ ونِتھ زِ یِمو پٔتِم چھُ اکھ گھنٹہٕ بٔنِتھ تہٕ ژے چھُ یِم اسہِ برابر بنٲومٕتۍ، یِمو دۅہُک بار تہٕ گرمی تُلِتھ چھِ۔ {کٔرِمٕتۍ...: یا، صرف اکھ گھنٹہٕ جٲری تھوومُت}\n13.\\tمگر تٔمۍ دیُت تِمو منزٕ أکِس جواب تہٕ وونُن، یار، بہٕ چُھس نہٕ ژے کانہہ غلطی کٔرمٕژ، کیا ژے اوسُکھ نہٕ أکِس پونسہٕ خٲطرٕ میانہِ سٍتۍ اتفاق کٔرِتھ؟ \n14.\\tپَنُن {یہ} رٔٹِتھ تہٕ پَنٕنـ̡ وَتہٕ پٔکِھہ: بہٕ دِیہٕ یێمہِ ٲخری سٍتـ̡ تہٕ ژے تہِ دِیہٕ۔ \n15. کیا یہ چُھنہٕ میانہِ خٲطرٕ جٲیز زِ بہٕ چُھس پننِس سٍتـ̡ یُس بہٕ چُھس یژھان کٔرِتھ؟ کیا چُھہ تُہٕنزِ أچھ بُر، کیازِ بہٕ چُھس اصل؟ \n16.\\tیێلہِ آسہِ ٲخری تہٕ گۅڈنیُک ٲخری آسُن: واریاہن ہٕندِ خٲطرٕ یِن بُلاونہٕ یُن، مگر واریاہ چُھہ ژارنہٕ آمُت۔ \n17.\\tتہٕ حضرت عیسیٰ علیہ السلام یُس یروشلمس کُن گژھِتھ وتہِ کٔرِتھ بارہ شٲگِرِ الگ کٔرِتھ وۆنُن، \n18. وُچھِو أسۍ یروشلمس کُن نیران۔ تہٕ انسان سُند فرزند یِیہِ بٔڈۍ پادٕرین تہٕ کاتبن سٍتـ̡ دھوکہ دِنہٕ، تہٕ تِم دِن أمِس سٍتـ̡ مارنٕچ سزا دِنہٕ، \n19.\\tتہٕ سُہ دِیہِ غیر قومن نِش طنز کرنہٕ خٲطرٕ، تہٕ کوٹھہٕ دِنہٕ خٲطرٕ تہٕ صلیب دِنہٕ خٲطرٕ، تہٕ تریمہِ دۅہہ گژھہِ سُہ دُبارٕ زندٕ۔ \n20.\\tامہ پتہ آیہ أمس نِش زبدی سٕندٮ۪ن شُرین ہٕنز موج پننین نیچوین سٍتۍ، أمِس سٍتـ̡ پوٗزا کٔرِتھ تہٕ أمِس سٍتـ̡ کُنہِ چیزس سٍتـ̡ یژھان۔ \n21.\\tتہٕ تٔمۍ ووٚن أمِس کیا چُھہ؟ سُہ چُھ أمِس ونان زِ یِم میٲنۍ زٕ نیچوۍ گژھن تُہنزِ سلطنتس مَنٛز بِہتھ، اکھ تُہٕندِس دٔچھنِس اتھس پیٹھ، تہٕ بیٛاکھ کھوورِ طرفہٕ۔ \n22.\\tمگر عیسیٰ علیہ السلام دیت جواب تہٕ وونُن، تہٕ ژیہ چھے نہٕ پتاہ زِ ژیہ کیا چُھہ منگان۔ کیا تُہۍ ہیکو تتھ پیالہ چِھہ یُس بہٕ چیٚو، تہٕ یُس بپتسمہ دِنہٕ آمُت چُھ، تہٕ یُس بہٕ بپتسمہ دِنہٕ آمُت چُھ؟ تِم چھِ أمِس ونان زِ أسۍ چھِ قٲبل۔ \n23. تہٕ سُہ چُھ تِمن ونان زِ یێمہِ سٍتـ̡ چُھہ میانہِ پیالہٕ سٍتـ̡ بپتسمہ دِنہٕ آمُت، تہٕ یێمہِ سٍتـ̡ بپتسمہ دِنہٕ آمُت چُھ، مگر میٲنِس دٔچھنِس اتھس تہٕ کھوورِ طرفہٕ بِہُن چُھہ نہٕ میٲنۍ دِنہٕ خٲطرٕ، بٔلکہِ یِہ یِمن دِنہٕ یُن، یێمہِ سٕندِ خٲطرٕ یہِ میانہِ مٲلہِ سٕندِ طرفہٕ تیار کرنہٕ آمُت چُھ۔ \n24.\\tتہٕ ییلہ داہن بوٗز، تِم گٔیہِ دۅن باین خلاف شرارت ہٕندِس سٍتـ̡ ہٕندِس سٍتـ̡ ہٕندِس دٔسۍ ہٕندِس سٍتـ̡ ۔ \n25.\\tمگر حضرت عیسیٰ علیہ السلام بُلوو تِمن پى۪ٹھ، تہٕ وونُن، تہٕ تۅہہ چھے پتاہ زِ غیر قومن ہٕندِس شہزادس چِھ تِمن پیٹھ حاکمیت تھاوان، تہٕ یِم بٔڈ چِھہ تِمن پیٹھ اختیار تھاوان۔ \n26. مگر یُس تہِ یُس تہِ بوٚڈ آسہِ، سُہ گژھہِ تُہند وزیر۔ \n27. تہٕ یُس تہٕ یُس تہٕ یُس تہٕ یُس تہٕ چُھہ تُہند خادم بنہِ: \n28. یێلہِ زن انسان سُند فرزند آو نہٕ خدمت کرنہٕ خٲطرٕ، بلکہ خدمت کرنہٕ خٲطرٕ، تہٕ واریاہن ہٕندِ خٲطرٕ پنٕنۍ زُو تاوان دِنہٕ خٲطرٕ۔ \n29.\\tییلہ تِم یریحہ پیٹھہ نیرِ، اَمہ سٍتـ̡ لٔگـ̡ واریاہ لٔگـ̡ أمِس پَتہٕ پَتہٕ۔ \n30. تہٕ وُچھِو وتہِ نِش بِہِتھ زٕ انہِ نفر، ییلہِ تِمو یہِ بوٗز زِ عیسیٰ مسیح چُھ اَتھ کُن پٔکِتھ، وَنُن زِ اے خداوند، داؤد سُند نیٚچُو، اسہِ پیٹھ رحم کرُن۔ \n31.\\tتہٕ لٔج تِمن ملامت کٔرِتھ، تِکیازِ تِم گژھن خاموش روزُن، مگر تِمو دِژ زیادٕ وَنُن زِ اے خداوند، اے داؤد سٕندِس نیٚچوِس سٍتـ̡ کرٕ اسہِ پیٹھ رحم۔ \n32.\\tتہٕ حضرت عیسیٰ علیہ السلام کھڑا تہٕ تِمن بُلاونہٕ تہٕ وونُن، تہٕ ژٕ کیا کرٕ بہٕ ژےٚ سٍتـ̡ کٔرِتھ؟ \n33.\\tتِم چھِ أمِس ونان زِ خداوند، یُس سانہِ أچھ یلہٕ یلہٕ گژھِ۔ \n34.\\tیێلہِ حضرت عیسیٰ علیہ السلام ہٕندِس أچھن پیٹھ رحم تہٕ تِمن ہٕنزِ أچھن ہٕندِس أچھن ہٕندِس اچھن ہٕندِس سٍتـ̡ دِژ تہٕ تِمو گٔیہِ أمِس پٲٹھۍ۔","1. تہٕ ییلہ تِم یروشلمس نزدیک وٲتۍ، تہٕ زیتون کِس پہاڑس کُن وٲتِتھ آیہ حضرت عیسیٰ علیہ السلام زٕ شٲگِر، \n2.\\tتِمن وَنُن زِ گامس منز گژھِو پانس خلاف تہٕ سیدِ وتہِ وُچھِو اکھ گَرٕ بٔنِتھ تہٕ أمِس سٍتۍ اکھ گُرٕ تہٕ اَکھ کۅکر وُچھِو۔ \n3. تہٕ یێلہِ کٲنسہِ {انسان} چُھہ تۅہہِ وَنُن، تۅہہِ وَنُن زِ خداوند چُھہ تِمن ہٕنز ضرورت۔ تہٕ سُہ سوزِ سُہ سوزُن۔ \n4.\\tیہ سورُے سپُد، یُس رسول اللہ صلی اللہ علیہ وآلہ وسلم وننہ اوس آمُت زِ یہ گژھہِ پورٕ سپدُن، \n5.\\tژیہ وَنُن سِیون سٕنز کورِ، وُچھِو، تُہند بادشاہ چُھہ ژے نِش آمُت، عاجز تہٕ أکِس گَرَس پیٹھ بِہِتھ، تہٕ گَرٕ سُند بُرِ۔ \n6. تہٕ شٲگِر گٔیہِ عیسیٰ مسیح سٕندِ حُکُم سٍتـ̡ کٔرِتھ، \n7.\\tتہٕ أنِتھ گَرٕ تہٕ گُرِ تہٕ تِمن لٲگِتھ پَلَو تہٕ تِمو لٲگِتھ تِمن ہٕندِس پَلَس پیٹھ۔ \n8.\\tتہٕ واریاہ بٔڈۍ لٔج وتہِ پَنٕنۍ پَلَو وَتہِ پٲٹھۍ۔ باقیو ژٔٹِتھ کُلٮ۪و پیٹھٕ لنجہِ ژٹِتھ تہٕ وتہِ کٔرِکھ تِمن کُلۍ۔ \n9.\\tتہٕ یِمو لٔگِتھ یُس امہِ برونہہ گٔیہِ، تہٕ یِمو پتہٕ یِمو ہُند دٲیرٕ داؤد سٕندِس نیچوِس سٍتـ̡ وۆنُن: بابرکت چُھہ سُہ یُس خداوند سٕندِ ناوٕ سٍتـ̡ یِوان چُھ۔ ہوشنا چُھہ تھزرس مَنٛز۔ \n10.\\tتہٕ ییلہ سُہ یروشلمس مَنٛز آو، سٲرۍسٕے شہرس آو منتقل کرنہٕ، یہِ کُس چُھ؟ \n11.\\tتہٕ ہجوم ووٚن زِ یہِ چُھ عیسیٰ مسیح گلیل کِس ناصرتُک پیغمبر۔ \n12.\\tتہٕ عیسیٰ مسیح ژاو خدایہ سٕندِس مندرس مَنٛز، تہٕ کٔرِن تِم سٲری یِم مندرس مَنٛز کٕننہٕ تہٕ ہینہٕ وٲلۍ، تہٕ کٔرٕن پٲنسہٕ بدلاون والٮ۪ن ہٕنزِ میزہٕ تہٕ کۅتر کٕننہٕ والٮ۪ن ہٕنزِ نشستہٕ الٹٲوِن، \n13. تہٕ تِمن وونُن زِ یہِ چُھ لیکھنہٕ آمُت، میون گرٕ یِیہِ نمازُک گرٕ وَننہٕ۔ مگر ژے بنوو یہِ چورن ہُند گۅپھ۔ \n14.\\tتہٕ انہِ تہٕ لوٚنگ آو أمِس نِش مندرس مَنٛز۔ تہٕ تٔمۍ کٔر تِمن شفا۔ \n15.\\tتہٕ ییلہ بٔڈۍ پادٕرۍ تہٕ کاتب وُچھ تٔمۍ سٕندِ کٔرمٕژ حیرت انگیز کامہِ، تہٕ شُرۍ ٲسۍ مندرس مَنٛز روُن، تہٕ وَنُن زِ ہوشنا داؤد سٕندِس نیچوِس سٍتۍ۔ تِم گٔیہِ ناراض گٔیہِ، \n16.\\tتہٕ وونُن أمِس زِ یِم کیا چُھہ بوزان چھُو؟ تہٕ عیسیٰ مسیح چُھ تِمن وَنان۔ کیا ژے چُھہ نہٕ زانہہ پٔرِمُت، شُرین تہٕ دۄدٕ دِنہٕ والٮ۪ن ہٕندِس مَنٛزٕ چُھہ ژے تعریف کٔرمٕژ؟ \n17.\\tتہٕ سُہ دراو تِم تہٕ شہرٕ نیبر بیتھنی کُن۔ تہٕ سُہ روٗد اَتہِ روزُن۔ \n18.\\tوۅنۍ صبحس ییلہ سُہ شہرس منز واپس آو، تس ٲس فاقہٕ۔ \n19.\\tییلہ تس وتہِ منز اکھ انجیر کُل وُچھ، سُہ آو اتھ نِش، تہٕ لوٚب نہٕ اتھ پیٹھ کینہہ تہِ، صرف پنہٕ ؤتھر ورٲے تہٕ وونُن زِ از تام گژھہِ نہ ژے پیٹھ کانہہ میو۔ تہٕ وُچھُن انجیر کُلِس ہُرۍ۔ {اکھ انجیر کُل}\n20.\\tتہٕ ییلہ مریدن وُچھ، تِمو گٔے حٲران تہٕ وونُن، انجیر کُل کوتاہ جلدی گۆو مرزاونہٕ۔ \n21. عیسیٰ مسیحن دیُت جواب تہٕ وونُن تِمن پٔزۍ پٲٹھۍ، یێلہِ تہٕ یێلہِ تہِ یێلہِ تہٕ یێلہِ تہِ یێلہِ تہِ یێلہِ تہِ یێلہِ ژٔٹِتھ ژٔلِتھ تہٕ سمندرس مَنٛز دِنہٕ یِو۔ یێلہِ گژھہِ سپدُن۔ \n22. تہٕ سارِنٕے چیز، یُس تہٕ یُس تہٕ یُس تہٕ دعاہس مَنٛز منگنہٕ یِو، یُس تہٕ \n23.\\tتہٕ ییلہ سُہ مندرس منز آو، سردار پادٕرۍ تہٕ لُکن ہٕندِ بزرگ آیہِ أمِس نِش یِتھٕ پٲٹھۍ سُہ ہیچھناوان اوس، تہٕ وونُن، ژے کمہِ اِختِیارٕ سٍتـ̡ چُھہ یِم چیز دِوان۔ تہٕ ژے کٔمۍ دِیُت یہِ اِختِیار؟ \n24.\\tتہٕ حضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن تِمن تہِ زِ بہٕ تہِ پرژھہٕ ژےٚ اکھ کتھ یُس بہٕ کمہِ اِختِیارٕ سٍتـ̡ کران چھُس۔ \n25.\\tیوحنا سُند بپتسمہ کتہِ اوس؟ اسمانہٕ پیٹھ، یا انسانس سٍتـ̡ ؟ تہٕ تِمو کٔر پانس سٍتـ̡ استدلال کٔرِتھ ونان، اگر أسـ̡ اسمانہٕ پى۪ٹھ۔ سُہ وَنُن اسہِ پى۪ٹھ، تێلہِ کیازِ کٔر نہٕ تٔمِس پى۪ٹھ۔ \n26. مگر اگر أسۍ ونو انسانس متعلق۔ أسۍ چھہِ لوکن کھوژان۔ تکیازِ سٲری چھہِ یوحنا پیغمبر مانان۔ \n27.\\tتہٕ تِمو دِژ عیسیٰ ہس جواب تہٕ وونُن، أسۍ ہیکو نہٕ ؤنِتھ۔ تہٕ تٔمۍ ووٚن تِمَن زِ بہٕ کمہِ اِختِیارٕ سٍتـ̡ بہٕ یِم کٲم کران چھُس۔ \n28.\\tمگر تۅہہ کیا خیال چھُ؟ أکِس {یقین} شخصس ٲسۍ زٕ نیچوۍ۔ تہٕ سُہ آو گۄڈنِکِس نِش، تہٕ ووٚنُن، نیچو، گژھ دۅہہ میٲنِس انگورس مَنٛز کٲم کٔرِتھ۔ \n29.\\tتٔمۍ دیُت جواب تہٕ ووٚنُن، بہٕ کرٕ نہٕ، مگر امہ پتہ گۆو تٔمۍ توبہ تہٕ گٔیہ۔ \n30.\\tتہٕ سُہ آو دویمِس نِش، تہٕ وونُن یِتھے پٲٹھۍ وونُن۔ تہٕ تٔمۍ دِژ جواب تہٕ وونُن، بہٕ {گژھو} جناب: تہٕ گوٚو نہٕ۔ \n31.\\tیِمو منزٕ کیا تٔمِس مٲلہِ سٕنزِ مرضی کٔرِتھ؟ تِم چھِ أمِس ونان گۅڈنِک۔ عیسیٰ مسیح چُھ تِمن ونان زِ بہٕ چُھس تۅہہِ ونان زِ پبلکن تہٕ بدکار گژھن خدایہ سٕندِس بادشاہتس مَنٛز۔ \n32.\\tیوحنا آو نیکی ہٕندِس وتہِ سٍتـ̡ تہٕ تۅہہِ کٔر نہٕ أمِس پژھہٕ پٲٹھۍ۔ \n33.\\tبیاکھ تمثیل بوزو: اتہِ اوس اکھ خاص گرہ دار، یمۍ انگور باغ لاگان اوس، تہ اتھ اندۍ لٔگتھ تہ اتھ منز اکھ شراب، تہ اکھ مینار بنووُن، تہ دِژن زمیندارن نِش، تہ گۆو دور ملکس منز۔ \n34. تہٕ ییلہ میوُک وق نزدیک آو تٔمۍ سوٗزۍ پنٕنۍ نوکر زمیندارن نِش، تاکہ تِم میلن امہِ ہُند پھل۔ \n35.\\tتہٕ کاشتکارو رٔٹِتھ تٔمۍ سٕندِس نوکر تہٕ أکِس مارُن تہٕ بییِس کٔرِکھ کَنہِ تہٕ بییِس کٔرِتھ کٔرِتھ کٔرِتھ۔ \n36.\\tبییہِ سوٗزۍ تمٔۍ گۅڈنِکہِ کھۅتہٕ زیادٕ باقٕے خدمتگار تہٕ تِمو کٔر تِمن سٍتـ̡ یِتھے پٲٹھۍ ۔ \n37. مگر ٲخٕر کار سوٗز تِمن نِش پنُن نیچو تہٕ یہِ ونان زِ تِم کرِ میٲنِس نیچوِس احترام۔ \n38.\\tمگر ییلہ زمیندارو نیچو وُچھ، تِمو ووٚن پانس منز، یہِ چُھ وٲرِث۔ آؤ، أسۍ مارو أمِس تہٕ أسۍ أمِس وٲرِثس پیٹھ قبضہٕ۔ \n39.\\tتہٕ تِمو رٔٹِتھ تہٕ کٔرِکھ سُہ انگور منزٕ کٔڈِتھ تہٕ مارُکھ سُہ ۔ \n40. تێلہِ ییلہ انگورُک مالک ییہ، سُہ کیا کرِ تمن زمیندارن سٍتۍ؟ \n41.\\tتِم چھِ أمِس ونان زِ سُہ کرِ تِمن بدکار نفرن برباد تہٕ دِیہِ پنُن انگور باقین زمیندارن خٲطرٕ، یُس تٔمِس موسمس مُطٲبق پھل دِیہِ۔ \n42.\\tعیسیٰ چُھ تِمن ونان، کیا تۅہہ چھُنہٕ صحیفس مَنٛز زانہہ پٔرِمُت، سُہ پٔر یُس معمارو رد کٔرِمُت، سُہ چُھ کونہٕ ہُند کلہٕ بنیومُت: یِہ چُھ خداوند سٕنز کٲم تہٕ یہِ چُھ سانہِ نظرِ منز حیرت انگیز۔ \n43. تێمہِ کِنۍ چُھس بہٕ ژے ونان زِ خدایہِ سٕنز بادشٲہی یِیہِ ژے نِش نِنہٕ، تہٕ یِیہِ أکِس قومس دِنہٕ یُس امہِ سُند پھل دِنہٕ ییہِ۔ \n44. یُس تہِ اتھ کنس پیٹھ پیوٚو سُہ گژھہِ پھُٹُن، مگر یُس تہِ یُس پیوٚو، سُہ گژھہِ سُہ گٔژھِتھ پٔرِتھ۔ \n45. تہٕ ییلہ سردار پادٕرۍ تہٕ فریسیو تٔمۍ سٕنز تمثیل بوز، تِمو گوو تِمن ہٕنز کتھ کرنہٕ۔ \n46.\\tمگر ییلہ تِمو أمِس پیٹھ اتھہٕ تراونٕچ کوشش کٔر، تِمو گٔیہِ ہجومَس کھوژان، تِکیازِ تِمو اوس أمِس پیغمبر مانان۔","1. آسمانٕچ بادشٲہی چھے أکِس خاص بادشاہس ہٕندۍ پٲٹھۍ، یٔمۍ پننِس نیچوِس خٲطرٕ خانٛدر کٔر، \n2.\\tتہٕ سوٗزِن پَنٕنـ̡ خانٛدرٕ خٲطرٕ بُلاونہٕ خٲطرٕ تِمن بُلاونہٕ خٲطرٕ، تہٕ تِم آیہ نہٕ یِنہٕ۔ \n3.\\tبییہِ سوٗزۍ تمۍ باقی نوکر تہ وونُن زِ تِمن کُس کُس حکم دِنہٕ آمُت چھُ، وُچھ، مے چُھس پنُن شامُک بتہٕ تیار کورمُت: میٲنۍ بیل تہٕ {میانۍ} موٹۍ گٔیہِ مارنہٕ، تہٕ سارِنٕے چیز {چھِ} تیار: کھاندرس منز آو ۔ \n4.\\tمگر تِمو کٔر ہلکہٕ تہٕ گٔیہِ پنٕنۍ وَتھ، اکھ أمۍ سٕندِس کھہس کُن، بیاکھ تٔمۍ سٕندِس تجارتس کُن۔ \n5.\\tتہٕ باقیَن رٔٹِتھ تٔمۍ سٕندِس خادمَس نِش تہٕ کٔرٕن تِمن ہٕندِس دٲیرٕ سٍتـ̡ التجا تہٕ مارُن {تِم}۔ \n6.\\tمگر ییلہ بادشاہن یہِ بوز، سُہ گوٚو شرارت: تہٕ تٔمۍ سوٗزۍ پنٕنۍ فوج تہٕ تِم قاتل تباہ کٔرِتھ تہٕ تِہُند شہر زٲلِتھ۔ \n7.\\tاَمہِ پتہٕ چُھ سُہ پننین خادمَن ونان زِ خانٛدر چُھ تیار، مگر یِم دِنہٕ آمٕتۍ ٲسۍ، تِم ٲسۍ نہٕ لایق۔ \n8.\\tتَمہِ کِنۍ گژھِو شاہراہن منز، تہٕ یوتاہ تہِ لٔبِو، کھاندرٕچ وُچھِو۔ \n9.\\tیێلہِ گٔیہِ تِم نوکر شاہراہن کُن، تہٕ یِمو سارِنٕے سارِنٕے یِمن ہٕندِس بُرٕ تہٕ اَصٕل لٔبِتھ جمع کٔرِتھ، تہٕ کھاندرٕ سپُد پژھہِ سٍتـ̡ سجاونہٕ۔ \n10.\\tتہٕ ییلہ بادشاہ پژھین وچھنہٕ خٲطرٕ آو، تٔمۍ وُچھ تتہِ اکھ شخٕص یُس نہٕ کھاندرُک پلو لٲگِتھ اوس۔ \n11.\\tتہٕ سُہ چُھ أمِس وَنُن، یار، ژٕ کِتھہ کٔنۍ آو نہٕ کھاندرُک پلو ہیوٚت؟ تہٕ سُہ اوس بے زبان۔ \n12. پتہٕ ووٚن بادشاہن نوکروں زِ أمِس اتھہٕ تہٕ کھۄر بٔنِتھ نِن، تہٕ نیرِن نیبرِمِس اندِپِس منٛز۔ اَتہِ گژھہِ وَنُن تہٕ دندٕ گٕرٕنۍ۔ \n13.\\tواریاہن ہندِ خاطرہ چھہ وننہ آمت، مگر کینہہ چھہِ منتخب کرنہ آمتۍ۔ \n14.\\tامہ پتہ گۆو فریسی، تہٕ رٔٹِتھ مشورٕ زِ تم کِتھہ پٲٹھۍہیکن أمِس کتھہِ منز پھٔلِتھ۔ \n15.\\tتہٕ سوٗزۍ تِمو ہیروڈین سٍتـ̡ پنٕنـ̡ شٲگِرِ أمِس نِش، یہِ وونُن زِ أسـ̡ چُھہ پٔزۍ پٲٹھـ̡ تہٕ چُھہ خدایہِ سٕنز وتھ ہیچھناوان تہٕ چُھہ نہٕ کٲنٛسہِ انسانس سٍتـ̡ پرواہ کران، تکیازِ تُہۍ چُھہ نہٕ انسانس سٍتـ̡ \n16.\\tتَمہِ کِنۍ وَنُن زِ تُہۍ کیا چُھہ سوچان؟ کیا قیصرس خراج دِنۍ چھا جٲیز، کِنہٕ نہ؟ \n17.\\tمگر حضرت عیسیٰ علیہ السلامن وُچھ تِہٕنزِ بدکٲری تہٕ وونُن، یێلہِ کیازِ چُھہ میہ دِوان دِنہٕ، منافقو؟ \n18.\\tہاو میہ خراج تحسین ہُند پٲنسہٕ۔ تہٕ تِمو أنۍ أمِس اکھ پونسہٕ۔ {پٲنسہٕ: ستھ پینس نصف پٲنسہٕ}\n19.\\tتہٕ سُہ چُھ تِمن ونان زِ یہِ تصویر تہٕ تحریر کٔمۍ سٕندِس {چُھ}؟ {superscription: or, inscription}\n20.\\tتِم چھِ أمِس ونان قیصر سٕندِ۔ اَمہِ پَتہٕ چُھ سُہ تِمن ونان زِ تِم چیز دِیِو قیصرس یِم قیصر سٕندِ چھِ۔ تہٕ خدایہ سٕندِس سٍتـ̡ دِیُن تِم چیز یِم خدایہِ سٕندِ سٍتـ̡ چھِ۔ \n21.\\tییلہ تِمو یِم لفظ بوٗزِ، تِمو گٔیہِ حٲران تہٕ أمِس ترٲوِتھ گٔیہِ پننہِ وتہِ۔ \n22.\\tامی دۅہہ آو أمِس نِش صدوقی یُس ونان چھُ زِ قیامتُک کانہہ تہِ چھُنہٕ تہٕ پرژھُکھ أمِس \n23.\\tیہ ونِتھ زِ اگر کانہہ مرد مٔرِتھ تہٕ کانہہ اولاد آسہِ، تٔمۍ سُند بٲے کرِ پننہِ زنانہِ سٍتـ̡ خاندر تہٕ بٲے سٕندِس بٲیِس سٍتـ̡ بُلـ̡ دِنہٕ۔ \n24. وۅنۍ ٲسۍ اسہِ سٍتۍ ستھ بٲے: تہٕ گۅڈنچہ لٹہِ ییلہ تٔمۍ زنانہِ سٍتۍ خاندر کٔر، مٔرۍمٕژ تہٕ کانہہ مسلہٕ آسنہٕ کِنۍ ترووُن پننہ زنانہٕ پننِس بٲیِس نِش۔ \n25.\\tیتھے پاٹھۍ چھہ دۆیم تہِ تہ تریم تہِ سٔتِمِس تام۔ {سٔتِم: ستھ تہِ}\n26. تہٕ ٲخٕری زنانہٕ تہِ مٔرۍ۔ \n27. تَمہِ کِنۍ قیامتس مَنٛز کٔمۍ سٕنز زنانہٕ آسہِ سَتَن مَنٛز؟ تِکیازِ تِمن سارِنٕے ٲس سۄ ۔ \n28.\\tحضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن تِمن زِ تُہۍ چھِو غلطی کٔرِتھ، صحیفہٕ تہٕ نہ خدایہِ سٕندِس طاقتس سٍتـ̡ زانان چھِ۔ \n29. کیازِکہ قیامتس منز چِھ نہٕ تم خاندر کران، تہٕ نہ چِھ خاندر کرنہٕ یوان، بلکہ چِھ آسمانس منز خدا سٕندِ فرشتن ہٕندۍ پٲٹھۍ۔ \n30. مگر یێلہِ چُھہ نہٕ تۅہہ پٔرِتھ یُس خداین ژیہ سٍتـ̡ وننہٕ آمُت چُھ، \n31. بہٕ چُھس ابراہیم سُند خدا، تہٕ اسحاق سُند خدا، تہٕ یعقوب سُند خدا؟ خدا چُھنہٕ مرن ہُند خدا بلکہ زندٕ سُند خدا۔ \n32.\\tتہٕ ییلہ ہجومن بوٗز، تِم گٔیہِ تٔمۍ سٕندِس نظریہٕ سٍتـ̡ حٲران۔ \n33.\\tمگر ییلہ فریسیو یہ بوز زِ تٔمۍ چھِ صدوقی ژھۄپہٕ کٔرۍمٕتۍ، تِم گٔیہِ اَکہٕ وٹہٕ۔ \n34.\\tاَمہ پتہٕ یِمو منزٕ اَکھ {یُس} وکیل اوس، تٔمِس پرژھُن اکھ سوال، تہٕ وونُن لالچ، \n35.\\tمالہ، شریعتس مَنٛز کُس بٔڈ حکم چُھ؟ \n36. حضرت عیسیٰ علیہ السلام ووٚن تٔمِس زِ تُہۍ کٔرِو خداوند پنُن خدایہ پنہٕ نِس پوٗرٕ دِلہٕ سٍتـ̡ تہٕ پَنٕنـ̡ سٲرۍسٕے دِلہٕ سٍتـ̡ تہٕ پنہٕ نِس سارِنٕے دِلہٕ سٍتـ̡ محبت کٔرِتھ۔ \n37. یہِ چُھ گۄڈنیُک تہٕ بوٚڈ حُکم۔ \n38.\\tدۆیِم {چُھ} یِتھٕ پٲٹھۍ، ژے کٔرِو پننِس ہمساین پانس پٲٹھۍ۔ \n39.\\tیِمن دۅن حُکمن پیٹھ چُھ شریعت تہٕ پیغمبرن ہٕندِس سٍتـ̡ لٹاونہٕ آمُت۔ \n40. یێلہِ یێلہِ فریسی جمع گٔیہِ، حضرت عیسیٰ علیہ السلام پرژھ تِمن سٍتـ̡ \n41.\\tونان، مسیحس متعلق کیا چُھہ تۅہہ سوچان؟ سُہ کُس نیچو چُھ؟ تِم چھِ أمِس ونان {داؤد سُند نیٚچُو}۔ \n42. سُہ چُھ تِمن ونان زِ تیلہِ کِتھ کٔنۍ چُھ داؤد روحس سٍتـ̡ أمِس خداوند ونان \n43.\\tخداوند ووٚن میٲنِس آقاہس زِ بہٕ بِہتھ میانہِ دچھنہِ اتھس پیٹھ، یوتام نہٕ بہٕ چانہِ دُشمن پنُن کھۅر بٔنِتھ؟ \n44.\\tاگر داؤد تس رب ونان چھہِ، سہ کتھہ پاٹھۍ چھہ تس نیچو۔ \n45.\\tتہِ ہیوٚک نہ کانہہ انسان أمس کُنہِ لفظس جواب دِتھ تہ نہ ہیوٚک کٲنسہِ انسانس امہِ دۅہہ پیٹھہ بییہ کانہہ {سوال} پرژھان۔","1. تێلہِ وۆن عیسیٰ علیہ السلام تہٕ پننین شاگردن سٍتـ̡ \n2.\\tیہ ونِتھ زِ کاتب تہٕ فریسی چھِ موسىٰ سٕنزِ نشستس پیٹھ بِہتھ: \n3. تَمہِ کِنۍ یُس تہِ تِم وُچھِو تہٕ کٔرِو تہٕ کٔرِو۔ مگر تِمن ہٕندِس کامہِ پَتہٕ کٔرِو نہٕ، تِکیازِ تِم چھِ ونان تہٕ نہٕ کران۔ \n4. تِم چھِ گۄبٕر بوجھہٕ تہٕ تکلیف دِنہٕ خٲطرٕ گٔنڈِتھ، تہٕ تِم چھِ انسانن ہٕندِس پھیکس پیٹھ تراوان۔ مگر تِم چِھ نہٕ تِمن اَکہِ اونگجہِ سٍتـ̡ حرکت دِوان۔ \n5.\\tمگر تِہٕندِ سارِنٕے کامہِ سٍتـ̡ یِم انسانس سٍتـ̡ وُچھنہٕ مۅکھٕ کران چھِ: تِم چھِ پَنٕنـ̡ کٔرِتھ، تہٕ پَنٕنـ̡ پى۪ٹھـ�\n6. تہٕ دعوتن مَنٛز پیٹھمہِ کمرہٕ تہٕ عبادت خانن مَنٛز اہم نشستن سٍتـ̡ محبت کرُن، \n7. تہٕ بازرَن مَنٛز سلام، تہٕ یِمن ہٕندِس مَنٛز وَننہٕ یِن، ربی، ربی۔ \n8. مگر تم گژھ نہٕ ربی وننہٕ یُن: کیازِ اکھ چُھ تُہند مالک، {حتیٰ کہ} مسیح۔ تہٕ تم سٲری چھ بٲے۔ \n9.\\tتہٕ کُنہِ تہِ بُلاو نہ پننِس مٲلس زمینس پیٹھ، یُس اسمانس مَنٛز چُھ۔ \n10. تہٕ یێلہِ چُھہ تُہُند مٲلک، یێلہِ تہِ چُھہ مسیح۔ \n11. مگر یُس تۅہہِ مَنٛز سارِوٕے کھۄتہٕ بوٚڈ آسہِ، سُہ آسہِ تُہند خادم۔ \n12. تہٕ یُس پانس تھزرِ کرِ، سُہ گژھہِ ذلیل کرنہٕ۔ تہٕ یُس پانس عاجز کرِ، سُہ گژھہِ تھزراونہٕ یُن۔ \n13. مگر افسوس چُھہ تۅہہ، کاتب تہٕ فریسی، منافقو! تکیازِ تم چُھہ انسانس خلاف آسمانچ بادشٲہی بند کٔرتھ، کیازِ تم چِھ نہٕ پانس اندر اژان تہٕ نہ چُھہ اژنہٕ خٲطرٕ دٲخل گژان۔ \n14. اے کاتبو تہٕ فریسی، منافقو، افسوس! تکیازِ تم چھِو بیواہ ہٕندِس گرس کھٮ۪وان، تہٕ بہانہ کٔرِتھ چھِو زیٹھ دُعا کران، تێلہِ گژھہِ تۅہہ بۆڈ سزا میلان۔ \n15. ہا ہا تۅہہِ کاتبو تہٕ فریسی، منافقو! یێلہِ چُھہ سمندرس تہٕ زمینس سٍتـ̡ أکِس مذہب دِنہٕ مۅکھہٕ سُہ بَناوُن، تہٕ ییلہ سُہ بَناونہٕ ییہِ، تہٕ یێلہِ سُہ بَناوُن پانس کھۅتہٕ دۆگنہٕ زیادٕ جہنمُک شُر بناوان۔ \n16.\\tہا یُس تہِ مندرس سٍتـ̡ قسم کھیوان چُھ، سُہ چُھہ نہٕ کانہہ تہِ۔ مگر یُس تہِ مندر کِس سۄنہٕ سٍتـ̡ قَسم کَرُن، سُہ چُھ مقروض! \n17.\\tبیوقوف تہٕ انہِ: کیازِ سۅنہٕ چھا بوڈ یا مندر یُس سون مقدس بناوان چھُ؟ \n18.\\tیُس تہِ قربان گاہُک قسم کھُلہِ، سُہ چُھہ نہٕ کانہہ تہِ۔ مگر یُس تہِ اتھ پیٹھ موجود تحفہٕ سٍتـ̡ قَسم کٔرِ، سُہ چُھ قصوروار۔ {قصوروار: یا، مقروض، یا، پابند}\n19.\\tبیوقوف تہٕ انہِ: کیازِ کیا {چُھ} بوڈ تحفہٕ یا قربان گاہ یُس تحفہٕ مقدس کران چُھ؟ \n20. یێمہِ کِنۍ یُس تہِ قربان گاہٕ سٍتـ̡ قَسم کَرُن، سُہ چُھہ اَتھ سٍتـ̡ تہٕ سارِنٕے چیزـ̡ سٍتـ̡ قَسم کَرُن۔ \n21. یُس تہٕ یُس مندرس سٍتـ̡ قَسم کَرُن، سُہ چُھ اَتھ سٍتـ̡ تہٕ یُس اَتھ مَنٛز روزان چُھ، سُہ چُھ قَسم کَران۔ \n22. یُس اسمانس سٍتـ̡ قَسم کَرُن، سُہ چُھ خدایہِ سٕندِس تختس سٍتـ̡ تہٕ یُس اتھ پیٹھ بِہِتھ چُھ، سُہ چُھ قَسم کَران۔ \n23.\\tتۅہہِ ہُند افسوس چھُ، کاتب تہٕ فریسی، منافقو! تکیازِ تۅہہ چُھکھ پودنہٕ تہٕ انیس تہٕ کامین ہُند دٔہُم دِوان، تہٕ شریعت، فٲصل، رحمت، تہٕ ایمانٕکۍ وزنی معاملہٕ تراوِمٕتۍ: یِم گژھِ تۅہہ کرٕنۍ، تہٕ باقٕے تراوُن نہٕ۔ {anise: Gr. dill}\n24. {یے} انہِ رہنما، یُس موٚنگس پیٹھ زور دِوان چھُ، تہٕ اونٹ نِگِل کران چھُ۔ \n25. اے کاتب تہٕ فریسی، منافقو، افسوس! تکیازِ تم چِھ پیالہ تہٕ تھالہٕ نیبر صاف کران، مگر اندر چِھ تم زیادتی تہٕ زیادتی سٍتـ̡ بٔرِتھ۔ \n26.\\t{ژے} انہِ فریسی، گۅڈٕ صاف کرُن یُس پیالہ تہٕ تھالس اندر چُھ، یُتھ نیبرِم تہِ گژھہِ صاف کرنہٕ۔ \n27. اے کاتب تہٕ فریسی، منافقو، افسوس! تکیازِ تم چھہِ سفیدٕ قبرن ہٕندۍ پٲٹھۍ، یُس ظٲہر کُن خوبصورت باسان چھُ، مگر تم چھہِ مردہ ہٕنزِ اڈجہِ تہٕ سارِنٕے ناپاک سٍتـ̡ بٔرِتھ۔ \n28.\\tیِتھے پٲٹھـ̡ تہِ چُھہ تُہۍ ظاہری طور انسانس سٍتـ̡ نیک ظٲہر سپدان، مگر أندرِس اندر چھِو منافقت تہٕ بدکاری سٍتـ̡ بٔرِتھ۔ \n29. اے کاتب تہٕ فریسی، منافقو، افسوس! تکیازِ تم چھِو پیغمبرن ہٕنزِ قبر بناوان، تہٕ صالحن ہٕندِس قبرس سجاوان چھِو، \n30.\\tتہٕ وَنُن زِ اگر أسۍ پننین آباؤ اجدادن ہٕندِس زمانس مَنٛز آسہٕ ہا ہا نہٕ أسۍ پیغمبرن ہٕندِس خونس مَنٛز تِمن سٍتـ̡ شریک سپدان۔ \n31.\\tتێلہِ چھِو تم پانس گواہ بنوو زِ تم چھہِ تمن ہندۍ اولاد یمو پیغمبرن قتل کٔرۍ۔ \n32.\\tتیلہ کرو پننین مٲلن ہند پیمائش۔ \n33.\\t{یے} ناگ، {یے} سانپ، ژیہ کِتھہ پاٹھۍ بچٲوِتھ جہنم کِس لعنتس نِش۔ \n34. اَمہِ مۄکھہٕ چُھس بہٕ توے نِش پیغمبر، دانا تہٕ کاتب سوزان، تہٕ یِمو منزٕ کُنہِ کُنہِ مٲرِتھ تہٕ صلیب دِنہٕ۔ تہٕ یِمو منزٕ کُنہِ سٍتـ̡ پَنٕنـ̡ عبادت خانن مَنٛز کوٹھہٕ دِیُو، تہٕ یِمن سٍتـ̡ شہرٕ پۯاوُن تہٕ یِمن سٍتـ̡ دِنہٕ۔ \n35.\\tیُتھ زِ زمینس پیٹھ یُس نیک خون یُس نیک ہابیل سٕندِ خونہٕ پیٹھٕ باراکیاس سٕندِس نیچو زکریا سٕندِس خونس تام، یُس ژے مندرس تہٕ قربان گاہس درمیان مار۔ \n36. بہٕ چُھس ژےٚ ونان زِ یِم سٲری چیز یِن یَتھ نسلس مَنٛز یِنہٕ۔ \n37.\\tاے یروشلم، یروشلم، یُس پیغمبرن ماران چھُ، تہٕ یِم توے نِش سوزنہٕ آمٕتۍ چھِ، بہٕ کٲژاہ لٹہِ ہا چانہِ شُرِ جمع کٔرِتھ، یِتھٕ پٲٹھۍ کۅکُر پَنٕنِس پَکھن تَل کٔرِتھ، تہٕ تُہۍ کٔرِو نہٕ! \n38.\\tوچھو تُہند مکانہ چُھہ ژے ویران تراونہٕ آمُت۔ \n39. تِکیازِ بہٕ چُھس ژےٚ وَنُن زِ یێلہِ تہِ وُچھِو نہٕ بہٕ یێلہِ تہٕ یێلہِ تہِ وُچھِو، یُس خداوند سٕندِ ناوٕ سٍتـ̡ یِوان چھُ۔","1.\\tتہٕ عیسیٰ علیہ السلام دراو نیبر، تہٕ دراو مندرٕ منز، تہٕ تٔمۍ سٕندِ شٲگِر آیہِ أمِس نِش ہاونہٕ خٲطرٕ۔ \n2. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمَن زِ یِم سارِنٕے چیٖز چھِنہٕ وُچھمٕتۍ؟ بہٕ چُھس ژےٚ وَنُن زِ یَتہِ گژھہِ نہٕ اَکھ کٔنہِ کٔنہِ یُس نہٕ تراونہٕ یِنہٕ۔ \n3.\\tتہٕ ییلہ سُہ زیتون کِس پہاڑس پیٹھ بِہتھ، شٲگِر آیہِ أمِس نِش وَنُن، وَنُن زِ یِم چیز کٔر سپدِ؟ تہٕ تُہٕندِ یِنٕچ تہٕ دُنیاہٕکہِ خاتمٕچ نشانی کیا آسہِ؟ \n4. تہٕ حضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن تِمن زِ تِمن ہُند خیال تھاوُن زِ کانہہ تہِ انسان ہیکہِ نہٕ دھوکہٕ دِتھ۔ \n5. تکیازِ واریاہ لوگ یِن میانہِ ناوٕ سٍتـ̡ یِن، بہٕ چُھس مسیح۔ تہٕ کرٕ واریہن لوٗکن دھوکہٕ۔ \n6.\\tتہٕ ژے بوزِو جنگن ہٕنز افواہ تہٕ جنگن ہٕنز افواہٕ: وُچھِو نہٕ تۅہہ پریشان گژھُن: یِمن سارِنٕے چیزن گژھہِ سپدُن، مگر وُنہِ تہِ چھُنہٕ انجام سپدُن۔ \n7. قومہٕ گژھہِ قومس خلاف کھڑا تہٕ بادشٲہی گژھہِ بادشاہتس خلاف تہٕ مختلف جاین گژھن قحط، وبا تہٕ زلزلہٕ۔ \n8.\\tیم سٲری {چھہِ} غمُک آغاز۔ \n9. تیلہ گژھن تۅہہ مصیبت دِنہٕ خٲطرٕ حوالہٕ، تہٕ مارن تہٕ میانہِ ناوٕ خٲطرٕ گژھن سارنٕے قومن سۭتۍ نفرت۔ \n10. تہٕ پتہٕ گژھن واریاہ ناراض تہٕ اکھ أکِس سۭتۍ دھوکہ دِن، تہٕ اکھ أکِس سۭتۍ نفرت۔ \n11.\\tتہٕ واریاہ اپُز پیغمبر سپدن تہٕ واریاہن دھوکہٕ دِنۍ۔ \n12. تہٕ کیازِ بدکاری گژھہِ زیادٕ، واریاہن ہُند محبت گژھہِ سرد۔ \n13. مگر یُس ٲخرس تام روزِ، سُہ گژھہِ نجات دِنہٕ۔ \n14. تہٕ بادشٲہی ہٕنز یہِ انجیل یِیہِ سارِنٕے دُنیاہس مَنٛز سارنٕے قومن ہٕندِ خٲطرٕ گواہ دِنہٕ۔ تہٕ پَتہٕ یِیہِ انجام یِنہٕ۔ \n15.\\tتێلہِ ییلہ تۅہہ وُچھِو ویرانی ہٕنز مکروہ وُچھِو، یێمہِ سٍتـ̡ دانیال نبی سٕندِ دٔسۍ کتھ کرنہٕ آمٕژ چھِ، تۯێلہِ گژھِو مقدس مقامس مَنٛز کھڑا (یُس تہِ پٔرِتھ چُھ، سُہ گژھہِ سمجھُن:)\n16.\\tیِم یُس یہوداہس مَنٛز چھُ، تِم گژھن پہاڑن کُن ژلُن: \n17.\\tیُس مکانس پیٹھ آسہِ سُہ گژھہِ نہٕ پننہِ گرٕ منزٕ کانہہ چیز نِنہٕ خٲطرٕ بۄن وسُن: \n18.\\tیُس کھاہس منز چھُ، سہ گژھہِ واپس پَنُن پلو نِنہٕ خٲطرٕ واپس۔ \n19.\\tیِمن ہٕندِس دۅہس مَنٛز دِنہٕ والٮ۪ن تہٕ یِمن ہٕندِس دۅہس مَنٛز دِنہٕ والٮ۪ن ہٕندِ خٲطرٕ افسوس! \n20. مگر دُعا کٔرِو زِ تُہُند پرواز گژھہِ نہٕ وندس مَنٛز، تہٕ نہ سبت دۅہہٕ: \n21.\\tتیلہِ گژھہِ بٔڈ مصیبت، یُس نہٕ دنیاہٕکہِ ابتداہس پیٹھٕ از تام آسہِ، نہٕ تہٕ آسہِ نہٕ زانہہ تہِ۔ \n22. تہٕ یِمن دۅہن ہٕندِ خٲطرٕ گژھِ نہٕ یِم دۅہ کم کرنہٕ یِن، تِمن ہُند ماز گژھہِ نہٕ بچاونہٕ یُن، مگر ژارنہٕ آمٕژ سٕندِ خٲطرٕ گژھن یِم دۅہ ژھوٚٹ کرنہٕ یِن۔ \n23.\\tتێلہِ یێلہِ کانہہ تہِ انسان ژیہ وَنُن، یێلہِ چُھہ مسیح یا تتہِ۔ یێلہِ کُنہِ تہِ یێلہِ یێلہِ تہِ یێلہِ چُھہ مسیح نتہ \n24. تِکیازِ یێلہِ گژھن اپُز مسیح تہٕ اپُز پیغمبر پٲدٕ سپدن، تہٕ بٔڈۍ نشانہٕ تہٕ عجائبات ہاونہٕ۔ یوتاہ زِ اگر یہ ممکن آسہِ، تِم کرِ ژارنہٕ آمژن دھوکہٕ۔ \n25.\\tوچھ، میہ چھہ ژیہ گۅڈہ وونمُت۔ \n26.\\tتێلہِ اگر تۅہہِ ونن زِ وچھ سُہ چُھہ ریگستانس مَنٛز۔ بێیہِ نہٕ نیرُن: وُچھِو سُہ چُھہ خفیہ خانن مَنٛز۔ پژھ نہٕ کٔرِو نہٕ۔ \n27. یِتھٕ پٲٹھۍ چُھ بجلی مشرقس کُن نیران، تہٕ مغربس کُن تہِ چمکان چُھ۔ یِتھے پٲٹھۍ گژھہِ انسان سُند فرزند سُند یُن تہِ۔ \n28.\\tیَتھ تہِ لاشہٕ آسہِ، تتہِ یِن عقاب جمع کرنہٕ۔ \n29. یِمن دۅہن ہٕندِس مصیبت پَتہٕ ییہِ آفتاب سیاہ تہٕ زونہِ دِیہِ نہٕ گاش تہٕ آسمانہٕ سٍتـ̡ پۯاوٕنـ̡ تہٕ آسمانٕچ طاقتہٕ گژھہِ ہلاونہٕ۔ \n30. تہٕ اَمہِ پَتہٕ گژھہِ اسمانس مَنٛز انسان سٕندِس فرزند سُند نِشانہٕ ظٲہِر، تہٕ پَتہٕ گژھن زمینہٕ کِس سارِنٕے قبیلہٕ ماتم تہٕ تِم وُچھن انسان سُند فرزند آسمانہٕ کِس اُبرَس مَنٛز طاقتہٕ تہٕ بٔڈ شان سان یِوان۔ \n31.\\tتہٕ سُہ سوزِ پَنٕنـ̡ فرشتہٕ سٍتـ̡ بٔڈ آوازٕ سٍتـ̡ تہٕ تِم کٔرِن ژۅشونی ہواو سٍتـ̡ سٍتـ̡ آسمانہٕ کِس اَکہِ اندس پیٹھٕ بییِس اندس تام۔ {سٍتـ̡...: یا بٔڈ آوازٕ سٍتـ̡\n32.\\tوۅنۍ ہیچھِو انجیر کُلِچ اکھ تمثیل۔ ییلہ تمۍ سٕنزِ لنجہِ وُنہِ نرم آسہِ، تہٕ پنہٕ ؤتھٕر کڈِتھ چھِ، ژیہ چھیہ پتاہ زِ ریتہٕ کالہِ چھُ نزدیک: \n33.\\tیتھے پاٹھۍ ییلہ تم یم سٲری چیز وچھو، یہ زان زِ یہ چھہ نزدیک، {حتی} دروازس پیٹھ۔ {یہ: یا، وہ}\n34.\\tبہٕ چُھس ژےٚ ونان زِ یِم سارِنٕے چیز پوٗرٕ گژھن توٚت تام گژھِ نہٕ یہِ نسل ژٔلِتھ۔ \n35.\\tاسمانس تہٕ زمینہِ گژھہِ ژٔلِتھ مگر میٲنۍ کلام گژھہِ نہٕ ژٔلِتھ۔ \n36.\\tمگر تمہِ دۅہہٕ تہٕ ساعتُک چُھہ نہ انسانس زانان، نہٕ اسمانٕکۍ فرشتن سٍتـ̡ بێیہِ سٍتـ̡ صرف میون باپ۔ \n37.\\tمگر یِتھے پٲٹھـ̡ نوے سُند دۅہ آسہِ، تِتھے پٲٹھـ̡ گژھہِ انسان سُند فرزند سُند یُن تہِ۔ \n38. یِتھ کٔنۍ زَن یِمن دۅہن سٔہلاب برونہہ اوس تِم کھٮ۪وان چیوان ، خاندر کران تہٕ خاندر کٔرِتھ، توٚت تام ییمہِ دۅہہ نوے صندوقس منز اژان اوس، \n39.\\tتہٕ اوسُس نہٕ پتاہ یوٚت تام سٔہلاب آو تہٕ تِم سارِنٕے نِش نِنہٕ۔ یِتھے پٲٹھۍ گژھہِ انسان سُند فرزند سُند یُن۔ \n40.\\tتیلہِ گژھن زٕ کھاہس منز۔ اکھ یِن نِنہٕ تہٕ بیٛاکھ یِن نِنہٕ۔ \n41.\\tزٕ زنانہٕ گژھن گِلہِ منز گِلہٕ دِنہٕ۔ اَکھ یِن نِنہٕ تہٕ بیٛاکھ یِن تراوُن۔ \n42.\\tتێلہِ وُچھِو: تێلہِ چُھہ نہٕ پتاہ زِ تُہند رب کُس گھنٹہٕ چُھ یِوان۔ \n43.\\tمگر یہ زان زِ اگر گرِ ہٕندِس نیک آدمس پتاہ آسہِ ہے زِ ژوٗر کمہِ پٲٹھۍ، سُہ آسہِ ہا وُچھان، تہٕ تٔمۍ سُند گرٕ پھُٹراوُن آسہِ نہٕ۔ \n44. تێمہِ کِنۍ تہِ روٗزِو تیار، تِکیازِ یێتھِس وقتس مَنٛز یێلہِ نہٕ تُہۍ یہِ باسان زِ انسان سُند فرزند چُھ یِوان۔ \n45. تیلہِ کُس چُھ وفادار تہٕ عقلمند خادم، یُس تٔمۍ سٕندِس مٲلکَن پننِس گرس پیٹھ حکمران بنوو، یُس تِمن وقتس پیٹھ ماز دِنہٕ خٲطرٕ؟ \n46.\\tسُہ خادم، یُس تٔمۍ سُند آقا یِنہٕ وِزِ یِیہِ وُچھِ۔ \n47. بہٕ چُھس ژےٚ ونان زِ سُہ بناوِ سُہ پنٕنِس سارِنٕے مالس پیٹھ حُکوٗم۔ \n48.\\tمگر اگر سُہ بدکار خادم پننِس دِلس منز وَنُن، میون آقا چُھ تٔمِس یِنس ژیر کران۔ \n49.\\tتہٕ کرِ پننین سٲتھی خدمتگارن مارُن، تہٕ شرابس سٍتـ̡ کھٮ۪نہٕ چِھہ شراب۔ \n50.\\tتٔمِس خادمُک مالک گژھہِ تتھ دۅہس منز یُس نہٕ تس وچھان آسہِ، تہٕ تتھ ساعتس منز یُس نہٕ تس پتاہ آسہِ، \n51.\\tتہٕ ژٔٹِتھ ژٔٹِتھ تہٕ دِیُن منافقن سٍتـ̡ تٔمِس سٍتـ̡ پنُن حصہٕ مُقرر کرنہٕ۔ {ژٹُن...: یا ژٔٹِتھ ژٔٹِھ}","1. تیلہِ ییہِ اسمانٕچ بادشٲہی دَہن کُنوارٮ۪ن سٍتـ̡ ہاونہٕ، یِمو پنٕنۍ شمع تُلِتھ تہٕ مہرازس سمکھنہٕ خٲطرٕ درٛاو۔ \n2. تہٕ یِمو منزٕ پانژھ عقلمند تہٕ پانژھ ٲسۍ بیوقوف۔ \n3. یِمو بیوقوف ٲسۍ تِمو تِمن ہٕندِس شمعس نِش تہٕ نِیوُن نہٕ تیٖل پانس سٍتـ̡ ۔ \n4.\\tمگر دانشمندو روٚٹ پننین بانن منز چراغو سٍتـ̡ تیٖل۔ \n5.\\tییٚلہِ مہرازٕ روٗد، تِم ٲسۍ سٲری شوٚنگتھ تہٕ شوٚنگِتھ۔ \n6. تہٕ نصف رٲژ گٔیہِ کرٛٮ۪کھ دِنہٕ، وُچھِو مہرازٕ آو یِوان۔ تٔمِس مِلنہٕ خٲطرٕ گٔژھِو نیٚبر۔ \n7.\\tتمہِ پتہ گٔیہِ تِم سارِنٕے کُنِرۍ، تہٕ کٔرٕکھ پنٕنۍ شمعہٕ ژٹنہٕ۔ \n8.\\tتہٕ بیوقوفن ووٚن دانشمندن زِ اسہِ دِیو پنُن تیٖل۔ تکیازِ سانہِ چراغ گٔیہِ بٔرۍمٕتۍ۔ {گٔیہِ نٮ۪بر: یا نیبر گٔژھن}\n9.\\tمگر دانشمندن دیُت جواب دِتھ زِ {نہٕ تۅہہ}؛ یِمن ہٕندِ خٲطرٕ گژھِ نہٕ اسہِ تہٕ تۅہہِ خٲطرٕ کٲفی ، بلکہ گژھِو تِمن نِش یِم کٕنَن تہٕ پانس خٲطرٕ ہینہٕ یِوان۔ \n10. تہٕ ییٚلہِ تِم مٔلۍ ہینہِ گٔیہِ، مہرازٕ آو ۔ تہٕ یِم تِم تیار ٲسۍ، گٔیہِ أمِس سٍتۍ خانٛدرَس خٲطرٕ: تہٕ دروازٕ آو بنٛد۔ \n11.\\tامہ پتہ آیہ باقٕے کُنوارِ تہِ، وونُن، خداوند، خداوند، اسہِ خٲطرٕ یلہٕ۔ \n12.\\tمگر تٔمۍ دیُت جواب تہٕ وونُن، پٔزۍ پٲٹھۍ بہٕ چُھس ژےٚ ونان زِ بہٕ چُھس نہٕ ژےٚ زانان۔ \n13. تێلہِ وُچھِو، تێلہِ چُھہ نہٕ پتاہ زِ سُہ دۅہ تہٕ کُس گھنٹہٕ یێلہِ انسان سُند فرزند چُھ یِوان۔ \n14.\\tیِکیازِ {آسمانٕچ بادشٲہی چُھ} یُس أکِس دوٗر مُلکس مَنٛز سفر کران چُھ، {یُس} پَنٕنـ̡ نوکرٕ بُلٲوِتھ تہٕ تِمن دِژُن پنُن سامان۔ \n15.\\tتہٕ أکِس دِژ پانژھ ٹیلنٹ، بییِس زٕ تہٕ بییِس أکِس دِژٕ۔ پرٮ۪تھ أکِس دِژ پننہِ واریاہ صلاحیتہٕ مُطٲبق۔ تہٕ سیوٚد پَنُن سفر۔ {ٹیلنٹس: اکھ ٹیلنٹ چُھ اکھ ہتھ ستٲٹھ پاؤنڈ داہ شلنگ}\n16.\\tتمہِ پَتہٕ یُس پانژھ ٹیلنٹ رٔٹِتھ اوس، سُہ گۆو تِمن سٍتـ̡ تجارت، تہٕ بنووُن باقٕے پانژھ ٹیلنٹ۔ \n17.\\tتہ یتھے پاٹھۍ یُس زٕ رٔٹِتھ اوس، تمِس تہِ کٔرِتھ باقی زٕ تہِ۔ \n18.\\tمگر یُس اکھ روٚٹمُت اوس، سُہ گوٚو زمینہِ مَنٛز کھٔنِتھ تہٕ کٔرٕن پَنٕنِس مٲلکہٕ سٕندِ پٲنسہٕ ژوٗرِ۔ \n19.\\tواریاہس کالس پَتہٕ چُھ یِمن خادمَن ہُند مٲلک یِوان تہٕ تِمن سٍتـ̡ حساب چُھ کران۔ \n20. تہٕ یِتھٕ پٲٹھۍ یُس پانژھ ٹیلنٹ حٲصل اوس کٔرمٕژ تہٕ باقٕے پانژھ ٹیلنٹ أنۍ تہٕ وونُن، خدا، ژے دِژ مےٚ پانژھ ٹیلنٹ دِژمٕتۍ، وُچھ، مے کٔر تمن علاوٕ پانژھ ٹیلنٹ حٲصل۔ \n21.\\tتٔمۍ سٕندِس مٲلکَن ووٚن أمِس، شاباش تہٕ نیک تہٕ وفادار خادم: ژے چھُکھ کینژن چیزن پیٹھ وفادار رودمُت، بہٕ بناوٕ ژے واریاہن چیزن پیٹھ حُکوٗمت۔ \n22.\\tسُہ تہِ آو یُس زٕ ٹیلنٹ میلہِ تہٕ وونُن، خداوند، ژے دِژ میہ زٕ ٹیلنٹ دِژمٕژ، وُچھِو مے یِمو علاوٕ زٕ ٹیلنٹ حٲصل کٔرۍمٕتۍ۔ \n23.\\tتٔمۍ سٕندِس مٲلکَن ووٚن أمِس، شاباش، نیک تہٕ وفادار خادم۔ ژے چھُکھ کینژَن چیزن پیٹھ وفادار روزمُت، بہٕ بناوٕ ژے واریاہن چیزن پیٹھ حُکُمر: پَنٕنِس آقا سٕنزِ خوشی مَنٛز اژُن۔ \n24.\\tیێمہِ سٍتـ̡ یێلہِ اَکھ صلٲحیتـ̡ میلہِ سٍتـ̡ آو تہٕ وونُن، خدایا، بہٕ چُھس ژے زانان زِ ژٕ چُھکھ سخٕت انسان، یێتہِ نہٕ ژے ووومُت چُھ، تہٕ یێتہِ ژے ژے ژٔٹِتھ تہٕ یێلہِ نہٕ ژے ژٔٹِتھ چُھ، تہٕ یێلہِ تہٕ ژے چُھکھ ژے ژٔٹِتھ \n25.\\tتہٕ بہٕ کھوژمُت، تہٕ گٔژھ پنٕنۍ صلاحیت زمینس منز ژوٗرِتھ: لو، تتہِ چُھہ ژے چُھہ تُہُند {یعنی}۔ \n26.\\tتٔمۍ سٕندِس مٲلکَن دِیُت جواب تہٕ وونُن، {ژے} بدکار تہٕ کاہلہٕ خادم، ژے چُھکھ زانان زِ بہٕ چھُس یَتہِ نہٕ ووومُت، تہٕ یَتہِ نہٕ بہٕ ووت تتہِ جمع کٔرِتھ: \n27.\\tتَمہِ کِنۍ پزِ ژے میون پونسہٕ بدلاون والٮ۪ن نِش تھاوُن، تہٕ {پتہٕ} میانہِ یِنہٕ وِزِ ہا مےٚ پنُن سود حٲصِل کٔرِتھ۔ \n28.\\tتێلہِ نِش ٹیلنٹ نِن، تہٕ دِیُن أمِس دَہ ٹیلنٹ آسہِ۔ \n29.\\tیُس پریتھ کٲنسہِ دِنہٕ یُس دِنہٕ یِیہ، تہٕ أمِس آسہِ فراوانی حٲصِل کرنہٕ، مگر یُس نہٕ أمِس نِش یُس تہِ نِنہٕ یُس أمِس نِش آسہِ۔ \n30.\\tتہٕ بێکار خادم تراوُن نیبرِمِس اندِپِس مَنٛز: اَتہِ گژھہِ وَنُن تہٕ دندٕ گٔژھہِ۔ \n31. یێلہِ انسان سُند فرزند پننِس جلال سٍتـ̡ تہٕ سٲری مقدس فرشتہٕ أمِس سٍتـ̡ یِنہٕ، تیلہِ بِہِہ سُہ پنہٕ نِس جلال کِس تختس پیٹھ: \n32.\\tتہٕ أمِس برونہہ کُن یِن سارِنٕے قومن جمع کرنہٕ، تہٕ سُہ کرِ یِم اکھ أکِس نِش الگ کٔرِتھ، یِتھٕ پٲٹھۍ چُھہ پَنٕنـ̡ پَنٕنـ̡ دانٛد ژھاوٕنـ̡ نِش الگ کٔرِتھ: \n33.\\tتہٕ سُہ تھاوُن دانٛد دچھنہِ اتھس پیٹھ، مگر ژھاوٕل کھوورِ طرفہٕ۔ \n34. تیلہٕ کرِ بادشاہ تِمن دچھنہِ اتھہٕ سٍتـ̡ وَنُن، یێلہِ یێلہِ میانہِ مٲلہِ سٕندِ بابرکت سٍتـ̡ رٔٹِتھ رٔٹِتھ دُنیاہٕچ بُنیاد پۯاونہٕ آمٕژ بادشٲہی ہٕندِس وٲرثس سٍتـ̡ ۔ \n35.\\tبہٕ اوسُس فاقہٕ تہٕ ژے دِژٕ ماز دِژمُت، بہٕ اوسُس اَکھ اجنبی تہٕ ژے دِژٕ مے اَن: \n36.\\tننگہٕ تہٕ ژے لٔگِتھ پَلو: بہٕ اوسُس بٮ۪مار، تہٕ ژے گٔے میہ نِش۔ \n37.\\tتیلہِ دِیہِ نیک أمِس جواب دِتھ زِ خداوند، ییلہ أسۍ ژے ہُند فاقہٕ وُچھمُت، تہٕ ژے دِژُکھ کھٮ۪وُن؟ یا پیاس تہٕ دِژُکھ ژے شراب؟ \n38.\\tییلہ أسۍ ژے اکھ اجنبی وُچھمُت، تہٕ ژے رٔٹِتھ رٔٹِتھ؟ یا ننگہٕ تہٕ پلو لٲگِتھ {ژے}؟ \n39. یا ییلہ أسۍ ژے بیمار یا جیلس منز وُچھمٕتۍ، تہٕ ژے نِش آو؟ \n40. تہٕ بادشاہ دِیہِ جواب تہٕ تِمن وَنُن، یێلہِ چُھہ ژےٚ وَنُن، یێلہِ ژے میانین بٲے منزٕ أکِس سٍتـ̡ کٔرِتھ چُھ، تێہہ چُھہ میانہِ سٍتـ̡ کورمُت۔ \n41. تیلہِ گژھہِ سُہ تِمن کھوورِ طرفہٕ تہِ ونُن، یێلہِ ژٔلِتھ ژٔلِو، یێلہِ شیطان تہٕ تٔمۍ سٕندِس فرشتن ہٕندِ خٲطرٕ تیار کرنہٕ آمٕژ چھےٚ۔ \n42. کیازِ بہٕ اوسُس فاقہٕ تہٕ ژے دِژ نہٕ ماز تہٕ ژے دِژ نہٕ میہ کانہہ ماز تہٕ ژے دِژ نہٕ میہ کانہہ شراب۔ \n43.\\tبہٕ اوسُس اَکھ اجنبی تہٕ ژے اوسُس نہٕ میہ انٛدرٕ کٔرِتھ، تہٕ ژے کٔر نہٕ میہ نِش نِش۔ \n44.\\tتیلہِ کیا تِم تہِ جواب دِتھ ونان زِ خداوند، ییلہ أسۍ ژے ہُند لوٚکُن، یا ترش، یا اجنبی شخص، یا ننگہ، یا بیمار، یا جیلس مَنٛز، تہٕ کیا چُھہ نہٕ تۅہہِ خدمت کٔرمٕژ؟ \n45.\\tتیلہِ کرِ سُہ تِمن جواب دِتھ ونان زِ بہٕ چُھس ژے ونان، یوتاہ ژے یِمو منزٕ أکِس تہِ سٍتـ̡ کٔرِتھ تہٕ کٔرِو نہٕ میہ سٍتـ̡ ۔ \n46.\\tتہٕ یِم گژھن ابدی عذابس مَنٛز، مگر صالحین ہٕندِس دٲیرٕ سٍتـ̡ زندٕگی مَنٛز۔","1. تہٕ سپد یێلہِ عیسیٰ مسیح یِم سٲری کلام مُکمل کٔرۍ، تٔمۍ ووٚن پننین شاگردن ، \n2. تۅہہ چھے پتاہ زِ دۅن دۅہن پَتہٕ چُھ فسح تہٕ انسان سُند فرزند چُھ دِنہٕ آمُت۔ \n3.\\tاَمہِ پَتہٕ جمع کٔرِتھ بٔڈۍ پادٕرۍ تہٕ کاتب تہٕ لُکن ہٕندِس بُزرگ سٕندِس محلس مَنٛز، یٔمِس کایافاس وَننہٕ اوس یِوان، \n4. تہٕ مشورٕ کٔرِتھ زِ تِم گژھن عیسیٰ علیہ السلام نِش تہٕ مارٕنـ̡ ۔ \n5.\\tمگر تِمو ووٚن زِ عید دۅہہٕ گژھہِ نہٕ لُکن منز ہنگامہٕ۔ \n6. وُنہِ ییلہ عیسیٰ مسیح بیتھنیاہس مَنٛز، شمعون کوڑھ سٕندِس گرس مَنٛز، \n7.\\tأمِس نِش آیہِ اَکھ زنانہٕ یٔمِس سٮ۪ٹھاہ قۭمتی مرہم ہُند اکھ الابسٹر ڈبہٕ، تہٕ ترووُن أمِس کلَس پیٹھ، ییٚلہِ سُہ بِہتھ {ماز}۔ \n8.\\tمگر ییلہ تٔمۍ سٕندٮ۪و شاگردو وُچھ، تِمو ہیوٚت شرارت تہٕ وونُن، یہِ فضول کتھ کُنہِ مۅکھہٕ چُھہ؟ \n9.\\tامہ مۅکھہ آسہِ یہ مرہم واریاہ کٕننہٕ آمُت تہٕ غریبن دِنہٕ آمُت۔ \n10.\\tییلہ حضرت عیسیٰ علیہ السلام سمجھ آو، تٔمۍ ووٚن تِمن زِ زنانہِ کیازِ چھِو پریشان کران؟ تکیازِ تٔمۍ کٔر میہ سٍتـ̡ رژھ۔ \n11.\\tتِکیازِ چُھہ غریبَن ہمیشہٕ پانس سٍتـ̡ آسان۔ مگر میہ چُھہ نہٕ ہمیشہٕ۔ \n12.\\tتکیازِ یێمہِ سٍتـ̡ چُھہ یہ مرہم میٲنس جسمس پیٹھ تروومُت، تٔمۍ کٔر میانہِ دفنٕ خٲطرٕ۔ \n13. یێلہِ بہٕ چُھس ژےٚ ونان زِ یێتہِ یێلہِ تہِ یہِ انجیل پوٗرٕ دُنیاہس مَنٛز پراونہٕ ییہِ، تتہِ گژھہِ یہِ تہِ یُس أمِس زنانہِ ہٕندِس یادگارس مۅکھٕ وننہٕ ییہِ۔ \n14. پتہٕ گۆو بہو منزٕ اکھ، یُس یہوداہ اسکریوٹ ونان چُھ، گۆو سردار پادٕرین نِش، \n15. تہٕ ووٚنُن تِمَن، ژٕ کیا دِیہٕ مے تہٕ بہٕ دِیہٕ سُہ ژےٚ حوالہٕ۔ تہٕ تِمو کوٚر أمِس سٍتـ̡ ترہن رۄپہٕ ہُند معاہدٕ۔ \n16. تہٕ تمہ وقتہٕ پیٹھٕ ژھانڈ أمس دھوکہ دِنُک موقعہٕ۔ \n17.\\tوۅنۍ گۅڈنچہ لٹہِ حضرت عیسیٰ ہس نِش وٲتِتھ وونُن زِ ژے کتہِ چُھہ ژے فسح کھٮ۪نہٕ خٲطرٕ تیار کٔرِتھ؟ \n18.\\tتہٕ تٔمۍ ووٚن، یِتھِس شخٕصس نِش گژھ شہرس مَنٛز، تہٕ أمِس وَنُن، آقا چُھ ونان زِ میون وقت چُھ اتھس پیٹھ۔ بہٕ تھاوٕ پننین شاگردن سٍتـ̡ چانہِ گَرِ سٍتـ̡ فسح ۔ \n19. تہٕ شاگردو کٔر عیسیٰ مسیحن مقرر کرنہٕ آمُت۔ تہٕ تِمو کٔر فسح تیار۔ \n20.\\tوۅنۍ ییلہ تہِ آو تہ بیوٹھ سُہ بہن سٍتـ̡ ۔ \n21.\\tتہٕ یێلہِ تِمو کھٮ۪وان اوس، تٔمۍ ووٚن، یێلہِ بہٕ چُھس ژے ونان زِ ژے منزٕ کرِ اکھ دُکھہٕ۔ \n22.\\tتہٕ تِمو گٔیہِ سٮ۪ٹھاہ غمگسار تہٕ ہیوٚتُکھ پرٮ۪تھ أکِس أمِس وَنُن، خداوند، کیا بہٕ چھُس؟ \n23.\\tتہٕ تٔمۍ دیُت جواب تہٕ وونُن، یُس میٲنِس سٍتـ̡ ڈِشس مَنٛز اَتھٕ دِوان چُھ، سُہ کرِ مے دھوکہٕ۔ \n24.\\tانسان سُند فرزند چُھ یُتھ زن أمِس متعلق لیکھنہٕ آمُت چُھ، مگر تٔمِس انسانس ہٕندِ خٲطرٕ افسوس، یٔمِس سٍتـ̡ انسان سُند فرزند دھوکہ دِنہٕ چُھ! تٔمِس انسانس خٲطرٕ اوس اصل اگر نہٕ سُہ زامُت آسہِ۔ \n25.\\tپتہٕ دِژ یہوداہ، یٔمۍ أمِس دھوکھہٕ دِژ، دِیُت جواب تہٕ وونُن، آقا، کیا بہٕ چھُس؟ تٔمۍ ووٚن أمِس ووٚنمُت۔ \n26.\\tتہٕ یێلہِ تِم کھٮ۪وان ٲسۍ، حضرت عیسیٰ علیہ السلام نِش روٹی تہٕ دِژُن برکت، تہٕ دِژُن شاگردن تہٕ وونُن، نِیُن، کھیوٚن۔ یہِ چُھ میٲنۍ جسم۔ {بابرکت کٔرِتھ: واریاہ یونانۍ نسخو چُھ شُکریہ ادا کٔرِتھ}\n27.\\tتہٕ تٔمۍ رٔٹِتھ پیالہ تہٕ شُکریہ ادا کٔرِتھ دِتُن تِمن یہ سورُے پیو۔ \n28. یێمہِ سٍتـ̡ چُھہ میٲنۍ نۆو عہد نامُک خون، یُس واریاہن ہٕندِ خٲطرٕ گۅنہٕ ہٕنزِ معافی خٲطرٕ تراونہٕ یوان چُھ۔ \n29. مگر بہٕ چُھس ژے ونان زِ بہٕ چُھس نہٕ امہِ دۅہہٕ سٍتـ̡ یێلہِ بہٕ ژے سٍتـ̡ پننِس مٲلہِ سٕندِس بادشاہتس مَنٛز نوو چیٚنہٕ۔ \n30.\\tتہٕ ییلہ تِمو اکھ حمد گٮ۪و، تِم گٔیہِ زیتون کِس پہاڑس مَنٛز۔ {حمد: یا، زبور}\n31.\\tتێلہِ چُھ عیسیٰ مسیح تِمن ونان زِ یێمہِ رٲژ میانہِ مۅکھہٕ گژھہِ سارِنٕے ناراض تہٕ یێلہِ چُھہ لیکھنہٕ آمُت زِ بہٕ کٔرٕ چرواہِ سٕندِس دٲیرٕ سٍتـ̡ تہٕ کۅکرِ ہٕندِس کۅکرِ ہٕندِس کُنہِ رٲژ ہٕندِس سٍتـ̡ بێیہِ پٲٹھـ̡ پۯاونہٕ آمُت۔ \n32. مگر ییلہ بہٕ دُبارٕ زندٕ سپدِ، بہٕ گژھہٕ ژے برونہہ کُن گلیل مَنٛز۔ \n33.\\tپطرس دیُت جواب تہٕ وونُن تٔمِس زِ یێلہِ سارِنٕے لُکن ہٕندِ وجہ سٍتـ̡ گٔیہِ تۅہہِ سٍتـ̡ ناراض، {توتہِ} گژھہِ نہٕ بہٕ زانہہ ناراض۔ {ناراض: یا یێلہِ بێین انسانن ہُند ایمان گژھہِ ہلاونہٕ یُن تہٕ ناکام گژھُن، توتہِ روزِ میون پٲٹھـ̡ تہٕ ثابت روزُن}\n34.\\tحضرت عیسیٰ علیہ السلام ووٚن تٔمِس زِ بہٕ چُھس ژے وَنُن زِ از رٲژ کۅکُر کۅکرِ برونہہ کُن ژے کٔرِو میہ تریہ لٹہِ انکار۔ \n35. پطرس ووٚن أمِس زِ یێلہِ بہٕ ژے سٍتـ̡ مَرُن، توتہِ بہٕ کَرٕ نہٕ ژےٚ نِش انکار۔ یِتھے پٲٹھۍ ووٚن سارِنٕے شٲگِرِیو تہِ۔ \n36.\\tتێلہِ چُھ عیسیٰ مسیح پانس سٍتـ̡ گیتسمانی ناوٕ جایہِ یِوان، تہٕ چُھہ شاگردن ونان، یێلہِ بہٕ گژھِو یێلہِ تہٕ یێلہِ بێیہِ دُعا کرنہٕ۔ \n37.\\tتہٕ تٔمۍ نِیہِ پطرس تہٕ زبدی سٕندِ زٕ نیچوۍ پانس سٍتۍ، تہٕ ہیوٚتُن غمگسار تہٕ سٮ۪ٹھاہ گۄب۔ \n38.\\tتہٕ سُہ ووت رژھ کھنڈ برونہہ تہٕ پیوٚو بُتھِس پیٹھ، تہٕ دُعا کٔرِتھ وونُن، اے بابا، اگر یہ ممکن آسہِ، تیلہِ گژھہِ یہ پیالہ میانہِ نِش نیرُن، بہرحال بہٕ چُھس نہٕ یُتھ بہٕ یژھان چھُ، بلکہ ژے یِتھٕ پٲٹھۍ۔ \n39. تہٕ سُہ چُھ شٲگِرَن نِش یِوان، تہٕ چُھہ تِم شوٚنگِتھ وُچھان تہٕ پطرس ونان زِ کیا چُھہ نہٕ میہ سٍتـ̡ أکِس گھنٹس سٍتـ̡ وُچھِتھ؟ \n40. وُچھِو تہٕ دُعا کٔرِو، یێلہِ نہٕ تُہۍ فتنس مَنٛز دٲخل گٔژھِو: روح چُھ پٔزۍ پٲٹھـ̡ رضامند، مگر ماز {چُھ} کمزور۔ \n41.\\tسُہ گۆو دوٚیمہِ لٹہِ دُبارٕ تہٕ دُعا دُعا کٔرِتھ وونُن، اے بابا، اگر یہ پیالہ میہ نِش نیرِ، یوٚت تام بہٕ یہ چیٚنہٕ تیلہِ گژھہِ تۅہہ چانہِ مرضی پورٕ۔ \n42.\\tتہٕ سُہ آو تہٕ وُچھ تِم بییہ شوٚنگِتھ، تکیازِ تِمن ہٕنزِ أچھ ٲس گٔبۍ۔ \n43.\\tتہٕ سُہ ترٲوِتھ دُبارٕ دُعا کٔرِتھ دُعا کٔرِتھ۔ \n44. پَتہٕ چُھ سُہ پَنٕنٮ۪ن شٲگِرَن نِش یِوان تہٕ تِمن وَنُن چُھ، وُچھِو وُنُن وُن، تہٕ اِنسان سُند فرزند چُھ گۅنہگارن ہٕندِس اتھس مَنٛز دھوکہٕ دِنہٕ آمُت۔ \n45.\\tوۅتھ، اسہِ گژھہِ گژھُن: وچھ سُہ چُھ اتھس منز یُس میہ دھوکہ دِوان چھُ۔ \n46. تہٕ ییلہ سُہ وُنہِ تہِ کتھ کٔرِتھ، لو، یہوداہ، بہو منزٕ اکھ، آو تہٕ أمِس سٍتـ̡ لُکن ہٕندِس بٔڈِس پادٕرین تہٕ بزرگن ہٕندِ طرفہٕ تلوار تہٕ لٔٹہِ ہٮ۪تھ اکھ بٔڈ بٔڈِ۔ \n47.\\tوۅنۍ یمۍ أمس دھوکہ دِژ تمن اکھ اشارہ، یہ ونُن زِ یُس بہٕ بوسہ دِیہ، سُہ چُھس سُہ رٔٹتھ تھپھ کٔرِتھ۔ \n48.\\tتہٕ سُہ آو عیسیٰ مسیحس نِش تہٕ وونُن، سلام، مالک۔ تہٕ کوٚرُن أمِس بوس۔ \n49.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن أمِس یار، تہٕ ژٕ کیازِ چُھکھ آمُت؟ پَتہٕ آیہ تِمو عیسیٰ ہس پیٹھ اتھہٕ تہٕ نیُن سُہ ۔ \n50.\\tتہٕ وُچھ، یُس عیسیٰ مسیحس سٍتـ̡ اوس، تٔمۍ کٔر اَتھٕ پٔھٹِتھ تہٕ کٔرٕن بڈِ پادٕرۍ سٕندِس أکِس خادمس لٔگِتھ تہٕ لٔگِن تٔمِس کَن۔ \n51. اَمہِ پتہٕ ووٚن عیسیٰ علیہ السلام تٔمِس پَنٕنہِ تلوار دُبارٕ تٔمِس جایہِ تھپھ کٔرِتھ، تِکیازِ یِم سٲری تلوار رٔٹِتھ گژھن تلوار سٍتـ̡ ختم گٔیہِ۔ \n52.\\tژیہ چھا سوچان زِ بہٕ ہیوٚک نہ وۅنۍ پننِس مٲلس دُعا کٔرِتھ، تہٕ سُہ دِیہ میہ بہہ کھوتہ زیادٕ فرشتن ہٕندِس لشکرس منز؟ \n53.\\tمگر تیلہِ کِتھہ پٲٹھـ̡ گژھہِ صحیفہٕ پورٕ، یُتھ گژھہِ یِتھٕ پٲٹھـ̡ سپدُن؟ \n54. اَمہ ساعتہ ووٚن حضرت عیسیٰ علیہ السلامن ہٕندِس لٔگِس لٔگِتھ ژوٗر سٍتـ̡ تہٕ لُٹہٕ ہیتھ نیبر نیران۔ بہٕ اوسُس دۅہہٕ ژے سٍتـ̡ مندرس مَنٛز پرناوان تہٕ تہٕ ژے کٔر نہٕ میہ تھپھ۔ \n55.\\tمگر یہ سورُے سپُد یُتھ پیغمبرن ہٕنزِ صحیفہٕ پورٕ سپدِ۔ تمہِ پَتہٕ گٔیہِ سارِوٕے شٲگِرِ أمِس ترٲوِتھ ژٔلِتھ ژٔلِتھ۔ \n56.\\tتہٕ یِمو عیسیٰ ہس تھپھ کٔرِتھ تھپھ کٔرِتھ گٔیہِ تٔمِس کِفافس نِش، یَتہِ کاتب تہٕ بزرگ جمع گٔیہِ۔ \n57.\\tمگر پطرس ووت أمِس پَتہٕ بٔڈِس پادٕرۍ سٕندِس محلس تام، تہٕ ووت انٛدر تہٕ بیوٹھ نوکرَن سٍتـ̡ انجام وُچھنہٕ خٲطرٕ۔ \n58.\\tوۅنۍ کٔر بٔڈۍ پادٕرۍ، بزرگو تہٕ سارِنٕے مجلسو عیسیٰ ہس خلاف اپُز گوٲہی دِنہٕ خٲطرٕ، یُس سُہ مارنہٕ خٲطرٕ منگ۔ \n59.\\tمگر لوٚب نہٕ کانہہ تہِ: آ، اگرچہ واریاہ اپُز گواہ آیہ، {توتہِ} لٔب نہٕ تِم کانہہ تہِ۔ ٲخرس پیٹھ آیہ زٕ اپُز گواہ \n60.\\tتہٕ وونُن، أمِس {نفر} ووٚن، بہٕ ہیوٚک خدایہ سُند مندر تباہ کٔرِتھ، تہٕ یہ ترٮ۪ن دۅہن منز تعمیر کرُن۔ \n61.\\tتہٕ بٔڈۍ پادٕرۍ ووٚتھ تہٕ ووٚنُن تٔمِس کُنہِ تہِ جواب دِنہٕ؟ یِم گواہ کیا چھِ؟ \n62.\\tمگر حضرت عیسیٰ علیہ السلام رٔٹِتھ پَنُن خاموش۔ تہٕ اعلیٰ پادٕرین دِیُت جواب تہٕ وونُن زِ بہٕ چُھس زندٕ خدایہِ سٕندِ سٍتـ̡ ژے وَنُن زِ ژٕ چُھکھ خدایہِ سُند نیٚچُو۔ \n63. عیسیٰ مسیح چُھ أمِس ونان زِ توے چُھہ وَنُن: بہٕ چُھس ژے وَنُن زِ یێلہِ پَتہٕ وُچھِو اِنسان سُند نیٚچُو، یُس طاقتہٕ کِس دٔچھنِس اتھس پیٹھ بِہِتھ تہٕ آسمانہٕ کِس اُبرس مَنٛز یِوان چُھ۔ \n64.\\tاَمہِ پَتہٕ دِژ بٔڈۍ پادٕرین پَنٕنـ̡ پٲٹھ \n65.\\tتۅہہ کیا خیال چُھہ؟ تِمو دِژ جواب تہٕ وونُن زِ سُہ چُھ موتُک قصوروار۔ \n66.\\tپتہٕ دِژ تِمو أمِس بُتھِس پیٹھ تھوک، تہٕ لٔگۍ أمِس بُتھِس پیٹھ۔ تہٕ باقیو لٔگۍ أمِس اتھو سٍتۍ، {اتھہٕ...: یا لٔرۍ}\n67.\\tیہ ونِتھ زِ اسہِ نِش پیشن گویی کرٕن، اے مسیح، سُہ کُس چُھ یُس ژے مارُن دِژمُت؟ \n68.\\tوُن پطرس بِہتھ محلس منز، تہٕ اَکھ لڑکی آیہِ أمِس نِش، وَنُن زِ تہٕ تہٕ اوسُکھ گلیل کِس عیسیٰ سٕندِس سٍتـ̡ ۔ \n69.\\tمگر تٔمۍ کٔر سارِنٕے برونہہ کُن انکار تہٕ وونُن زِ بہٕ چُھس نہٕ پتاہ ژےٚ کیا ونان چھِ۔ \n70.\\tتہٕ ییلہ سُہ دٲرس منز نیرِ، بییِس {نونہِ} وُچھ أمِس تہٕ وونُن تِمن یُس تتہِ اوس، یہِ {نفر} تہِ اوس عیسیٰ مسیحس سٍتـ̡ ۔ \n71. تہٕ بییہِ کٔر تٔمۍ حلف کٔرِتھ انکار، بہٕ چُھس نہٕ أمِس نفرس زانان۔ \n72. تہٕ کینژَس کالس پَتہٕ وٲتِتھ یِم یِمو نِش کھڑا ٲسِتھ، تہٕ وونُن پطرس، یٔقیٖنی طور تہٕ چُھکھ تِمو منزٕ اکھ۔ تِکیازِ تُہٕندِس کلامَس سٍتـ̡ چُھہ تۅہہِ سٍتـ̡ پى۪ٹھـ̡ \n73.\\tامہ پتہ لوٚگ أمس بد دعا تہٕ قسم، {ونن}، بہٕ چھُس نہٕ أمس نفرس پتہ۔ تہٕ یکدم کۅکر عملہٕ۔ \n74. تہٕ پطرس اوس عیسیٰ سُند کلام یاد، یُس أمِس وَننہٕ آمُت اوس زِ کۅکُر کۅکرِ برونہہ کُن کٔرِکھ میہ تریہ لٹہِ انکار۔ تہٕ سُہ درٛاو نیٚبر، تہٕ ووٚن سٮ۪ٹھاہ روُن۔","1. ییلہ صُبح ووت، سارِوٕے بٔڈۍ پادٕرۍ تہٕ بزرگو کٔر عیسیٰ ہس سٍتـ̡ مارنہٕ خٲطرٕ مشورٕ: \n2. تہٕ ییلہ تمو أمس پابند کٔر، تمو نِش نِتھ تہٕ کوٚرُن پونٹیئس پیلاطس گورنرس نِش۔ \n3. پَتہٕ یہوداہ، یٔمۍ أمِس دھوکھہٕ دِژمُت، ییٚلہِ تٔمِس مذمت کرنہٕ آمٕژ ٲس، توبہ کٔرِن تہٕ أنِن ترٕہ رۄپہٕ رۄپہٕ دُبارٕ پادٕرین تہٕ بزرگن نِش۔ \n4.\\tیہ ونِتھ زِ میہ چھہ معصوم خونس دھوکہ دِژمُت۔ تہٕ تِمو ووٚن، اسہِ کیا چُھہ یہِ؟ وُچھِو ژے {تَتھ کُن}۔ \n5.\\tتہٕ تٔمۍ ترٛٲوۍ مندرس مَنٛز رۄپہٕ ٹُکرٕ تہٕ درٛاو تہٕ گٔیہِ پھٲنسی دِنہٕ۔ \n6.\\tتہٕ بٔڈۍ پادٕرین رٔٹۍ رۄپہٕ ٹُکرٕ تہٕ وونُن، یِم خزانس مَنٛز تراوُن چُھنہٕ جٲیز، تِکیازِ یہِ چُھ خونُک قٕمتھ ۔ \n7.\\tتہٕ تِمو ہیوٚت مشورٕ تہٕ ہیوٚتُکھ پانس سٍتۍ کمہارن ہُند کھیت یُس اَتھ منز غٲر ملکی دفن کرنہٕ مۅکھہٕ۔ \n8. اَمہِ مۄکھٕ چُھ اَتھ کھہَس از تام خونُک مٲدان وننہٕ آمُت۔ \n9.\\tتێلہِ سپُد سُہ پورٕ یُس یرمی رسولن وونُن اوس تہٕ تِمو رۄپہٕ رۄپہٕ رۅپہٕ رٔٹِتھ یُس قٲمتھ اوس، یُس تِمو بنی اسرٲیلِیو ہُند مۅل اوس۔ {کُس...: یا، یُس تِمو بنی اسرٲیلِس نِش ہیوٚت}\n10. تہٕ دِژن تم کمہار سٕندِ کھہٕ خٲطرٕ، یِتھ کٔنۍ خداوند میہ مقرر کوٚر۔ \n11.\\tتہٕ حضرت عیسیٰ علیہ السلام ووٚن گورنرس برونہہ کُن، تہٕ گورنرن پرژھ أمِس زِ کیا تُہۍ چھوا یہودین ہُند بادشاہ؟ تہٕ حضرت عیسیٰ علیہ السلام ووٚن تٔمِس وَنُن۔ \n12.\\tتہٕ ییلہ أمِس بٔڈۍ پادٕرین تہٕ بزرگن ہُند الزام آو دِنہٕ، تٔمِس دِژ نہٕ کانٛہہ تہِ جواب۔ \n13.\\tتێلہِ ووٚن پیلاطس أمِس زِ ژے چُھہ نہٕ بوزان زِ تِم کٲژاہ کتھہٕ چھِ تۅہہِ خلاف گواہی دِوان۔ \n14.\\tتہٕ تٔمۍ دِیُت أمِس زانہہ تہِ کُنہِ لفظُک جواب۔ یوٗت تام زِ گورنرن گوٚو سٮ۪ٹھاہ حٲران۔ \n15.\\tوۅنۍ اوس گورنرن لوکن خٲطرٕ اکھ قٲد یلہٕ تراوان، یُس تم کرِ۔ \n16.\\tتہٕ تِمن اوس تمہ وقتہٕ اکھ قٲبلِ ذِکر قٲد، یٔمِس باراباس ناو اوس۔ \n17.\\tتێلہِ ییلہ تِم جمع گٔیہِ، پیلاطس ووٚن تِمن کُس یُس بہٕ ژے یلہٕ تراوُن؟ باراباس، یا عیسیٰ یس مسیح ونان چھہِ؟ \n18.\\tتکیازِ تس ٲس پتاہ زِ حسد کِنۍ اوس تمو أمس دِژمُت۔ \n19.\\tییلہ سُہ فیصلہٕ کِس مقامس پیٹھ بِہاونہٕ آو، تٔمۍ سٕنزِ خانٛدارِنہِ سوز أمِس نِش زِ ژے چھُنہٕ أمِس عادل شخصس سٍتـ̡ کانہہ واٹھ تھاوان، تکیازِ میہ چُھہ از دۅہہ خوابس مَنٛز واریاہ چیز تٔمِس سٍتـ̡ دِژمُت۔ \n20.\\tمگر بٔڈۍ پادٕرۍ تہٕ بزرگو کٔر بٔڈِس ہجومَس رٲضی زِ تِم گژھن باراباسس پرژھنہٕ تہٕ عیسیٰ سُند تباہ کرُن۔ \n21.\\tگورنرن دیُت جواب تہٕ وونُن تِمَن، کیا تُہۍ چھِو دۅشوٕے منزٕ یلہٕ تراوُن؟ تِمو ووٚن باراباس۔ \n22. پیلاطس چُھ تِمن ونان زِ تیلہِ کیا کرٕ بہٕ عیسیٰ مسیحس سٍتـ̡ یُس مسیح ونان چُھ؟ {تِم سارِوٕے چُھہ أمِس ونان زِ سُہ گژھہِ صلیب دِنہٕ۔ \n23.\\tتہٕ گورنرن ووٚن، کیازِ، أمِس کیا بُرکار کورمُت؟ مگر تِمو دِژ زیادٕ کرٛٮ۪کھ دِتھ زِ سُہ گژھہِ صلیب دِنہٕ۔ \n24.\\tییلہ پیلاطس وُچھ زِ سُہ ہیوٚک نہٕ کانہہ تہِ غالب سپدِتھ، مگر {یہ} ہنگامہ سپُد، تٔمۍ روٚٹ آب تہٕ لوگُن ہجومس برونہہ کُن اتھہٕ چھلِتھ وونُن، بہٕ چُھس أمِس عادل شخصہٕ سٕندِس خونس سٍتـ̡ بے قصور: وُچھو تہٕ وُچھو۔ \n25.\\tاَمہِ پتہٕ دِیُت سارِنٕے لُکن جواب تہٕ وونُن تٔمۍ سُند خون اسہِ تہٕ سانٮ۪ن شُرین پیٹھ۔ \n26.\\tتمہِ پتہ ترووُن تِمن نِش بارباس یلہٕ، تہٕ ییلہ تٔمۍ عیسیٰ مسیحس تھپھ دِژ، تٔمۍ دِژ تمِس صلیب دِنہٕ خٲطرٕ۔ \n27. اَمہِ پَتہٕ نِیوو گورنر سٕندِ سپاہ عیسیٰ سٕندِس کامن ہالس مَنٛز، تہٕ کٔرٕکھ أمِس سٍتـ̡\n28.\\tتہٕ تِمو کٔر أمِس کُنہِ \n29.\\tتہٕ ییلہ تِمو کانٹَن ہُند تاج لوٚگ، تِمو تھووُن أمِس کَلس پیٹھ، تہٕ تٔمِس دٔچھنِس اتھس مَنٛز اکھ نٔل، تہٕ تِمو کٔرٕکھ أمِس برونہہ کُن کۅٹھہٕ تہٕ تٔمِس ٹھٹھہٕ کٔرِتھ وونُن، ہاے یہودین ہُند بادشاہ! \n30.\\tتہٕ تِمو تھوکھ أمِس پیٹھ تھوک، تہٕ رٔٹِکھ نٔر تہٕ لٔگِتھ أمِس کلَس پیٹھ۔ \n31.\\tتہٕ تمہِ پتہ کٔر تمِس ٹھٹھہٕ کٔرِتھ، تِمو لوٚگ أمِس نِش پوشہٕ، تہٕ لوٚگُکھ أمِس پَنُن پَلَو، تہٕ نِیُکھ أمِس صلیب دِنہٕ خٲطرٕ۔ \n32.\\tتہٕ ییلہ تِم نیبر درایہ، تِمو وُچھ سائرین سُند اکھ شخٕص یُس شمعون ناو اوس، أمِس کٔر تٔمۍ سُند صلیب تُلنس پیٹھ مجبور۔ \n33.\\tتہٕ ییلہ تِم گولگوتھا نٲوۍ أکِس جایہِ وٲتِتھ، یعنی کلہٕ کھورِ ہٕنز جاے، \n34.\\tتِمو دِژ أمِس گال سٍتۍ رٔلِتھ چنہٕ خٲطرٕ سرکہٕ، تہٕ ییلہ أمِس چُھس چُھ، سُہ چُھ نہٕ چیٚوان۔ \n35.\\tتہٕ تِمو کٔرِکھ أمِس مصلوب تہٕ کٔرِکھ تٔمِس پلو پھٔٹِتھ تہٕ کٔرِکھ قرعہٕ، یُس رسول اللہ علیہ وآلہ وسلم سٕندِ طرفہٕ وَننہٕ آمُت اوس، تِمو کٔرِکھ میٲنۍ پلو تِمن مَنٛز تقسیٖم۔ \n36.\\tتہٕ بِہتھ وُچھان تِمو تتہِ وُچھان۔ \n37.\\tتہٕ کٔرِن پننِس کلس پیٹھ لیٚکھِتھ پنُن الزام لیٚکھِتھ، یہِ چُھ عیسیٰ مسیح یہودین ہُند بادشاہ۔ \n38.\\tاَمہ پتہٕ آیہ أمِس سٍتـ̡ زٕ چور صلیب دِنہٕ، اکھ دچھنہِ طرفہٕ تہٕ بیاکھ کھوورِ طرفہٕ۔ \n39.\\tتہٕ یِمو کٔر أمِس کلہٕ ہلٲوِتھ طعنہ دِتھ، \n40. تہٕ وَنُن، یُس مندر تباہ کٔرِتھ تہٕ ترٮ۪ن دۅہن مَنٛز تعمیر کٔرِو، پَنُن پان بچٲوِو۔ یێلہِ ژٕ خدایہِ سُند نیٚچُو چھُو، صلیب پیٹھٕ ؤسِو بۄن۔ \n41.\\tیتھے پاٹھۍ ٲسۍ بڈۍ پادٕرۍ کاتبن تہٕ بزرگن سٍتۍ طنز کران تہٕ وونُن، \n42. تٔمۍ بچٲو باقیَن ہٕندِس سٍتـ̡ سُہ ہێکہِ نہٕ بچٲوِتھ۔ یێلہِ سُہ اسرٲیلُک بادشاہ آسہِ، تێلہِ گژھہِ سُہ صلیب پیٹھٕ بۄن تہٕ أسـ̡ أمِس پژھ کٔرِو۔ \n43. تٔمۍ کٔر خدایس پیٹھ بھروسہٕ۔ سُہ گژھہِ وُنہِ أمِس نجات دِنہٕ، یێلہِ سُہ یێلہِ أمِس نِش آسہِ، تکیازِ تٔمۍ ووٚن زِ بہٕ چُھس خدایہِ سُند نیٚچُو۔ \n44.\\tژوٗر تہِ یِم أمِس سٍتـ̡ مصلوب کٔرِتھ دِنہٕ آمٕتۍ۔ \n45. وۅنۍ اوس شیمہِ بجہ پیٹھہ نٔومہِ بجہ تام سارنٕے زمینس منز انہِ گوٚٹ۔ \n46. تہٕ نٔوِمہِ بجِہ وُن عیسیٰ علیہ السلام بَڑِ آوازِ سٍتـ̡ وۆنُن، ایلی، ایلی، لاما سبچتھانی؟ یعنی، میانہِ خدا، میانہِ خدا، ژے کیازِ تروو میہ ترک؟ \n47.\\tیِمو منزٕ کینہہ یِمو اَتہِ کھڑا ٲسۍ، ییلہ تِمو بوزان چُھ، یہِ {انسان} چُھ الیاس بلاوان۔ \n48.\\tتہٕ یِمو منزٕ اکھ ژوٚل، تہٕ لوٚگ سِرکہٕ سٍتۍ بٔرِتھ، تہٕ تھووُن أکِس سرس پیٹھ، تہٕ دِتُن أمِس چنہٕ۔ \n49.\\tباقیو ووٚن زِ اسہِ وُچھِو الیاس یِنہٕ أمِس بچاونہٕ خٲطرٕ۔ \n50.\\tعیسیٰ مسیحن ییلہ سہ بییہِ بٔڑِ آوازِ سٍتـ̡ رووُن، ترووُن بھوت۔ \n51.\\tتہٕ وُچھِو مندرُک پردہ ہیرٕ پیٹھٕ بۄن تام ژٔٹِتھ ژٔٹِتھ ۔ تہٕ زمین لٔج لٔٹِتھ تہٕ کٔنہِ پھٔٹۍ۔ \n52.\\tتہٕ قبرٕ کھولنہٕ آمٕتۍ۔ تہٕ شوٚنگِتھ شوٚنگنہٕ والٮ۪ن مقدسن ہٕنزِ واریاہ لاشہٕ گٔیہٕ، \n53.\\tتہٕ گۆو قبرو منزہ نیبر تہٕ گۆو مقدس شہرس مَنٛز، تہٕ گوو واریاہن ہٕندِس نظرس منز۔ \n54. وۅنۍ ییلہ سینچورین تہٕ تِم یِم أمِس سٍتـ̡ عیسیٰ مسیحس وُچھان ٲسۍ، زلزلہٕ وُچھمُت، تہٕ یِم چیز سپدان ٲسۍ، تِمو گٔیہِ سٮ۪ٹھاہ خوفہٕ تہٕ وونُن، پٔزۍ پٲٹھۍ اوس یہِ خدایہِ سُند نیٚچُو۔ \n55. تہٕ واریاہ زنانہٕ آسہٕ دور وُچھان، یُس گلیل پیٹھٕ عیسیٰ سٕندِ پتہٕ أمِس خدمت کران اوس: \n56. یمن منز ٲس مریم میگڈالین تہٕ جیمز تہٕ جوس سٕنز موج تہٕ زبیدی سٕندٮ۪ن شُرین ہٕنز موج تہٕ مریم تہٕ زیبدی سٕندٮ۪ن شُرین ہٕنز موج تہِ۔ \n57.\\tییلہ تہِ آو اَکھ امیر شخٕص یُس یوسف ناو اوس، یُس پانہٕ عیسیٰ سُند شٲگِر اوس۔ \n58. سُہ گوٚو پیلاطس نِش تہٕ کوٚرُن عیسیٰ سٕندِ لاشہٕ منگان۔ پَتہٕ دِیُت پیلاطس لاشہٕ دِنُک حُکُم۔ \n59.\\tتہٕ ییلہ یوسفن لاش نِتھ، تٔمۍ لٔگِتھ صاف کُنہِ پلوس مَنٛز ؤلِتھ، \n60.\\tتہٕ تھووُن سُہ پننِس نٔوِس قبرس منز، یُس تٔمۍ کٔنہِ پتھرِ منز ژٔٹِتھ اوس، تہٕ تٔمۍ ووٚتھ قبر کِس دروازس پیٹھ اکھ بوٚڈ کنہِ، تہٕ درٛاو درٛاو۔ \n61.\\tتہِ ٲس مریم مگدلینی تہ بیاکھ مریم قبرس پیٹھ بِہتھ۔ \n62. وُنہِ دوٚیمہِ دۅہ، یُس تیٲری ہٕندِس دۅہہٕ پتہٕ، سردار پادٕرۍ تہٕ فریسی گٔیہِ اِکہٕ وٹہٕ پیلاطس نِش، \n63.\\tیہ ونِتھ جناب، اسہِ یاد چھُ زِ أمِس دھوکہٕ دِنہٕ والٮ۪ن ووٚن زِ سُہ وُنہِ زندٕ آسنہٕ وِزِ تریہ دۅہہٕ پَتہٕ بہٕ وُتھٕ دُبارٕ۔ \n64. تَمہِ مۄکھٕ کٔرِو حُکُم زِ قبر گژھہِ تریمہِ دۅہہٕ تام یقینی بناونہٕ، یێلہِ تٔمۍ سٕندِ شٲگِرِ رٲژ یِن تہٕ ژوٗرِ نِن، تہٕ لُکن ؤنِن زِ سُہ چُھ مُردٕ منزٕ زندٕ گومُت، تێلہِ گژھہِ ٲخری غلطی گۅڈنِچہِ کھۅتہٕ بدتر آسہِ۔ \n65.\\tپیلاطس ووٚن تِمن وُچھِن، تہٕ پٔکِو پَنٕنـ̡ پَنٕنـ̡ پٲٹھ \n66. تہٕ تِمو گٔیہِ تہٕ قبر کٔرِتھ کٔنِس مُہر تہٕ کٔرِتھ کٔرِتھ گٔژھ پٲٹھۍ۔","1. سبت کِس ٲخرس پیٹھ، ییلہ ہفتہٕ کس گۄڈنِکِس {دۅہ} کُن طلوع گژھن شروع گوو، مریم مگدلینی تہٕ بیاکھ مریم آیہ قبر وچھنہٕ خٲطرٕ۔ \n2. تہٕ وُچھ اَکھ بٔڈ زلزلہٕ، تکیازِ خداوند سُند فرشتہ آو اسمانہٕ پیٹھٕ بۄن، تہٕ آو تہٕ دروازٕ پیٹھٕ کٔنہِ کٔنہِ واپس لٔگِتھ تہٕ بیوٹھ اَتھ پیٹھ۔ {اوس: یا، اوس}\n3.\\tتٔمۍ سُند بُتھ اوس بجلی ہیوٗ تہٕ پوشاک اوس شینہٕ ہیوٗ سفید۔ \n4.\\tتہٕ أمِس خوفہٕ سٍتـ̡ گٔیہِ رٲچھ کٔرِتھ تہٕ گٔیہِ مٔرِتھ {انسان}۔ \n5. تہٕ فرشتن دیُت جواب تہٕ وونُن زنانہٕ زَنان، تِکیازِ بہٕ چُھس پتاہ زِ تُہۍ چھِو عیسیٰ مسیحس ژھاران یُس صلیب اوس دِنہٕ آمُت۔ \n6. سُہ چُھ نہٕ یتہِ موجود: کیازِ سُہ چُھ زندٕ گومُت، یِتھ کٔنۍ تٔمۍ ووٚنمُت۔ یێلہِ وُچھِو سُہ جاے یێتہِ خداوند اوس۔ \n7. تہٕ گژھ جلدی تہٕ پننین شاگردن ؤنِو زِ سُہ چُھ مُردٕ منزٕ زندٕ گومُت۔ تہٕ وُچھِو سُہ چُھہ تۅہہِ برونہہ کُن گلیل مَنٛز نیران۔ تتہِ وُچھِو سُہ وُچھُن: لو، مے چُھہ ژےٚ وَننہٕ آمُت۔ \n8.\\tتہٕ تِم دراو قبرِ منزٕ جلدٕے خوف تہٕ سٮ۪ٹھاہ خوشی سٍتـ̡ ۔ تہٕ ژٔلِکھ تٔمۍ سٕندِس مریدن ہٕندِس کلام اننہٕ خٲطرٕ۔ \n9.\\tتہٕ یێلہِ تِم پننین شاگردن وننہِ گٔیہِ، وُچھ عیسیٰ مسیح سمکھیوو تِمن سٍتـ̡ وونُن، سارِوٕے سلام۔ تہٕ تِمو آیہ تہٕ رٔٹِتھ أمِس کھورِ تھپھ کٔرِتھ تہٕ کٔرٕکھ أمِس پوجا کرنہٕ۔ \n10. اَمہِ پتہٕ ووٚن عیسیٰ علیہ السلام تِمن زِ خوفزدہ گژھ نہٕ: گژھ میانین باین ؤنِتھ زِ تِم گژھن گلیل تہٕ تتہِ گژھن میہ وُچھن۔ \n11.\\tوُنہِ ییلہ تِم نیران ٲسۍ، وُچھ کینہہ پہرہ دِنہٕ وٲلِس شہرس مَنٛز، تہٕ ہٲوِکھ سارِنٕے کامہِ ہٕندِس پادٕرَن ہٕندِس سٍتـ̡ ۔ \n12. تہٕ ییلہ تِم بزرگن سٍتـ̡ جمع گٔیہ، تہٕ مشورٕ کٔرِتھ دِژ تِمو فوجین واریاہ پٲنسہٕ، \n13.\\tیہ ونِتھ زِ تٔمۍ سٕندِ شٲگِر آیہ رٲژ رٲژ تہٕ ژوٗرِ نِش أسۍ شوٚنگِتھ ژوٗرِ۔ \n14. تہٕ اگر یہِ گورنر سٕندِس کنن تام واتہِ، أسۍ کٔرِو أمِس رٲضی تہٕ تۅہہِ رٲچھ کٔرِتھ۔ \n15.\\tتہ تِمو رٔٹۍ پونسہٕ، تہٕ یُتھ تِمن ہیچھناونہٕ آمُت اوس، تہٕ یہِ قول چُھ از تام یہودین مَنٛز عام طور وننہٕ یوان۔ \n16.\\tپَتہٕ گٔیہِ کاہ شٲگِر گلیل کُن، أکِس پہاڑس مَنٛز ییتہِ حضرت عیسیٰ علیہ السلام تِم مقرر کورمُت اوس۔ \n17.\\tتہٕ ییلہ تمو أمس وُچھ، تمو کٔر أمس پوٗزا مگر کینژَن گٔیہِ شَک۔ \n18.\\tتہٕ عیسیٰ مسیح آو تہٕ تِمن سٍتـ̡ وونُن زِ اسمانس تہٕ زمینس مَنٛز چُھہ میہ سورے طاقت دِنہٕ آمُت۔ \n19. تێمہِ کِنۍ گژھِو تہٕ سارنٕے قومن ہیچھناوُن، تہٕ تِمن بپتسمہ دِیُن مٲلِس سٕندِس ناوس سٍتـ̡ تہٕ نیچو سٕندِس ناوس سٍتـ̡ بپتسمہ دِن: {ہیچھناوُن...: یا، بَنٲیِو سارنٕے قومن ہٕندِس عیسٲے سٍتـ̡\n20.\\tتِمن ہیچھناوُن یُس میہ تۅہہ حکم دِژمُت چُھ، تہٕ بہٕ چُھس ژے سٍتـ̡ ہمیشہٕ، {حتیٰ کہ} دُنیا کِس اندس تام۔ آمین۔"];
